import type { CultureArticle } from "../types";

const items: CultureArticle[] = [{"id":"asa-006","version":2,"slug":"gaokao-three-days-that-can-decide-a-family-s-next-decade","contentType":"feature","category":"work-and-education","title":{"ar":"غاوكاو: ثلاثة أيام قد تحدد عقدًا من حياة أسرة","de":"Gaokao: Drei Tage, die ein Jahrzehnt prägen","en":"Gaokao: Three Days That Can Shape a Decade"},"deck":{"ar":"في الصين، يتحول امتحان الجامعة إلى حدث وطني تعيد الأسر ترتيب حياتها حوله.","de":"In China wird die Universitätsaufnahmeprüfung zum nationalen Ereignis, um das Familien ihr Leben neu ordnen.","en":"In China, the university entrance exam becomes a national event around which families reorganize their lives."},"teaser":{"ar":"كل يونيو، يعيش أكثر من عشرة ملايين طالب أيامًا مصيرية، وتتحول البيوت إلى خلايا دعم صامتة.","de":"Jeden Juni sitzen über zehn Millionen Kandidaten eine Prüfung, die Familien zu stillen Support-Zellen macht.","en":"Every June, over ten million candidates sit an exam that turns households into quiet support cells."},"readingMinutes":1,"sections":{"ar":[{"heading":"امتحان يعيد ترتيب الحياة اليومية","paragraphs":["في كل شهر يونيو، يجلس أكثر من عشرة ملايين مرشح لامتحان الجامعة الوطني، المعروف باسم غاوكاو. ليس مجرد اختبار أكاديمي، بل لحظة تعيد ترتيب حياة الأسرة بأكملها. تغلق المدارس أبوابها لأسبوع المراجعة، تأخذ الأمهات إجازة من العمل، وتتحول غرف النوم إلى مساحات صامتة للتركيز.","في إحدى مدارس المقاطعات الثانوية، يُغلق المبنى بالكامل خلال أسبوع المراجعة. أم تترك عملها لتطبخ، وجدة تزور معبدًا صباح الامتحان طلبًا للحظ. هذه الطقوس الصغيرة تعكس كيف يصبح الامتحان شأنًا عائليًا جماعيًا، لا فرديًا."]},{"heading":"الدرجات والحصص الإقليمية","paragraphs":["تُقرن الدرجات بحصص المقاطعات ونظام تطوع مرتب، لذا تعتمد فرصة الطالب في جامعة مرموقة بشدة على مكان تسجيل الأسرة. هذا الواقع يخلق تفاوتًا واضحًا بين الأقاليم، ويغذي نقاشًا ساخنًا حول عدم المساواة في نظام هوكو.","تختلف قواعد القبول والمواد والمنافسة من مقاطعة لأخرى، وتتغير كثيرًا. بعض المقاطعات أدخلت نماذج جديدة لاختيار المواد، لكن الامتحان يظل الطريق الرئيسي إلى الجامعات النخبوية. المسارات المهنية والخارجية تنمو كبدائل، لكنها لا تزال محدودة."]},{"heading":"ضغط يخلق صناعة وقلقًا","paragraphs":["أدى حجم الرهان إلى ظهور صناعة ضخمة لمدارس الدروس الخصوصية، وإلى جدل متصاعد حول ضغط الامتحان وأثره على الطلاب. في كل عام، تنتشر مشاهد الآباء الذين يرافقون أبناءهم إلى قاعات الامتحان، والشرطة التي تنظم المرور قرب المراكز.","مع ذلك، تختلف النظرة إلى الامتحان بين الأجيال والمناطق. فبينما تعتبره بعض الأسر نقطة تحول حاسمة، تنظر أسر أخرى إليه كفرصة من بين عدة فرص، خاصة مع تنوع المسارات المتاحة اليوم."]}],"de":[{"heading":"Eine Prüfung ordnet den Alltag neu","paragraphs":["Jeden Juni nehmen mehr als zehn Millionen Kandidaten an der nationalen Universitätsaufnahmeprüfung teil, dem Gaokao. Es ist nicht nur ein akademischer Test, sondern ein Moment, der das Leben einer ganzen Familie neu ordnet. Schulen schließen für die Wiederholungswoche, Mütter nehmen Urlaub von der Arbeit, und Schlafzimmer werden zu stillen Konzentrationsräumen.","An einer Kreisoberschule wird das gesamte Gebäude während der Wiederholungswoche geschlossen. Eine Mutter nimmt sich frei, um zu kochen, und eine Großmutter besucht am Morgen der Prüfung einen Tempel für Glück. Diese kleinen Rituale zeigen, wie die Prüfung zu einer kollektiven Familienangelegenheit wird, nicht zu einer individuellen."]},{"heading":"Punkte und Provinzquoten","paragraphs":["Die Ergebnisse werden mit Provinzquoten und einem rangbasierten Freiwilligensystem kombiniert, sodass die Chance eines Schülers auf eine Spitzenuniversität stark davon abhängt, wo die Familie registriert ist. Diese Realität schafft deutliche Unterschiede zwischen den Regionen und befeuert eine hitzige Debatte über die Ungleichheit des Hukou-Systems.","Zulassungsregeln, Fächer und Wettbewerb unterscheiden sich von Provinz zu Provinz und ändern sich häufig. Einige Provinzen haben neue Modelle zur Fächerwahl eingeführt, doch die Prüfung bleibt der Hauptweg zu Eliteuniversitäten. Berufliche und ausländische Wege wachsen als Alternativen, bleiben aber begrenzt."]},{"heading":"Druck schafft Industrie und Sorgen","paragraphs":["Die hohen Einsätze haben eine riesige Industrie von Nachhilfeschulen hervorgebracht und eine wachsende Debatte über Prüfungsstress und seine Auswirkungen auf Schüler ausgelöst. Jedes Jahr verbreiten sich Bilder von Eltern, die ihre Kinder zu den Prüfungssälen begleiten, und von Polizisten, die den Verkehr in der Nähe der Zentren regeln.","Dennoch unterscheidet sich die Sicht auf die Prüfung zwischen Generationen und Regionen. Während einige Familien sie als entscheidenden Wendepunkt betrachten, sehen andere sie als eine von mehreren Chancen, besonders angesichts der heutigen Vielfalt an Bildungswegen."]}],"en":[{"heading":"An Exam That Rearranges Daily Life","paragraphs":["Every June, more than ten million candidates sit the national university entrance examination, known as the gaokao. It is not just an academic test but a moment that rearranges an entire family's life. Schools close for revision week, mothers take leave from work, and bedrooms become silent spaces for focus.","In a county high school, the whole building is closed for revision week; a mother takes leave from work to cook, and a grandmother visits a temple for luck on the morning of the exam. These small rituals show how the exam becomes a collective family affair, not an individual one."]},{"heading":"Scores and Provincial Quotas","paragraphs":["Scores are paired with provincial quotas and a ranked volunteer system, so a student's chance of a top university depends heavily on where the family is registered. This reality creates stark differences between regions and fuels heated debate about hukou inequality.","Admission rules, subjects and competition differ by province and change frequently. Some provinces have introduced new subject-selection models, but the exam remains the main route into elite universities. Vocational and overseas routes are growing alternatives, though they remain limited."]},{"heading":"Pressure Creates Industry and Anxiety","paragraphs":["The high stakes have created a vast cram-school industry and heated debate about exam stress and its impact on students. Every year, scenes spread of parents escorting children to the hall and police directing traffic near test centres.","Yet views on the exam vary across generations and regions. While some families see it as a decisive turning point, others regard it as one opportunity among several, especially given the growing diversity of educational paths today."]}]},"context":{"countries":["CN"],"region":"China","continent":"asia","languages":["zh"],"period":"contemporary"},"tags":["work-and-education","China"],"sources":[{"organization":"Wikipedia","title":{"ar":"Gaokao","de":"Gaokao","en":"Gaokao"},"url":"https://en.wikipedia.org/wiki/Gaokao","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Education in China","de":"Education in China","en":"Education in China"},"url":"https://en.wikipedia.org/wiki/Education_in_China","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مدرسة ثانوية بمقاطعة صينية، يُغلق المبنى بالكامل خلال أسبوع المراجعة؛ تأخذ الأم إجازة من العمل لتطبخ، وتزور الجدة معبدًا صباح الامتحان طلبًا للحظ.","de":"An einer Kreisoberschule in China wird das gesamte Gebäude während der Wiederholungswoche geschlossen; eine Mutter nimmt sich frei, um zu kochen, und eine Großmutter besucht am Prüfungsmorgen einen Tempel für Glück.","en":"In a county high school the whole building is closed for revision week; a mother takes leave from work to cook, and a grandmother visits a temple for luck on the morning of the exam."},"misunderstanding":{"ar":"الاعتقاد بأن غاوكاو يحدد مصير كل طالب بشكل مطلق. في الواقع، توجد مسارات مهنية وخارجية متزايدة، ولا تتعامل كل الأسر مع الامتحان كقرار نهائي.","de":"Die Annahme, das Gaokao bestimme das Schicksal jedes Schülers absolut. Tatsächlich gibt es zunehmend berufliche und ausländische Wege, und nicht alle Familien behandeln die Prüfung als endgültige Entscheidung.","en":"The belief that the gaokao absolutely determines every student's fate. In reality, vocational and overseas routes are growing, and not all families treat the exam as a final decision."},"comparison":{"ar":"مثل امتحانات القبول الجامعي في دول أخرى، لكن الفرق أن غاوكاو يرتبط بحصص إقليمية ونظام تسجيل الأسرة، مما يجعله أقرب إلى حدث عائلي واجتماعي شامل.","de":"Ähnlich wie Universitätsaufnahmeprüfungen in anderen Ländern, doch der Unterschied ist die Verbindung mit Provinzquoten und dem Familienregistrierungssystem, was es zu einem umfassenden familiären und sozialen Ereignis macht.","en":"Like university entrance exams in other countries, but the difference is its link to provincial quotas and the family registration system, making it a comprehensive family and social event."}},{"id":"asa-007","version":2,"slug":"meshrep-the-uyghur-gathering-that-taught-music-manners-and-community","contentType":"feature","category":"traditions","title":{"ar":"مەشرەپ: مجلس يجمع الغناء والأدب والأخلاق","de":"Meshrep: das Fest, das Musik und Manieren lehrt","en":"Meshrep: the gathering that taught music and manners"},"deck":{"ar":"كيف تحوّل تجمّع الجيران إلى مدرسة للسلوك والموسيقى بين الأويغور.","de":"Wie ein Nachbarschaftstreffen bei den Uiguren zur Schule des Benehmens und der Lieder wird.","en":"How a neighbourhood assembly among Uyghurs became a school for behaviour and song."},"teaser":{"ar":"في ساحات القرى، يجتمع الأويغور على الموسيقى والنصح، حيث يتعلم الشباب الأدب من كبار السن. تعرّف على المەشرەپ.","de":"In Innenhöfen kommen Uiguren zu Musik und Ermahnung zusammen. Alte lehren Junge, und Lieder tragen Werte weiter. Ein Blick auf den Meshrep.","en":"In courtyards across Xinjiang, Uyghurs gather for music and moral guidance. Elders correct, youth learn, and songs carry values forward. Meet the meshrep."},"readingMinutes":2,"sections":{"ar":[{"heading":"ما هو المەشرەپ؟","paragraphs":["المەشرەپ هو تجمّع مجتمعي عند الأويغور في شينجيانغ، يجمع بين الموسيقى والرقص والطعام والشعر والتوجيه الأخلاقي. الكلمة نفسها توحي باجتماع احتفالي، حيث يلتقي الجيران والأقارب في فناء أو ساحة، ويتبادلون أطباق الطعام ويستمعون إلى أغانٍ تُعزف على الدوتار. وفي هذه الأجواء، لا يكون الترفيه منفصلاً عن التربية: فكبار السن يوجّهون سلوك الصغار، والشباب يتعلمون الأغاني وآداب المجلس من خلال المشاركة الفعلية.","وقد أدرجت اليونسكو المەشرەپ في قائمة التراث الثقافي غير المادي عام 2010، واصفة إياه بأنه وسيلة لنقل القيم الاجتماعية. وتُقام هذه المجالس تقليدياً في الأعراس وأعياد الحصاد والمناسبات المجاورة، حيث يتولى وجهاء الحي تصحيح السلوك وتلقين العادات. وبهذا المعنى، فهو ليس حفلاً عابراً، بل مؤسسة اجتماعية غير رسمية تُرسّخ الانتماء واللغة والتقاليد."]},{"heading":"كيف يعمل في الحياة اليومية","paragraphs":["في عرس قروي، يُقام المەشرەپ في الفناء: يعزف عازف الدوتار الأغاني، وينشد كبار السن الأمثال والحِكم، ويُشجَّع الضيوف الشباب على الرقص. هذا المشهد يوضح كيف يتحول المنزل أو الساحة إلى مسرح للتعلم، حيث يُراقب الكبار أداء الصغار ويصححون أخطاءهم بلطف أو بسخرية محببة. وتختلف تفاصيل المەشرەپ باختلاف المناسبة والمنطقة، لكن جوهره يبقى اجتماعاً يربط الترفيه بالتهذيب.","ومنذ عام 2017، قيّدت سياسات أمنية في شينجيانغ العديد من فعاليات المەشرەپ العلنية، كما أن وصول الباحثين الأجانب إلى المنطقة محدود. وتُعقد المەشرەپ في مجتمعات الشتات الأويغوري في آسيا الوسطى وخارجها كوسيلة للحفاظ على اللغة والهوية. وهنا تبرز صعوبة التعميم: فالتقارير الرسمية الصينية تؤكد حماية الثقافة، بينما تصف منظمات حقوقية قيوداً، ما يجعل التفاصيل متباينة حسب المصدر."]},{"heading":"بين الاحتفال والقيود","paragraphs":["يكشف المەشرەپ عن وظيفة اجتماعية أوسع من مجرد الاحتفال: فهو آلية لضبط السلوك ونقل المعرفة الشفهية. فالأمثال التي يرددها الكبار ليست زخرفة، بل دروس في الكرم واحترام الجيران وحل الخلافات. ولهذا فإن أي تغيير في إقامته يؤثر على طريقة تعلّم الشباب لهذه القيم.","وفي مجتمعات الشتات، يعيد المهاجرون إنتاج المەشرەپ بأشكال جديدة، أحياناً في قاعات مدنية أو عبر تجمعات عائلية، ما يدل على مرونة هذا التقليد وقدرته على التكيف مع بيئات مختلفة. ومع ذلك، تبقى نسخته الأصلية مرتبطة بالمكان والذاكرة الجماعية."]}],"de":[{"heading":"Was ist der Meshrep?","paragraphs":["Der Meshrep ist ein Gemeinschaftstreffen der Uiguren in Xinjiang, das Musik, Tanz, Essen, Poesie und moralische Unterweisung verbindet. Das Wort selbst deutet auf eine festliche Versammlung hin: Nachbarn und Verwandte treffen sich in einem Hof oder auf einem Platz, tauschen Speisen aus und hören Liedern zu, die auf der Dutar gespielt werden. Unterhaltung und Erziehung sind dabei nicht getrennt – Ältere korrigieren das Verhalten der Jüngeren, und junge Leute lernen Lieder und Umgangsformen, indem sie mitmachen.","Die UNESCO nahm den Meshrep 2010 in die Liste des immateriellen Kulturerbes auf und beschrieb ihn als ein Mittel zur Weitergabe sozialer Werte. Traditionell findet er bei Hochzeiten, Ernten und Nachbarschaftsfesten statt, wobei Älteste das Benehmen korrigieren und junge Menschen Lieder und Manieren lernen. In diesem Sinne ist er keine flüchtige Feier, sondern eine informelle soziale Institution, die Zugehörigkeit, Sprache und Tradition festigt."]},{"heading":"Wie er im Alltag funktioniert","paragraphs":["Bei einer Dorfhochzeit findet der Meshrep im Innenhof statt: Ein Dutar-Spieler stimmt Lieder an, ältere Männer tragen Sprichwörter vor, und junge Gäste werden zum Tanzen ermuntert. Diese Szene zeigt, wie ein Haus oder Hof zur Bühne des Lernens wird, auf der Ältere die Darbietungen der Jüngeren beobachten und Fehler freundlich oder mit liebevollem Spott korrigieren. Die Einzelheiten des Meshrep unterscheiden sich je nach Anlass und Region, doch sein Kern bleibt ein Zusammenkommen, das Unterhaltung mit Erziehung verbindet.","Seit 2017 werden viele öffentliche Meshrep-Veranstaltungen in Xinjiang durch Sicherheitsmaßnahmen eingeschränkt, und ausländische Forscher haben nur begrenzten Zugang zur Region. In der uigurischen Diaspora in Zentralasien und darüber hinaus wird der Meshrep gepflegt, um Sprache und Identität zu bewahren. Hier zeigt sich, wie schwierig Verallgemeinerungen sind: Chinesische Quellen betonen den Kulturschutz, während uigurische und Menschenrechtsgruppen Einschränkungen beschreiben – die Details unterscheiden sich je nach Quelle."]},{"heading":"Zwischen Feier und Einschränkung","paragraphs":["Der Meshrep verweist auf eine soziale Funktion, die über das Feiern hinausgeht: Er ist ein Mechanismus, um Verhalten zu regulieren und mündliches Wissen weiterzugeben. Die Sprichwörter der Älteren sind keine Dekoration, sondern Lektionen in Großzügigkeit, Respekt vor Nachbarn und Konfliktlösung. Ändert sich die Art, wie er stattfindet, wirkt sich das darauf aus, wie junge Menschen diese Werte lernen.","In der Diaspora wird der Meshrep in neuen Formen wiederbelebt, manchmal in Gemeindesälen oder bei Familientreffen. Das zeigt die Flexibilität dieser Tradition und ihre Fähigkeit, sich an verschiedene Umgebungen anzupassen. Dennoch bleibt die ursprüngliche Form an den Ort und das kollektive Gedächtnis gebunden."]}],"en":[{"heading":"What the meshrep is","paragraphs":["Meshrep is a community gathering among the Uyghurs of Xinjiang that combines music, dance, food, poetry and moral instruction. The word itself suggests a festive assembly: neighbours and relatives meet in a courtyard or square, share dishes and listen to songs played on the dutar. Entertainment and upbringing are not separated – elders correct the behaviour of younger people, and the young learn songs and manners by taking part.","UNESCO added the meshrep to its intangible cultural heritage list in 2010, describing it as a vehicle for transmitting social values. Traditionally it is held for weddings, harvests and neighbourhood events, with elders correcting behaviour and young people learning songs and manners. In this sense it is not a fleeting party but an informal social institution that anchors belonging, language and tradition."]},{"heading":"How it works in daily life","paragraphs":["At a village wedding, a meshrep takes place in a courtyard: a dutar player leads songs, older men recite proverbs, and young guests are teased into dancing. The scene shows how a home or yard becomes a stage for learning, where elders watch the performances of the young and correct mistakes with kindness or affectionate mockery. The details of meshrep vary by occasion and region, but its core remains a gathering that ties entertainment to upbringing.","Since 2017 many public meshrep events have been restricted under security policies in Xinjiang, and outside researchers have limited access to the region. Uyghur diaspora communities in Central Asia and beyond hold meshrep as a way of maintaining language and identity. Here the difficulty of generalisation becomes clear: official Chinese sources emphasise cultural protection, while Uyghur and human-rights groups describe restrictions, so details vary by source."]},{"heading":"Between celebration and restriction","paragraphs":["The meshrep points to a social function that goes beyond celebration: it is a mechanism for regulating behaviour and passing on oral knowledge. The proverbs recited by elders are not decoration but lessons in generosity, respect for neighbours and conflict resolution. Any change in how it is held affects how young people learn these values.","In diaspora communities, migrants recreate the meshrep in new forms, sometimes in community halls or family gatherings, which shows the flexibility of the tradition and its ability to adapt to different settings. Yet its original form remains tied to place and collective memory."]}]},"context":{"countries":["CN"],"region":"Xinjiang","community":"Uyghur","continent":"asia","languages":["ug"],"period":"contemporary"},"tags":["traditions","Xinjiang","Meshrep is","It was"],"sources":[{"organization":"Wikipedia","title":{"ar":"Meshrep","de":"Meshrep","en":"Meshrep"},"url":"https://en.wikipedia.org/wiki/Meshrep","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Uyghurs","de":"Uyghurs","en":"Uyghurs"},"url":"https://en.wikipedia.org/wiki/Uyghurs","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في عرس قروي، يُقام المەشرەپ في الفناء: يعزف عازف الدوتار الأغاني، وينشد كبار السن الأمثال، ويُشجَّع الضيوف الشباب على الرقص.","de":"Bei einer Dorfhochzeit findet der Meshrep im Innenhof statt: Ein Dutar-Spieler stimmt Lieder an, ältere Männer tragen Sprichwörter vor, und junge Gäste werden zum Tanzen ermuntert.","en":"At a village wedding, a meshrep takes place in a courtyard: a dutar player leads songs, older men recite proverbs, and young guests are teased into dancing."},"misunderstanding":{"ar":"ليس المەشرەپ حفلاً فنياً معزولاً عن الحياة اليومية، بل مجلس يمارس فيه الكبار سلطة أخلاقية ويصححون سلوك الصغار.","de":"Der Meshrep ist keine isolierte künstlerische Veranstaltung, sondern ein Treffen, bei dem Ältere moralische Autorität ausüben und das Verhalten Jüngerer korrigieren.","en":"The meshrep is not an isolated artistic event but an assembly where elders exercise moral authority and correct the behaviour of the young."},"comparison":{"ar":"يشبه المەشرەپ مجالس السمر في مجتمعات أخرى حيث يُستخدم الغناء لتلقين القيم، لكنه يتميز بدمج التوجيه الأخلاقي المباشر في صميم الاحتفال.","de":"Der Meshrep ähnelt abendlichen Zusammenkünften in anderen Gesellschaften, bei denen Lieder Werte vermitteln, doch er verbindet direkte moralische Unterweisung mit dem Fest selbst.","en":"The meshrep resembles evening gatherings in other societies where songs transmit values, but it folds direct moral instruction into the heart of the celebration itself."}},{"id":"asa-008","version":2,"slug":"keigo-three-layers-of-politeness-inside-one-japanese-sentence","contentType":"language","category":"languages","title":{"ar":"الكيغو: ثلاث طبقات من الأدب في جملة يابانية","de":"Keigo: Drei Höflichkeitsebenen in einem japanischen Satz","en":"Keigo: Three Layers of Politeness in One Japanese Sentence"},"deck":{"ar":"نظام لغوي يعكس التسلسل الاجتماعي والعلاقات بين المتحدثين.","de":"Ein sprachliches System, das soziale Hierarchien und Beziehungen widerspiegelt.","en":"A linguistic system that reflects social hierarchy and relationships between speakers."},"teaser":{"ar":"في اليابان، تتغير الكلمات حسب من تخاطب، فتظهر ثلاثة مستويات من الأدب داخل جملة واحدة.","de":"In Japan ändern sich die Wörter je nach Gesprächspartner, und drei Höflichkeitsstufen erscheinen in einem einzigen Satz.","en":"In Japan, words change depending on whom you address, and three levels of politeness appear within a single sentence."},"readingMinutes":1,"sections":{"ar":[{"heading":"ثلاثة مستويات في جملة واحدة","paragraphs":["تحتوي اللغة اليابانية على نظام أدب يُسمى «كيغو»، وله ثلاثة مستويات رئيسية: سونكيغو لرفع شأن المستمع، وكنجوغو لتواضع المتحدث، وتيينيغو للأدب العام.","يتغير شكل الفعل نفسه: «إيكو» (يذهب) يصبح «مايريماسو» عند التواضع، و«إيراشايماسو» عند احترام الآخر.","يُعد كيغو التجاري لغة ثانية لكثير من الموظفين الجدد، الذين يتلقون تدريبًا ويستخدمون كتيبات، وتُعد الأخطاء مصدر إحراج شائع في العمل."]},{"heading":"التواضع والاحترام في العلاقات","paragraphs":["يرتبط النظام بمفهوم «أوتشي-سوتو»: يتحدث المرء بتواضع عن مجموعته وباحترام عن الغرباء، لذا قد يستخدم الشخص نفسه صيغًا مختلفة مع زميل ومع عميل.","يستخدم المتحدثون الأصغر سنًا وموظفو الخدمة أسلوبًا مهذبًا مبسطًا، ويتجادل اللغويون حول ما إذا كان كيغو يتراجع أم يتغير فحسب.","يختلف الاستخدام حسب المنطقة والشركة والجيل، وقد تبدو المبالغة في الأدب ساخرة أو باردة بين الزملاء المقربين."]}],"de":[{"heading":"Drei Ebenen in einem Satz","paragraphs":["Die japanische Sprache kennt ein Höflichkeitssystem namens Keigo mit drei Hauptregistern: Sonkeigo zur Erhöhung des Hörers, Kenjōgo zur Bescheidenheit des Sprechers und Teineigo für allgemeine Höflichkeit.","Dieselbe Handlung ändert ihre Form: iku (gehen) wird zu mairimasu beim Bescheiden und zu irasshaimasu beim Respektieren.","Business-Keigo ist für viele Neulinge eine zweite Sprache; sie nehmen an Schulungen teil und nutzen Handbücher, und Fehler sind eine häufige Quelle von Peinlichkeiten am Arbeitsplatz."]},{"heading":"Bescheidenheit und Respekt in Beziehungen","paragraphs":["Das System ist mit Uchi-Soto verbunden: Man spricht bescheiden über die eigene Gruppe und respektvoll über Außenstehende, sodass dieselbe Person gegenüber einem Kollegen und einem Kunden unterschiedliche Formen verwendet.","Jüngere Sprecher und Servicekräfte nutzen oft einen vereinfachten höflichen Stil, und Linguisten diskutieren, ob Keigo verfällt oder sich einfach verändert.","Die Verwendung variiert je nach Region, Unternehmen und Generation, und übermäßige Förmlichkeit kann unter engen Kollegen ironisch oder kalt wirken."]}],"en":[{"heading":"Three Levels in One Sentence","paragraphs":["Japanese has an honorific system called keigo with three main registers: sonkeigo for elevating the listener, kenjōgo for humbling the speaker, and teineigo for general politeness.","The same action changes shape: iku (go) becomes mairimasu when humbling oneself and irasshaimasu when respecting the other person.","Business keigo is a second language for many recruits, who attend training and use manuals; errors are a common source of workplace embarrassment."]},{"heading":"Humility and Respect in Relationships","paragraphs":["The system is entwined with uchi-soto: one speaks humbly about one's own group and respectfully about outsiders, so the same person may use different forms with a colleague and a client.","Younger speakers and service staff often use a simplified polite style, and linguists debate whether keigo is declining or simply changing.","Usage varies by region, company and generation, and over-formality can sound ironic or cold between close colleagues."]}]},"context":{"countries":["JP"],"region":"Japan","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["languages","Japan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Japanese honorifics","de":"Japanese honorifics","en":"Japanese honorifics"},"url":"https://en.wikipedia.org/wiki/Japanese_honorifics","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Honorific speech in Japanese","de":"Honorific speech in Japanese","en":"Honorific speech in Japanese"},"url":"https://en.wikipedia.org/wiki/Honorific_speech_in_Japanese","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"موظفة جديدة ترد على الهاتف بعبارة «أوسيوا ني ناتي أورييماسو»، ثم تنتقل إلى صيغ التواضع عند الحديث عن مديرها.","de":"Eine neue Mitarbeiterin beantwortet das Telefon mit osewa ni natte orimasu und wechselt dann zu bescheidenen Formen, als sie über ihren eigenen Manager spricht.","en":"A new employee answers the phone with osewa ni natte orimasu, then switches to humble forms when speaking about her own manager."},"misunderstanding":{"ar":"يُفهم كيغو أحيانًا كنظام ثابت، لكنه في الواقع يتغير حسب السياق والعلاقة.","de":"Keigo wird manchmal als starres System missverstanden, ist aber kontext- und beziehungsabhängig.","en":"Keigo is sometimes misunderstood as a fixed code, but it is context- and relationship-dependent."},"comparison":{"ar":"يشبه كيغو استخدام صيغ المخاطبة في لغات أخرى، لكنه أكثر تعقيدًا وتداخلاً مع العلاقات الاجتماعية.","de":"Keigo ähnelt der Verwendung von Anredeformen in anderen Sprachen, ist aber komplexer und stärker mit sozialen Beziehungen verwoben.","en":"Keigo resembles the use of address forms in other languages, but is more complex and intertwined with social relationships."},"expression":{"original":"お世話になっております","language":"日本語","gloss":{"ar":"شكرًا لدعمكم المستمر - تحية العمل القياسية","de":"Vielen Dank für Ihre fortwährende Unterstützung – die Standard-Begrüßung im Geschäftsleben","en":"Thank you for your continued support - the standard business greeting"},"usage":{"ar":"تُستخدم في بداية المحادثات التجارية، خاصة على الهاتف أو في البريد الإلكتروني.","de":"Wird zu Beginn geschäftlicher Gespräche verwendet, besonders am Telefon oder in E-Mails.","en":"Used at the start of business conversations, especially on the phone or in emails."},"transliteration":"osewa ni natte orimasu"}},{"id":"asa-009","version":2,"slug":"aizuchi-the-small-noises-that-prove-a-japanese-listener-is-still-there","contentType":"note","category":"communication","title":{"ar":"آيزوتشي: أصوات صغيرة تُثبت أن المستمع ما زال معك","de":"Aizuchi: die kleinen Laute, die Zuhören sichtbar machen","en":"Aizuchi: the small noises that prove a listener is there"},"deck":{"ar":"في المحادثات اليابانية، يملأ المستمع الفراغ بإيماءات وكلمات قصيرة مثل «هاي» و«سو ديسو ني»، لا اتفاقاً بل إصغاءً.","de":"Im japanischen Gespräch füllt die zuhörende Person Pausen mit «hai», «ee» oder «sō desu ne» – Zeichen der Aufmerksamkeit, nicht der Zustimmung.","en":"In Japanese conversation, listeners fill the gaps with hai, ee and sō desu ne — signals of attention rather than agreement, and easy for visitors to misread."},"teaser":{"ar":"كيف تعرف أن من أمامك يستمع فعلاً؟ في اليابان يجيبون بأصوات صغيرة متكررة، وقد يخطئ الزائر فيقرأها موافقةً.","de":"Woran erkennt man, dass jemand wirklich zuhört? In Japan durch kurze, häufige Laute, die Besucher leicht als Einverständnis missverstehen.","en":"How do you know someone is still listening? In Japan, with short, frequent sounds that visitors often mistake for consent."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما يقوله المستمع دون أن يقاطع","paragraphs":["الآيزوتشي هي تلك التعجبات والإيماءات المتكررة التي يصدرها المستمع أثناء حديث الآخر: «هاي»، «إي»، «سو ديسو ني». وهي إشارات انتباه ومشاركة، لا موافقة على ما يُقال.","يستخدمها المتحدثون باليابانية أكثر بكثير من مستخدمي الإنجليزية في محادثات مشابهة، وهذا فرق في الإيقاع لا في الأدب وحده.","يختلف تكرارها وشكلها بحسب المنطقة والعمر والجنس، كما غيّرت مكالمات الفيديو سرعتها؛ والإفراط فيها مع الأصدقاء المقربين قد يبدو مسرحياً."]},{"heading":"سوء فهم شائع في اللقاءات","paragraphs":["قد يضلّل هذا العادة الزائرَ: مستمع يردد «نعم، نعم» ربما يتابع الحكاية فقط، لا يوافق على اقتراح.","على الهاتف تُدار الآيزوتشي بطريقة مختلفة، إذ يُقرأ الصمت الأطول احتمالاً لانقطاع الخط.","لذلك صار معلمو اللغة يعلّمون إنتاجها وتفسيرها معاً، لأن غيابها قد يجعل المتحدث يبدو بارداً أو معادياً."]}],"de":[{"heading":"Was Zuhören hörbar macht","paragraphs":["Aizuchi sind die häufigen Zwischenrufe und Nicken – hai, ee, sō desu ne –, mit denen eine zuhörende Person das Sprechen der anderen begleitet. Sie signalisieren Aufmerksamkeit und Beteiligung, nicht Zustimmung.","Japanischsprechende verwenden sie in vergleichbaren Gesprächen viel häufiger als Englischsprechende; das verändert den Rhythmus, nicht nur die Höflichkeit.","Häufigkeit und Form unterscheiden sich je nach Region, Alter und Geschlecht, und Videoanrufe haben den Takt verändert; bei engen Freunden kann zu viel Aizuchi theatralisch wirken."]},{"heading":"Ein verbreitetes Missverständnis","paragraphs":["Besucher können dadurch in die Irre geführt werden: Wer «ja, ja» sagt, folgt vielleicht nur der Erzählung und stimmt keinem Vorschlag zu.","Am Telefon wird Aizuchi anders gehandhabt, weil längere Stille dort eher als abgebrochene Verbindung gelesen wird.","Sprachlehrkräfte unterrichten deshalb inzwischen sowohl das Hervorbringen als auch das Deuten von Aizuchi, denn seine Abwesenheit kann kühl oder feindselig wirken."]}],"en":[{"heading":"What listening sounds like","paragraphs":["Aizuchi are the frequent interjections and nods — hai, ee, sō desu ne — that a listener makes while another person speaks. They signal attention and participation rather than agreement.","Japanese speakers use them far more often than English speakers in comparable conversations, which changes the rhythm rather than just the politeness.","Frequency and form vary by region, age and gender, and video calls have changed the pace; overusing aizuchi with close friends can sound theatrical."]},{"heading":"A common misunderstanding","paragraphs":["The habit can mislead visitors: a listener saying yes, yes may be following the story, not consenting to a proposal.","On the phone aizuchi are managed differently, since longer silence is more likely to be read as the line dropping.","Language teachers now explicitly teach both producing and interpreting aizuchi, since its absence can make a speaker seem cold or hostile."]}]},"context":{"countries":["JP"],"region":"Japan","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["communication","Japan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Aizuchi","de":"Aizuchi","en":"Aizuchi"},"url":"https://en.wikipedia.org/wiki/Aizuchi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Backchannel (linguistics)","de":"Backchannel (linguistics)","en":"Backchannel (linguistics)"},"url":"https://en.wikipedia.org/wiki/Backchannel_(linguistics)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مكالمة فيديو، يواصل مدير في طوكيو تمتمة «سو ديسو ني» بينما يشرح مورّد ألماني تأخيراً؛ يكتشف المورّد لاحقاً أن التمتمة تعني «أنا أسمع»، لا «أنا أوافق».","de":"In einem Videoanruf murmelt ein Manager in Tokio wiederholt «sō desu ne», während ein deutscher Lieferant eine Verzögerung erklärt; später erfährt der Lieferant, dass das Murmeln «ich höre zu» bedeutete, nicht «ich stimme zu».","en":"On a video call a Tokyo manager keeps murmuring sō desu ne while a German supplier explains a delay; the supplier later learns the murmurs meant I am listening, not I agree."},"misunderstanding":{"ar":"الاعتقاد بأن «هاي» تعني دائماً الموافقة أو القبول، بينما هي في كثير من المواقف مجرد إشارة إلى أن المستمع يتابع.","de":"Die Annahme, «hai» bedeute immer Zustimmung oder Einwilligung, obwohl es oft nur zeigt, dass die zuhörende Person der Erzählung folgt.","en":"Assuming that hai always means agreement or consent, when it often only shows that the listener is following the story."},"comparison":{"ar":"في محادثة إنجليزية قد يُترك الصمت ليحمل معنى الإصغاء، أما في اليابانية فيُملأ الفراغ بأصوات قصيرة متتابعة تحفظ استمرار الحوار.","de":"Im englischen Gespräch darf Stille das Zuhören tragen; im japanischen wird die Lücke mit kurzen, wiederkehrenden Lauten gefüllt, die das Gespräch in Gang halten.","en":"In English conversation, silence can carry the listening; in Japanese, the gap is filled with short repeated sounds that keep the exchange moving."},"expression":{"original":"そうですね","language":"日本語","gloss":{"ar":"هذا صحيح، أليس كذلك؟ إشارة إصغاء شائعة","de":"das stimmt, nicht wahr – ein häufiges Hörsignal","en":"that's right, isn't it — a common listening backchannel"},"usage":{"ar":"تُقال أثناء حديث الآخر لتأكيد المتابعة، لا لإعلان الموافقة على رأيه.","de":"Wird während des Sprechens der anderen Person gesagt, um Aufmerksamkeit zu zeigen, nicht um einer Meinung zuzustimmen.","en":"Said while another person speaks to show you are following, not to declare agreement with their view."},"transliteration":"sō desu ne"}},{"id":"asa-010","version":2,"slug":"senpai-and-kohai-how-a-graduation-year-organises-japanese-daily-life","contentType":"feature","category":"social-behaviour","title":{"ar":"سيمباي وكوهاي: سنة التخرج تنظّم اليوم","de":"Senpai und Kōhai: das Eintrittsjahr ordnet den Alltag","en":"Senpai and kōhai: a graduation year orders daily life"},"deck":{"ar":"في اليابان، من دخل قبلك يبقى سيمباي، ومن جاء بعدك كوهاي، وهذا الفارق يرتّب التحية والجلوس والكلام.","de":"Wer früher in Schule, Verein oder Firma kam, bleibt Senpai; wer später kommt, ist Kōhai. Das prägt Begrüßung, Sitzordnung und Sprache.","en":"In Japan, whoever entered a school, club or company earlier stays senpai; the later arrival is kōhai, and this shapes greetings, seating and speech."},"teaser":{"ar":"علاقة ليست رتبة جامدة فقط: الأكبر يوجّه ويحمي وأحياناً يدفع، والأصغر يخاطب بأدب ويتعلّم.","de":"Keine starre Rangordnung, sondern ein Tausch: Ältere führen und schützen, Jüngere sprechen höflich und lernen.","en":"Not a rigid rank but a trade: seniors guide and protect, juniors speak politely and learn the ropes."},"readingMinutes":1,"sections":{"ar":[{"heading":"من يدخل أولاً","paragraphs":["في اليابان، يُسمّى من التحق بالمدرسة أو النادي أو الشركة قبلك سيمباي، ويُسمّى من جاء بعدك كوهاي. هذا الفارق البسيط في سنة الدخول يرتّب تفاصيل يومية كثيرة: كيف تُلقي التحية، وأين تجلس، وبأي لغة تخاطب الآخر.","العلاقة ليست مجرد رتبة على ورقة. يُتوقّع من السيمباي أن يوجّه الأصغر ويحميه، وأحياناً أن يدفع عنه في المناسبات، بينما يستخدم الكوهاي لغة مهذّبة ويتراجع في القرارات احتراماً للتسلسل."]},{"heading":"الأندية تعلّم الترتيب","paragraphs":["في الأندية الرياضية ودوائر الجامعات، تُدار الحياة اليومية على هذا الفارق: الأصغر ينظّفون، ويقدّمون الطعام والشراب، ويخاطبون الأكبر بلقبه لا باسمه.","هذه المهام ليست عقاباً بقدر ما هي طريق دخول إلى الجماعة؛ فمن يخدم يتعلّم أصول المكان، ثم ينتقل لاحقاً إلى دور المعلّم مع من يأتي بعده.","تختلف حدّة هذا الترتيب بين المناطق والأجيال: بعض الأندية تتمسّك به بحرفية، وأخرى تخفّفه حسب مزاج الأعضاء وطبيعة المدينة."]},{"heading":"في العمل وخارجه","paragraphs":["في أماكن العمل يستمر النمط في التدريب والجلسات المسائية بعد الدوام، لكن ثقافة الشركات الناشئة والعمل عن بُعد خفّفت من صرامته.","وقد انتقل المصطلح إلى الخارج عبر المانغا والأنيمي، حيث يُستخدم سيمباي كنداء مباشر في مجتمعات الترجمة، فيصبح الكلمة جسراً بين لغتين لا مجرد لقب.","الواقع أن التسلسل أكثر تفاوضاً مما توحي الصورة النمطية؛ فالعمر وسنوات الخدمة لا يتطابقان دائماً، وكثير من الأندية والشركات صار يشجّع المرونة بدل الجمود."]}],"de":[{"heading":"Wer zuerst kommt","paragraphs":["In Japan heißt Senpai, wer früher in eine Schule, einen Verein oder eine Firma eingetreten ist; Kōhai ist der Jüngere. Dieser kleine Unterschied im Eintrittsjahr ordnet viele Alltagsdetails: wie man grüßt, wo man sitzt und in welcher Sprache man miteinander spricht.","Die Beziehung ist mehr als ein Rang auf dem Papier. Von Senpai wird erwartet, dass sie Jüngere anleiten, schützen und manchmal bezahlen; Kōhai verwenden höfliche Sprache und halten sich bei Entscheidungen zurück."]},{"heading":"Vereine lehren die Ordnung","paragraphs":["In Sportvereinen und Universitätszirkeln läuft der Alltag entlang dieser Unterscheidung: Jüngere putzen, servieren und sprechen Ältere mit Titel statt Namen an.","Diese Aufgaben sind weniger Strafe als Eintritt in die Gruppe; wer dient, lernt die Regeln des Ortes und gibt sie später an die Nächsten weiter.","Wie streng das gehandhabt wird, schwankt regional und generationell: Manche Vereine halten daran fest, andere lockern es je nach Mitgliedern und Stadt."]},{"heading":"Im Beruf und darüber hinaus","paragraphs":["Am Arbeitsplatz lebt das Muster in Einarbeitung und abendlichem Zusammensein weiter, doch Start-up-Kultur und Homeoffice haben es abgeschwächt.","Über Manga und Anime wanderte der Begriff ins Ausland, wo Senpai in Übersetzungsgemeinschaften zur direkten Anrede wird und so zur Brücke zwischen Sprachen.","Tatsächlich ist die Hierarchie verhandelbarer als das Klischee suggeriert; Alter und Betriebszugehörigkeit decken sich nicht immer, und viele Vereine und Firmen fördern Flexibilität statt Starrheit."]}],"en":[{"heading":"Who came first","paragraphs":["In Japan, someone who entered a school, club or company earlier is called senpai; the person who arrived later is kōhai. This small difference in entry year arranges many everyday details: how you greet, where you sit and in what register you speak.","The relationship is more than rank on paper. Seniors are expected to mentor, protect and sometimes pay for juniors, while juniors use polite language and defer in decisions."]},{"heading":"Clubs teach the order","paragraphs":["In sports clubs and university circles, daily life runs on this distinction: juniors clean, serve and address seniors by title rather than name.","These tasks are less punishment than a way into the group; whoever serves learns the rules of the place and later passes them on to the next arrivals.","How strictly this is applied varies by region and generation: some clubs hold to it literally, others soften it depending on members and city."]},{"heading":"At work and beyond","paragraphs":["In workplaces the pattern persists in training and after-hours socialising, though flat startup culture and remote work have weakened it.","Through manga and anime the term travelled abroad, where senpai often becomes a form of address in translation communities, turning the word into a bridge between languages.","In reality the hierarchy is more negotiated than the stereotype suggests; age and length of service do not always align, and many clubs and companies now encourage flexibility over rigidity."]}]},"context":{"countries":["JP"],"region":"Japan","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["social-behaviour","Japan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Senpai and kōhai","de":"Senpai and kōhai","en":"Senpai and kōhai"},"url":"https://en.wikipedia.org/wiki/Senpai_and_k%C5%8Dhai","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Japanese honorifics","de":"Japanese honorifics","en":"Japanese honorifics"},"url":"https://en.wikipedia.org/wiki/Japanese_honorifics","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عضو في السنة الأولى بنادي كيودو يحيّي طلاب السنة الثالثة، ويحمل أدواتهم، ويناديهم سيمباي، وفي المقابل يتلقى تدريباً ومكاناً في روتين النادي.","de":"Ein Erstjähriger im Kyūdō-Verein verbeugt sich vor den Drittjährigen, trägt deren Ausrüstung und nennt sie Senpai; dafür erhält er Training und einen Platz im Ablauf des Vereins.","en":"A first-year member of a kyūdō club bows to the third-year students, carries their equipment and calls them senpai, and in return receives coaching and a place in the club's routines."},"misunderstanding":{"ar":"يُفهم هذا الترتيب أحياناً كخضوع أعمى، لكنه في الواقع عقد متبادل: احترام مقابل رعاية وتوجيه.","de":"Oft wird die Ordnung als blinde Unterwerfung gelesen, doch sie ist ein Tausch: Respekt gegen Fürsorge und Anleitung.","en":"The order is often read as blind submission, but it is a trade: respect in exchange for care and guidance."},"comparison":{"ar":"يشبه الأمر إلى حد ما تقاليد التلمذة في الحرف أو علاقة المبتدئ بالخبير، لكن الفارق هنا أن المعيار هو سنة الدخول لا الخبرة وحدها.","de":"Ähnlich wie in Handwerkszünften oder Mentoring-Beziehungen, nur dass hier das Eintrittsjahr zählt, nicht allein die Erfahrung.","en":"It resembles apprenticeship in crafts or a mentoring bond, except that the entry year counts, not experience alone."}},{"id":"asa-011","version":2,"slug":"honne-and-tatemae-the-difference-between-feeling-and-saying","contentType":"contrast","category":"communication","title":{"ar":"هونّه وتاتيمائه: ما نشعر به وما نقوله","de":"Honne und Tatemae: Fühlen und Sagen","en":"Honne and Tatemae: Feeling vs. Saying"},"deck":{"ar":"في اليابان، الفصل بين المشاعر الصادقة والموقف العلني ليس نفاقًا، بل أسلوب للحفاظ على الانسجام.","de":"In Japan ist die Trennung von echten Gefühlen und öffentlicher Haltung kein Widerspruch, sondern eine Form des Respekts.","en":"In Japan, the gap between true feelings and public stance is not deceit but a way to keep relationships smooth."},"teaser":{"ar":"لماذا لا يقول اليابانيون \"لا\" مباشرة؟ اكتشف كيف يعمل هونّه وتاتيمائه في الحياة اليومية.","de":"Warum sagen Japaner oft nicht direkt „Nein“? Entdecken Sie, wie Honne und Tatemae im Alltag funktionieren.","en":"Why do Japanese speakers often avoid a direct “no”? Discover how honne and tatemae work in everyday life."},"readingMinutes":1,"sections":{"ar":[{"heading":"المشاعر الصادقة والوجه العلني","paragraphs":["في اليابان، يُفهم هونّه (本音) على أنه المشاعر أو الرأي الحقيقي للشخص، بينما تاتيمائه (建前) هو الموقف العلني الذي يُتخذ للحفاظ على سلاسة الموقف. هذا التمييز ليس مجرد كذب؛ فالتاتيمائه يُعتبر شكلاً اجتماعيًا يحمي كرامة الآخر ويحافظ على انسجام المجموعة.","يتجلى هذا في الرفض، حيث قد يُصاغ الجواب بعبارة \"إنه صعب قليلاً\" بدلاً من \"لا\" المباشرة، تاركًا للمستمع استنتاج الإجابة. هذا الأسلوب ليس غامضًا بالضرورة، بل يعتمد على السياق والعلاقة بين المتحدثين."]},{"heading":"متى يظهر هونّه؟","paragraphs":["السياق هو المفتاح: يُعبَّر عن هونّه بحرية أكبر عند الشرب مع الزملاء المقربين، أو بين العائلة، أو في خصوصية الأصدقاء. في هذه اللحظات، تُخفف الحواجز الاجتماعية ويصبح التعبير عن الرأي الحقيقي مقبولاً.","مثال عملي: يسأل أحد الموردين مديرًا إن كان الموعد النهائي ممكنًا؛ فيقول المدير \"سنبذل قصارى جهدنا\" (تاتيمائه)، ثم يخبر الفريق على انفراد أن الموعد لا يمكن تحقيقه (هونّه). هذا لا يعني أن المدير كاذب، بل أنه يوازن بين الحفاظ على العلاقة والواقع العملي."]},{"heading":"سوء الفهم في العمل","paragraphs":["غالبًا ما يفسر المديرون الأجانب تاتيمائه على أنه موافقة، وهو فجوة تعالجها برامج التدريب عبر الثقافات بشكل صريح. المفهوم هو نوع مثالي وليس قاعدة صارمة: فاليابانيون يتفاوتون كثيرًا في المباشرة، والشباب وأماكن العمل الدولية يخلطون بين الأسلوبين.","في المقابل، في ثقافات أخرى قد يُنظر إلى الرفض غير المباشر على أنه مراوغة، بينما في اليابان يُنظر إليه على أنه لباقة."]}],"de":[{"heading":"Wahre Gefühle und öffentliche Fassade","paragraphs":["In Japan versteht man unter Honne (本音) die wahren Gefühle oder Meinungen einer Person, während Tatemae (建前) die öffentliche Haltung ist, die man einnimmt, um eine Situation reibungslos zu gestalten. Dieses Paar ist nicht einfach eine Lüge: Tatemae gilt als soziale Form, die das Gesicht des anderen schützt und die Harmonie der Gruppe wahrt.","Das zeigt sich bei Ablehnungen, die oft als „es ist ein wenig schwierig“ formuliert werden statt als direktes Nein, sodass der Zuhörer die Antwort selbst ableiten muss. Diese Art der Kommunikation ist nicht unbedingt unklar, sondern hängt von Kontext und Beziehung ab."]},{"heading":"Wann Honne gezeigt wird","paragraphs":["Der Kontext entscheidet: Honne wird freier ausgedrückt, wenn man mit engen Kollegen trinkt, in der Familie oder im Privaten mit Freunden. In solchen Momenten fallen soziale Hemmungen, und die eigene Meinung zu äußern wird akzeptabel.","Ein Beispiel aus der Praxis: Ein Lieferant fragt einen Manager, ob der Termin machbar ist; der Manager sagt „Wir werden unser Bestes geben“ (Tatemae) und teilt dem Team später privat mit, dass der Termin nicht zu halten ist (Honne). Das bedeutet nicht, dass der Manager lügt, sondern dass er die Beziehung und die praktische Realität ausbalanciert."]},{"heading":"Missverständnisse am Arbeitsplatz","paragraphs":["Ausländische Führungskräfte deuten Tatemae oft als Zustimmung – eine Lücke, die interkulturelle Trainingsprogramme inzwischen gezielt ansprechen. Das Konzept ist ein Idealtypus, keine feste Regel: Japaner unterscheiden sich stark in ihrer Direktheit, und junge Menschen sowie internationale Arbeitsplätze mischen häufig beide Stile.","Im Gegensatz dazu gilt in manchen anderen Kulturen indirekte Ablehnung als ausweichend, während sie in Japan als Höflichkeit verstanden wird."]}],"en":[{"heading":"True feelings and public face","paragraphs":["In Japan, honne (本音) is a person’s true feeling or opinion, while tatemae (建前) is the public stance adopted to keep a situation smooth. The pair is not simply lying: tatemae is treated as a social form that protects the other person’s face and keeps group harmony intact.","This appears in refusals, which may be phrased as “it is a little difficult” rather than a direct no, leaving the listener to infer the answer. This is not necessarily vague; it depends on context and relationship."]},{"heading":"When honne comes out","paragraphs":["Context matters: honne is more freely expressed when drinking with close colleagues, among family, or in private with friends. In those moments, social guards drop and voicing one’s true opinion becomes acceptable.","A practical example: a supplier asks a manager whether the deadline is possible; the manager says “we will do our best” (tatemae), then privately tells the team the date cannot be met (honne). This does not mean the manager is lying, but that he is balancing the relationship with practical reality."]},{"heading":"Misreading at work","paragraphs":["Foreign managers often misread tatemae as agreement, a gap that cross-cultural training programmes now address explicitly. The concept is an ideal type, not a rule: Japanese speakers vary widely in directness, and young people and international workplaces often mix both styles.","By contrast, in some other cultures indirect refusal is seen as evasive, whereas in Japan it is understood as politeness."]}]},"context":{"countries":["JP"],"region":"Japan","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["communication","Japan","Honne is","The pair"],"sources":[{"organization":"Wikipedia","title":{"ar":"Honne and tatemae","de":"Honne and tatemae","en":"Honne and tatemae"},"url":"https://en.wikipedia.org/wiki/Honne_and_tatemae","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Uchi–soto","de":"Uchi–soto","en":"Uchi–soto"},"url":"https://en.wikipedia.org/wiki/Uchi%E2%80%93soto","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يسأل مورد مديرًا إن كان الموعد النهائي ممكنًا؛ فيقول المدير \"سنبذل قصارى جهدنا\"، ثم يخبر الفريق على انفراد أن الموعد لا يمكن تحقيقه.","de":"Ein Lieferant fragt einen Manager, ob der Termin machbar ist; der Manager sagt „Wir werden unser Bestes geben“, teilt dem Team später aber privat mit, dass der Termin nicht zu halten ist.","en":"A supplier asks a manager whether the deadline is possible; the manager says “we will do our best”, then privately tells the team the date cannot be met."},"misunderstanding":{"ar":"الاعتقاد بأن تاتيمائه مجرد كذب. في الواقع، هو شكل اجتماعي يهدف إلى حماية مشاعر الآخرين والحفاظ على الانسجام.","de":"Die Annahme, Tatemae sei einfach eine Lüge. Tatsächlich ist es eine soziale Form, die die Gefühle anderer schützt und Harmonie bewahrt.","en":"The belief that tatemae is simply lying. In fact, it is a social form aimed at protecting others’ feelings and maintaining harmony."},"comparison":{"ar":"في بعض الثقافات الغربية، يُفضل الرفض المباشر ويعتبر أكثر صدقًا، بينما في اليابان يُنظر إلى الرفض غير المباشر على أنه أكثر لباقة.","de":"In manchen westlichen Kulturen gilt direkte Ablehnung als ehrlicher, während in Japan indirekte Ablehnung als höflicher angesehen wird.","en":"In some Western cultures, direct refusal is considered more honest, while in Japan indirect refusal is seen as more polite."},"expression":{"original":"建前","language":"日本語","gloss":{"ar":"الوجه العلني أو الموقف الرسمي الذي يُقدم للآخرين","de":"die öffentliche Fassade oder offizielle Haltung, die man anderen zeigt","en":"the public face or official stance presented to others"},"usage":{"ar":"يُستخدم في المواقف الاجتماعية للحفاظ على الانسجام، خاصة في مكان العمل أو مع الغرباء.","de":"Wird in sozialen Situationen verwendet, um Harmonie zu wahren, besonders am Arbeitsplatz oder gegenüber Fremden.","en":"Used in social situations to maintain harmony, especially at work or with strangers."},"transliteration":"tatemae"}},{"id":"asa-012","version":2,"slug":"nemawashi-deciding-the-matter-before-the-meeting-starts","contentType":"note","category":"work-and-education","title":{"ar":"نِماواشي: القرار قبل الاجتماع","de":"Nemawashi: Die Entscheidung vor der Sitzung","en":"Nemawashi: Deciding before the meeting starts"},"deck":{"ar":"في اليابان، تُتخذ القرارات عبر محادثات فردية غير رسمية قبل الاجتماع الرسمي، حيث يُستوعب الاعتراض ويصبح الاجتماع مجرد تصديق.","de":"In Japan werden Entscheidungen durch informelle Einzelgespräche vorbereitet. Einwände werden aufgenommen, und die Sitzung wird zur Bestätigung statt zur Debatte.","en":"In Japan, decisions are prepared through informal one-to-one talks. Objections are absorbed, and the meeting becomes a ratification rather than a debate."},"teaser":{"ar":"كيف يُبنى التوافق في اليابان قبل أن يبدأ الاجتماع؟ نِماواشي يجعل القرار بطيئًا في البداية سريعًا في التنفيذ.","de":"Wie entsteht Konsens in Japan, bevor die Sitzung beginnt? Nemawashi macht Entscheidungen langsam im Start, aber schnell in der Umsetzung.","en":"How is consent built in Japan before a meeting begins? Nemawashi makes decisions slow to start but fast to implement."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور القرار","paragraphs":["نِماواشي يعني الذهاب حول الجذور: محادثات فردية غير رسمية تبني الموافقة قبل القرار الرسمي. يُناقش الاقتراح بهدوء مع كل شخص متأثر، وتُمتص الاعتراضات، فيصبح الاجتماع تصديقًا لا مناظرة.","غالبًا ما يقترن بنظام رينغي، حيث يسافر مستند موقّع بالأختام عبر التسلسل الهرمي. هذا يجعل البداية بطيئة لكن التنفيذ سريع لأن المقاومة عولجت مسبقًا.","يختلف الأمر حسب المنطقة والجيل: الشركات الكبرى التقليدية والحكومة تتمسك به، بينما تتخطاه الشركات الناشئة والأجنبية، ويرى النقاد أنه قد يحابي المقربين ويخفي الخلاف. كما أن العمل عن بعد أرهق الممارسة لأنها تحدث في الممرات والغداء."]},{"heading":"أين تتعثر الممارسة؟","paragraphs":["مع انتشار العمل عن بعد، فقدت نِماواشي مساحاتها غير الرسمية، مما جعل بناء التوافق أكثر صعوبة. يلجأ البعض إلى مكالمات فردية، لكن الغرف الافتراضية لا تعوض تلقائي الممر.","في المنظمات التقليدية، يظل نِماواشي قويًا، لكنه يثير انتقادات لأنه قد يفضل المطلعين ويخفي disagreements. هذا التوتر بين الفعالية والشفافية جزء من حياته اليومية في العمل."]}],"de":[{"heading":"Die Wurzeln der Entscheidung","paragraphs":["Nemawashi bedeutet, um die Wurzeln zu gehen: informelle Einzelgespräche, die Zustimmung vor einer formellen Entscheidung aufbauen. Ein Vorschlag wird leise mit jeder betroffenen Person besprochen, Einwände werden absorbiert, und die Sitzung wird zur Ratifizierung statt zur Debatte.","Oft wird es mit Ringi kombiniert, dem schriftlichen Genehmigungssystem, bei dem ein Dokument die Hierarchie hinaufwandert und Siegel sammelt. So wird der Start langsam, die Umsetzung aber schnell, weil Widerstand bereits behandelt wurde.","Regionale und generationelle Unterschiede zeigen sich: Große traditionelle Unternehmen und Behörden halten daran fest, während Start-ups und ausländische Firmen es oft überspringen. Kritiker sagen, es begünstige Insider und verberge Uneinigkeit. Auch die Fernarbeit hat die Praxis belastet, da sie in Fluren, beim Mittagessen und nach der Arbeit stattfindet."]},{"heading":"Wo die Praxis hakt","paragraphs":["Mit der Fernarbeit verlor Nemawashi seine informellen Räume, was den Konsensaufbau erschwert. Manche greifen zu Einzelanrufen, doch virtuelle Räume ersetzen nicht die Beiläufigkeit eines Flurs.","In traditionellen Organisationen bleibt Nemawashi stark, steht aber in der Kritik, Insider zu bevorzugen und Uneinigkeit zu verbergen. Diese Spannung zwischen Effektivität und Transparenz gehört zum Arbeitsalltag."]}],"en":[{"heading":"The roots of a decision","paragraphs":["Nemawashi means going around the roots: informal one-to-one conversations that build consent before a formal decision. A proposal is discussed quietly with each affected person, objections are absorbed, and the meeting becomes a ratification rather than a debate.","It is often paired with ringi, the written approval system in which a document travels up the hierarchy collecting seals. This makes decisions slow to start but fast to implement, because resistance has already been addressed.","Regional and generational variation matters: large traditional organisations and government hold to it, while startups and foreign-owned firms often skip it. Critics say it can favour insiders and hide disagreement. Remote work has strained the practice, since much of it happens in corridors, lunches and after-work conversations."]},{"heading":"Where the practice strains","paragraphs":["With remote work, nemawashi lost its informal spaces, making consensus harder to build. Some resort to individual calls, but virtual rooms do not replace the casualness of a corridor.","In traditional organisations, nemawashi remains strong but faces criticism for favouring insiders and hiding disagreement. This tension between effectiveness and transparency is part of everyday work life."]}]},"context":{"countries":["JP"],"region":"Japan","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["work-and-education","Japan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Nemawashi","de":"Nemawashi","en":"Nemawashi"},"url":"https://en.wikipedia.org/wiki/Nemawashi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Japanese management culture","de":"Japanese management culture","en":"Japanese management culture"},"url":"https://en.wikipedia.org/wiki/Japanese_management_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"قبل اقتراح سير عمل جديد، يزور قائد الفريق أربعة زملاء فردًا فردًا خلال أسبوع؛ بحلول الاجتماع، يمر التغيير دون جدال.","de":"Bevor ein neuer Arbeitsablauf vorgeschlagen wird, besucht ein Teamleiter eine Woche lang vier Kollegen einzeln; bis zur Sitzung wird die Änderung ohne Argumente angenommen.","en":"Before proposing a new workflow, a team leader visits four colleagues individually over a week; by the time the meeting is held, the change passes without argument."},"misunderstanding":{"ar":"يُفهم أحيانًا خطأً على أنه اجتماعات سرية أو تجنب للمواجهة، لكنه في جوهره بناء موافقة مقصود قبل القرار الرسمي.","de":"Manchmal wird es fälschlich als Geheimtreffen oder Vermeidung von Konfrontation verstanden, doch es ist ein bewusster Aufbau von Zustimmung vor der formellen Entscheidung.","en":"It is sometimes mistaken for secret meetings or avoidance of confrontation, but it is a deliberate building of consent before the formal decision."},"comparison":{"ar":"يشبه المشاورة غير الرسمية قبل التصويت في بعض الثقافات، لكنه أكثر منهجية ويمتد إلى ما بعد القرار عبر نظام رينغي.","de":"Es ähnelt informellen Vorgesprächen vor Abstimmungen in anderen Kulturen, ist aber systematischer und reicht über die Entscheidung hinaus durch das Ringi-System.","en":"It resembles informal consultations before a vote in other cultures, but is more systematic and extends beyond the decision through the ringi system."}},{"id":"asa-014","version":2,"slug":"hanami-reading-the-week-the-cherries-will-open","contentType":"scene","category":"nature-and-seasons","title":{"ar":"هانامي: قراءة أسبوع تفتّح الكرز","de":"Hanami: die Woche des Kirschblühens lesen","en":"Hanami: reading the week the cherries will open"},"deck":{"ar":"في اليابان يتابع الناس توقّعات تفتّح الكرز كما يتابعون أحوال الطقس، لأن موعد النزهة تحت الأشجار يُحسب بالأسابيع بل بالأيام.","de":"In Japan verfolgen Menschen die Kirschblütenvorhersage ähnlich wie das Wetter, denn das Picknick unter den Bäumen wird nach Tagen geplant.","en":"In Japan people track cherry-blossom forecasts much like the weather, because the picnic under the trees is planned by days, not months."},"teaser":{"ar":"عادة اجتماعية تجمع الزملاء والأصدقاء تحت أشجار الكرز، لكنها تعتمد على توقّعات دقيقة ونقاشات يومية حول الموعد المناسب.","de":"Ein geselliger Brauch, bei dem Kollegen und Freunde unter Kirschbäumen zusammenkommen, der aber von genauen Vorhersagen und täglichem Austausch abhängt.","en":"A social custom that brings colleagues and friends under cherry trees, but one that depends on precise forecasts and daily updates."},"readingMinutes":1,"sections":{"ar":[{"heading":"توقّع التفتّح قبل الحجز","paragraphs":["هانامي هو تقليد مشاهدة أزهار الكرز في الربيع، وغالبًا ما يرافقه تنزّه وتناول طعام تحت الأشجار في الحدائق وأفنية المعابد وضفاف الأنهار.","التوقيت هو كل شيء: تنشر هيئة الأرصاد الجوية اليابانية وشركات طقس خاصة توقّعات تفتّح الكرز، ويتحرّك خط التفتّح شمالًا عبر الجزر.","تستمر الزهرة نحو أسبوع إلى أسبوعين حسب الطقس، لذلك يتابع الموظفون والأصدقاء التحديثات ويحجزون أماكنهم مبكرًا."]},{"heading":"جمال عابر وموسم تجاري","paragraphs":["قِصَر عمر الزهرة رمز قديم في الشعر وعلم الجمال اليابانيين، مرتبط بمفهوم «مونو نو أواري»، أي إدراك جمال الأشياء العابرة.","هانامي أيضًا موسم تجاري، مع حلويات خاصة وبيرة ورحلات مشاهدة، وبعض الحدائق تقيّد الكحول بعد شكاوى من النفايات والضوضاء.","تختلف العادات بحسب المنطقة والمناخ، وقد يتغيّر الموسم بأسبوعين، ما دفع بعض المدن إلى منع حجز الأماكن مسبقًا في الحدائق المزدحمة."]}],"de":[{"heading":"Vorhersage vor der Reservierung","paragraphs":["Hanami ist der Brauch, im Frühling die Kirschblüte zu betrachten, meist mit einem Picknick unter den Bäumen in Parks, auf Tempelgeländen und an Flussufern.","Das Timing entscheidet: Die japanische Wetterbehörde und private Wetterfirmen veröffentlichen Blütenvorhersagen, und die Blütenfront wandert nordwärts über die Inseln.","Die Blüte dauert je nach Wetter etwa ein bis zwei Wochen, deshalb verfolgen Büros und Freundeskreise die Updates und reservieren frühzeitig Plätze."]},{"heading":"Vergängliche Schönheit und Geschäft","paragraphs":["Die Kürze der Blüte ist seit Langem ein Symbol in japanischer Dichtung und Ästhetik, verbunden mit mono no aware, dem Bewusstsein für vergängliche Schönheit.","Hanami ist auch eine kommerzielle Saison mit besonderen Süßigkeiten, Bier und Aussichtsfahrten; manche Parks beschränken Alkohol nach Beschwerden über Müll und Lärm.","Die Bräuche variieren je nach Region und Klima, und die Saison kann sich um zwei Wochen verschieben; überfüllte Stadtparks haben mancherorts dazu geführt, frühes Reservieren zu verbieten."]}],"en":[{"heading":"Forecasts before reservations","paragraphs":["Hanami is the custom of viewing cherry blossoms in spring, usually with a picnic under the trees in parks, temple grounds and riverbanks.","Timing is everything: the Japan Meteorological Agency and private weather companies publish cherry-blossom forecasts, and the blossom front moves north through the islands.","The bloom lasts roughly one to two weeks depending on weather, so offices and friends track updates and book spots early."]},{"heading":"Passing beauty and a commercial season","paragraphs":["The brevity of the blossom is a long-standing symbol in Japanese poetry and aesthetics, linked to mono no aware, an awareness of passing beauty.","Hanami is also a commercial season, with special sweets, beer and viewing cruises; some parks restrict alcohol after complaints about litter and noise.","Customs vary by region and climate, and the season can shift by two weeks; crowded urban parks have led some cities to ban early spot-reserving."]}]},"context":{"countries":["JP"],"region":"Japan","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["nature-and-seasons","Japan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hanami","de":"Hanami","en":"Hanami"},"url":"https://en.wikipedia.org/wiki/Hanami","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Cherry blossom front","de":"Cherry blossom front","en":"Cherry blossom front"},"url":"https://en.wikipedia.org/wiki/Cherry_blossom_front","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يرسل الزملاء في مجموعة دردشة خريطة توقّعات التفتّح، ويضعون بساطًا بلاستيكيًا أزرق في الثامنة صباحًا لحجز مكان، ثم يأكلون وجبة بينتو تحت الأشجار بعد العمل.","de":"Kollegen schicken eine Karte der Blütenvorhersage in den Gruppenchat, legen um acht Uhr morgens eine blaue Plastikfolie zum Reservieren aus und essen nach der Arbeit Bento unter den Bäumen.","en":"Colleagues send a group-chat map of the bloom forecast, put down a blue plastic sheet at 8 a.m. to reserve a spot, and eat bento under the trees after work."},"misunderstanding":{"ar":"يظن بعض الزوار أن هانامي مجرد صورة جميلة تُلتقط بسرعة، لكنه في الواقع تنظيم اجتماعي: من يحجز المكان، ومتى، ومن يحضر الطعام.","de":"Manche Besucher halten Hanami für ein schnelles Foto, doch es ist vor allem Organisation: Wer reserviert, wann, und wer bringt das Essen mit.","en":"Some visitors think hanami is just a quick photo, but it is mostly social organisation: who reserves the spot, when, and who brings the food."},"comparison":{"ar":"يشبه الأمر متابعة مباراة كبرى: الجميع يعرف الموعد تقريبًا، لكن أحدًا لا يريد أن يفوته الأسبوع الأفضل.","de":"Es ähnelt dem Verfolgen eines großen Spiels: Alle kennen ungefähr den Termin, aber niemand will die beste Woche verpassen.","en":"It resembles following a big match: everyone knows roughly when it happens, but nobody wants to miss the best week."}},{"id":"asa-015","version":2,"slug":"nomikai-the-office-dinner-that-does-the-work-of-a-meeting","contentType":"scene","category":"food-and-hospitality","title":{"ar":"نوميكاي: عشاء العمل الذي يقوم بعمل الاجتماع","de":"Nomikai: das Firmenessen, das die Arbeit eines Meetings erledigt","en":"Nomikai: the office dinner that does the work of a meeting"},"deck":{"ar":"في اليابان، حفلات الشرب المكتبية تُستخدم للتواصل وطرح ما لا يُقال في المكتب.","de":"In Japan dienen Firmenfeiern mit Alkohol dem Teambuilding und dem offenen Austausch abseits des Büros.","en":"In Japan, office drinking parties are used for bonding and airing what cannot be said at work."},"teaser":{"ar":"حفلات الشرب المكتبية في اليابان ليست مجرد ترفيه، بل وسيلة للتواصل وطرح المشكلات بعد كأس ثانٍ.","de":"Nomikai sind mehr als geselliges Beisammensein: Nach dem zweiten Bier werden Themen angesprochen, die im Büro tabu sind.","en":"Nomikai are more than social events: after the second beer, complaints that cannot be raised in the office are finally aired."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقوس الكأس والتراتبية","paragraphs":["النوميكاي هو حفلة شرب مكتبية، غالبًا في إيزاكايا، تُقام لترحيب بالموظفين الجدد أو الاحتفال بانتهاء مشروع أو تعزيز الروابط بين الفريق.","الجلوس غالبًا ما يكون وفق التراتبية، ويُعاد ملء الكؤوس من قبل الآخرين قبل كأس المرء، وقد يصب أصغر موظف للكبار."]},{"heading":"الكحول كتصريح اجتماعي","paragraphs":["يُعامَل الكحول كتصريح اجتماعي: الشكاوى التي لا يمكن طرحها في المكتب قد تُقال بعد البيرة الثانية. ليس الجميع يشربون، والعديد من الشركات تقدم الآن خيارات غير كحولية ونسخًا نهارية؛ الممارسة أقل إلزامية مما يوحي النمط النمطي. كما تختلف الممارسة بين المناطق والأجيال، فبعض الفرق الشابة تتبنى نوميكاي نهاريًا أو افتراضيًا."]}],"de":[{"heading":"Rituale und Hierarchie am Tisch","paragraphs":["Ein Nomikai ist eine betriebliche Trinkfeier, meist in einem Izakaya, um neue Mitarbeiter zu begrüßen, Projektabschlüsse zu feiern oder Teams zu verbinden.","Die Sitzordnung ist oft hierarchisch, Gläser werden von anderen nachgefüllt, bevor man selbst trinkt, und die jüngste Person schenkt den Vorgesetzten ein."]},{"heading":"Alkohol als soziale Erlaubnis","paragraphs":["Alkohol gilt als soziale Erlaubnis: Beschwerden, die im Büro nicht geäußert werden können, dürfen nach dem zweiten Bier zur Sprache kommen. Nicht alle trinken, und viele Firmen bieten heute alkoholfreie Optionen und Tagesveranstaltungen an; die Praxis ist weniger verpflichtend als das Klischee suggeriert. Auch regional und generationell gibt es Unterschiede: Manche jüngere Teams bevorzugen ein Nomikai am Mittag oder online."]}],"en":[{"heading":"Pouring rituals and hierarchy","paragraphs":["A nomikai is an office drinking party, usually at an izakaya, held to welcome recruits, mark project endings or bond teams.","Seating is often hierarchical, glasses are refilled by others before one's own, and the most junior person may pour for seniors."]},{"heading":"Alcohol as a social permission slip","paragraphs":["Alcohol is treated as a social permission slip: complaints that cannot be raised in the office may be aired after the second beer. Not everyone drinks, and many companies now offer non-alcoholic options and daytime versions; the practice is less compulsory than the stereotype implies. The practice also varies by region and generation, with some younger teams opting for lunchtime or virtual nomikai."]}]},"context":{"countries":["JP"],"region":"Japan","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["food-and-hospitality","Japan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Izakaya","de":"Izakaya","en":"Izakaya"},"url":"https://en.wikipedia.org/wiki/Izakaya","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Nomikai","de":"Nomikai","en":"Nomikai"},"url":"https://en.wikipedia.org/wiki/Nomikai","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بعد إطلاق منتج، يجلس عشرون زميلًا في غرفة خاصة؛ يصب أصغرهم البيرة لرئيس القسم، وأخيرًا ينتقد المدير الذي قلّ كلامه لأسابيع الجدول الزمني.","de":"Nach einem Produktlaunch sitzen zwanzig Kollegen in einem Privatraum; der Jüngste schenkt dem Abteilungsleiter Bier ein, und der Manager, der wochenlang wenig gesagt hat, kritisiert endlich den Zeitplan.","en":"After a product launch twenty colleagues sit in a private room; the youngest pours beer for the section chief, and the manager who has said little for weeks finally criticises the schedule."},"misunderstanding":{"ar":"يُفترض أحيانًا أن النوميكاي إلزامي للجميع، لكنه أصبح أقل إلزامية مع مقاومة العمال الشباب وتراجع تكراره بسبب العمل عن بعد وضغوط التكلفة.","de":"Manchmal wird angenommen, ein Nomikai sei für alle verpflichtend, doch er ist weniger obligatorisch geworden, da jüngere Arbeitnehmer sich widersetzen und Remote-Arbeit sowie Kostendruck die Häufigkeit verringern.","en":"It is sometimes assumed that nomikai are obligatory for everyone, but they have become less compulsory as younger workers resist and remote work and cost pressures reduce their frequency."},"comparison":{"ar":"بينما تُعقد الاجتماعات الرسمية في قاعات الاجتماعات، يُستخدم النوميكاي كمساحة غير رسمية لبناء الثقة وتبادل الآراء بصراحة أكبر.","de":"Während formelle Meetings in Konferenzräumen stattfinden, dient das Nomikai als informeller Raum, um Vertrauen aufzubauen und Meinungen offener auszutauschen.","en":"While formal meetings take place in conference rooms, nomikai serve as an informal space to build trust and exchange views more openly."}},{"id":"asa-017","version":2,"slug":"manzai-the-comedy-double-act-built-on-speed-and-contradiction","contentType":"note","category":"regional-humour","title":{"ar":"مانزاي: ثنائي كوميدي يقوم على السرعة والتناقض","de":"Manzai: das Komikerduo aus Tempo und Widerspruch","en":"Manzai: the comedy double act of speed and contradiction"},"deck":{"ar":"في مسارح أوساكا وكيوتو، يصقل الثنائي الكوميدي مادته أمام الجمهور الصغير قبل أن يصل إلى التلفزيون.","de":"In den Theatern von Osaka und Kyoto feilen Duos live an ihrem Material, bevor sie im Fernsehen auftreten.","en":"In Osaka and Kyoto theatres, duos polish their material live before an audience long before television comes calling."},"teaser":{"ar":"مانزاي شكل كوميدي ياباني يقوم على شخصيتين: الأحمق الذي يقول المستحيل والمصحّح الذي يوبّخه، وقد صار طريقًا إلى الشهرة.","de":"Manzai ist eine japanische Comedy-Form für zwei: Der Boke sagt etwas Absurdes, der Tsukkomi korrigiert ihn – oft mit einem Klaps.","en":"Manzai is a Japanese two-person comedy form: the boke says something absurd, the tsukkomi corrects him, often with a slap."},"readingMinutes":1,"sections":{"ar":[{"heading":"الأحمق والمصحّح: لعبة التوتر","paragraphs":["في مانزاي يقف شخصان على المسرح: البوكِه يقول شيئًا سخيفًا، والتسوكّومي يصحّحه أو يوبّخه، وأحيانًا يصفعه. هذا الإيقاع السريع هو جوهر المتعة، لا الصفعة نفسها.","تطوّر هذا الشكل حول أوساكا وكيوتو، ولا يزال الأسلوب الكانْسائي الأسرع والأكثر صدامًا يُقارن بإيقاع طوكيو الأبطأ."]},{"heading":"من المسرح الصغير إلى الشاشة","paragraphs":["معظم الثنائيات تعمل مستقلة أو تحت إدارة وكالة، وتصقل مادتها حيًّا في مسارح صغيرة قبل بلوغ التلفزيون.","جائزة إم-1 الكبرى، وهي مسابقة سنوية للثنائيات، صارت حدثًا وطنيًا وطريقًا إلى الشهرة التلفزيونية، ويتنوّع الأسلوب اليوم بين الأجيال والمناطق، إذ يمزج الجيل الجديد المانزاي بالمشاهد والستاند-أب.","تأثّر إيقاع المانزاي بدبلجة الأنمي وبرامج المنوعات والسخرية السياسية، وصار يطوف مهرجانات كوميدية دولية."]}],"de":[{"heading":"Narr und Aufpasser: das Spiel der Spannung","paragraphs":["Beim Manzai stehen zwei Menschen auf der Bühne: Der Boke behauptet etwas Absurdes, der Tsukkomi korrigiert oder tadelt ihn, manchmal mit einem Klaps. Dieses schnelle Rhythmusgefühl ist der Kern des Vergnügens, nicht der Klaps selbst.","Die Form entwickelte sich um Osaka und Kyoto; der schnellere, kämpferischere Stil aus Kansai wird noch heute mit dem langsameren Vortrag in Tokio verglichen."]},{"heading":"Vom kleinen Theater auf den Bildschirm","paragraphs":["Die meisten Duos arbeiten freiberuflich oder über eine Agentur und schleifen ihr Material live in kleinen Theatern, bevor sie ins Fernsehen kommen.","Der M-1 Grand Prix, ein jährlicher Wettbewerb für Manzai-Duos, ist ein nationales Ereignis und ein Weg zum Fernseherfolg; heute mischen jüngere Generationen Manzai mit Sketchen und Stand-up, sodass sich der Stil je nach Region und Alter unterscheidet.","Der Rhythmus des Manzai prägte Animesynchronisation, Varietésendungen und politische Satire und tourt inzwischen über internationale Comedy-Festivals."]}],"en":[{"heading":"Fool and straight man: a game of tension","paragraphs":["In manzai, two people share a stage: the boke says something absurd, and the tsukkomi corrects or scolds him, sometimes with a slap. That fast rhythm is the heart of the pleasure, not the slap itself.","The form developed around Osaka and Kyoto, and Kansai's faster, more combative style is still contrasted with Tokyo's slower delivery."]},{"heading":"From small theatres to the screen","paragraphs":["Most duos are freelance or agency-managed, and they polish material live in small theatres before reaching TV.","The M-1 Grand Prix, an annual contest for manzai duos, is a national event and a major route to television fame; today younger generations blend manzai with sketch and stand-up, so the style varies by region and age.","Manzai's rhythm has shaped anime dubbing, variety shows and political satire, and it now tours international comedy festivals."]}]},"context":{"countries":["JP"],"region":"Kansai","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["regional-humour","Kansai"],"sources":[{"organization":"Wikipedia","title":{"ar":"Manzai","de":"Manzai","en":"Manzai"},"url":"https://en.wikipedia.org/wiki/Manzai","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Owarai","de":"Owarai","en":"Owarai"},"url":"https://en.wikipedia.org/wiki/Owarai","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مسرح بأوساكا يدّعي البوكِه أنه يستطيع الطيران؛ يسأله التسوكّومي كيف، فيأتيه جواب سخيف بثقة، ثم يصفعه بينما يضحك الجمهور على التوقيت.","de":"In einem Theater in Osaka behauptet der Boke, er könne fliegen; der Tsukkomi fragt wie, bekommt eine selbstsichere absurde Antwort und gibt ihm einen Klaps, während das Publikum über das Timing lacht.","en":"In an Osaka theatre the boke claims he can fly; the tsukkomi asks how, gets a confident absurd answer, and slaps him while the audience laughs at the timing."},"misunderstanding":{"ar":"أسلوب أوساكا ليس الوحيد، والثنائيات الحديثة تمزج المانزاي بالمشاهد والستاند-أب؛ والصفعة عرف مسرحي وليست عنفًا حقيقيًا.","de":"Der Stil von Osaka ist nicht der einzige, und moderne Duos verbinden Manzai mit Sketch und Stand-up; der Klaps ist eine Konvention, keine echte Gewaltabsicht.","en":"Osaka's style is not the only one, and modern duos blend manzai with sketch and stand-up; the slap is a convention, not literally violent intent."},"comparison":{"ar":"يُقارن كثيرون إيقاع المانزاي السريع بالكوميديا اللفظية في ثقافات أخرى، لكن ما يميزه هو الثنائي الثابت: دور للخطأ ودور للتصحيح.","de":"Viele vergleichen den schnellen Rhythmus des Manzai mit Wortwitz in anderen Kulturen, doch besonders ist das feste Duo: eine Rolle für den Fehler, eine für die Korrektur.","en":"Many compare manzai's quick rhythm to verbal comedy elsewhere, but what sets it apart is the fixed pair: one role for the mistake, one for the correction."}},{"id":"asa-018","version":2,"slug":"korean-speech-levels-how-one-sentence-changes-with-the-listener","contentType":"language","category":"languages","title":{"ar":"مستويات الكلام الكورية واختيار الصيغة","de":"Koreanische Sprachebenen und die Wahl des Tons","en":"Korean speech levels and choosing a tone"},"deck":{"ar":"في الكورية يحمل الفعل نهايات تحدد الأدب والرسمية، واختيار المستوى يعتمد على العمر والرتبة والقرب والمقام.","de":"Koreanische Verben tragen Endungen, die Höflichkeit und Förmlichkeit markieren; die Ebene hängt von Alter, Rang, Nähe und Situation ab.","en":"Korean verbs carry endings that mark politeness and formality; the level depends on age, rank, closeness and setting, and a wrong choice can sound rude or oddly distant."},"teaser":{"ar":"كيف يغيّر متحدث كوري واحد جملته بحسب من يخاطبه؟ نظرة على مستويات الكلام في الحياة اليومية.","de":"Wie ein und derselbe Satz je nach Gesprächspartner anders klingt: ein Blick auf Sprachebenen im koreanischen Alltag.","en":"How one Korean sentence shifts with the listener: a look at speech levels in everyday work, family and online life."},"readingMinutes":1,"sections":{"ar":[{"heading":"نهايات الفعل تحدد المسافة","paragraphs":["تحمل الأفعال الكورية نهايات تعلن الأدب والرسمية، وأبرز المستويات المعاصرة: الرسمي المؤدب (-هامنيدا)، وغير الرسمي المؤدب (-هايو)، والعادي (-هاي).","يتوقف اختيار المستوى على العمر والرتبة ودرجة القرب والمقام، والخطأ فيه قد يبدو وقاحة أو برودًا غريبًا.","يُضاف عنصر التبجيل -سي- حين يكون الفاعل شخصًا يُحترم، وتُستخدم أفعال التواضع للمتحدث نفسه في بعض السياقات."]},{"heading":"العمر أولًا ثم السياق","paragraphs":["العمر مهم إلى حد أن الكوريين كثيرًا ما يسألون من تعرّفوا عليه حديثًا عن سنه ليعرفوا أي مستوى يستخدمون.","تخفف مستويات الكلام على الإنترنت وبين الأصغر سنًا، لكن تسلسل العمل والعائلة ما زال يفرضها.","يختلف الاستخدام بحسب المنطقة والجيل ووسائل الإعلام، وكثير من الكوريين يمزجون المستويات داخل المحادثة الواحدة، وقد انفصل النظام في كوريا الشمالية في المفردات والأعراف."]}],"de":[{"heading":"Verbendungen zeigen Distanz","paragraphs":["Koreanische Verben tragen Endungen, die Höflichkeit und Förmlichkeit anzeigen; die wichtigsten heutigen Ebenen sind formell-höflich (-hamnida), informell-höflich (-haeyo) und neutral (-hae).","Die Wahl hängt von Alter, Rang, Nähe und Situation ab, und ein Fehler kann unhöflich oder seltsam distanziert wirken.","Das Honorativ-Infx -si- tritt hinzu, wenn das Subjekt eine zu respektierende Person ist, während in manchen Kontexten bescheidene Verben für einen selbst stehen."]},{"heading":"Erst das Alter, dann der Kontext","paragraphs":["Das Alter zählt so stark, dass Koreaner neue Bekannte oft nach ihrem Alter fragen, um die passende Ebene zu kennen.","Online und unter jüngeren Sprechern lockern sich die Ebenen, doch Arbeitsplatz und Familie setzen sie weiter durch.","Der Gebrauch unterscheidet sich nach Region, Generation und Medien; viele Koreaner mischen Ebenen im selben Gespräch, und in Nordkorea hat sich das System in Wortschatz und Normen entfernt."]}],"en":[{"heading":"Verb endings signal distance","paragraphs":["Korean verbs carry endings that mark politeness and formality; the main contemporary levels are formal polite (-hamnida), informal polite (-haeyo) and casual or plain (-hae).","Choosing a level depends on age, rank, closeness and setting, and getting it wrong can sound rude or oddly distant.","The honorific infix -si- is added when the subject is someone to be respected, while humble verbs are used for oneself in some contexts."]},{"heading":"Age first, then the setting","paragraphs":["Age matters so much that Koreans often ask a new acquaintance's age to know which level to use.","Speech levels are loosening online and among younger speakers, but workplace and family hierarchies still enforce them.","Usage differs by region, generation and media; many Koreans mix levels within a conversation, and the North Korean system has diverged in vocabulary and norms."]}]},"context":{"countries":["KR"],"region":"South Korea","continent":"asia","languages":["ko"],"period":"contemporary"},"tags":["languages","South Korea"],"sources":[{"organization":"Wikipedia","title":{"ar":"Korean honorifics","de":"Korean honorifics","en":"Korean honorifics"},"url":"https://en.wikipedia.org/wiki/Korean_honorifics","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Korean language","de":"Korean language","en":"Korean language"},"url":"https://en.wikipedia.org/wiki/Korean_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يقول موظف مبتدئ لزميل أقدم يغادر المكتب «سوغو هاسيوتسومنيدا» أي «لقد تعبت»، ولا ينتقل إلى الكلام العادي إلا مع أصدقاء مقربين من عمره.","de":"Ein junger Angestellter sagt zu einem älteren Kollegen, der das Büro verlässt, sugo hasyeotseumnida („Sie haben hart gearbeitet“) und wechselt nur bei engen gleichaltrigen Freunden zur lockeren Rede.","en":"A junior employee says sugo hasyeotseumnida (you have worked hard) to a senior leaving the office, and switches to casual speech only with close same-age friends."},"misunderstanding":{"ar":"يظن بعضهم أن المستوى المؤدب يعني المسافة العاطفية دائمًا، لكنه قد يكون مجرد احترام عادي داخل العمل.","de":"Manche halten die höfliche Ebene immer für emotionale Ferne, obwohl sie oft nur normale Achtung im Beruf ausdrückt.","en":"Some assume the polite level always means emotional distance, though it often just marks ordinary respect at work."},"comparison":{"ar":"في العربية تتغير المفردات والضمائر بحسب المخاطب، أما الكورية فتغيّر نهاية الفعل نفسها.","de":"Im Deutschen ändern sich Anrede und Wortwahl je nach Gegenüber, im Koreanischen aber die Verbendung selbst.","en":"English changes titles and word choice with the listener, while Korean changes the verb ending itself."},"expression":{"original":"수고하셨습니다","language":"한국어","gloss":{"ar":"لقد تعبت - تقدير مؤدب لزميل أو شخص أكبر","de":"Sie haben hart gearbeitet - höfliche Anerkennung gegenüber Kollegen oder Älteren","en":"you have worked hard - a polite acknowledgment to a colleague or senior"},"usage":{"ar":"تُقال عند مغادرة زميل العمل أو انتهاء مهمة مشتركة","de":"beim Verlassen des Büros oder nach einer gemeinsamen Aufgabe","en":"said when a colleague leaves the office or after a shared task"},"transliteration":"sugohasyeotseumnida"}},{"id":"asa-019","version":2,"slug":"nunchi-the-social-skill-of-reading-a-room-without-being-told","contentType":"note","category":"communication","title":{"ar":"نونتشي: قراءة الغرفة دون كلام","de":"Nunchi: den Raum ohne Worte lesen","en":"Nunchi: reading a room without words"},"deck":{"ar":"مهارة اجتماعية كورية تعني ملاحظة مزاج الآخرين وجوّ المكان بسرعة، وتُمدح كفضيلة لكنها قد تُتعب صاحبها.","de":"Eine koreanische soziale Fähigkeit, Stimmungen und Atmosphäre schnell zu erfassen – gelobt als Tugend, oft aber auch anstrengend.","en":"A Korean social skill for sensing moods and atmosphere quickly, praised as a virtue yet often exhausting for those who practise it."},"teaser":{"ar":"في كوريا الجنوبية يعني «نونتشي» قياس العين: أن تلتقط مزاج الآخرين وجوّ الموقف دون أن يُقال لك شيء.","de":"In Südkorea meint Nunchi das „Augenmaß“: die Gabe, Stimmungen und die Lage zu erfassen, ohne dass jemand etwas sagt.","en":"In South Korea, nunchi means “eye measure”: the ability to read another person’s mood and the atmosphere of a situation without being told."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما معنى نونتشي","paragraphs":["تعني كلمة نونتشي حرفياً «قياس العين»، أي القدرة على قراءة مزاج شخص آخر وجوّ الموقف بسرعة. وهي فضيلة اجتماعية يُمدح بها صاحبها: يلاحظ discomfort الضيف، أو غضب المدير، أو أن وقت الرحيل قد حان.","أما عبارة «نونتشي أوبدا»، أي أن يكون المرء بلا نونتشي، فهي إهانة تشير إلى شخص غافل عن الآخرين. وتعمل هذه المهارة بقوة في البيئات الهرمية حيث يُتجنّب الخلاف المباشر ويُستنتج المعنى من نبرة الصوت والسياق."]},{"heading":"بين الهدية والعبء","paragraphs":["يجد المقيمون الأجانب في نونتشي هدية وعبئاً في آن: غيابها قد يوسمهم كغرباء، واستخدامها الدائم مُتعب. ويختلف السلوك بحسب الجيل والسياق، إذ يميل الشباب الكوريون أكثر إلى المباشرة، بينما تبقى التلميحات مهمة في أماكن العمل."]}],"de":[{"heading":"Was Nunchi bedeutet","paragraphs":["Nunchi bedeutet wörtlich „Augenmaß“, also die Fähigkeit, die Stimmung eines anderen und die Atmosphäre einer Situation schnell zu lesen. Es gilt als soziale Tugend: Wer Nunchi hat, merkt, wenn ein Gast sich unwohl fühlt, wenn der Chef wütend ist oder wann es Zeit zu gehen ist.","Die Wendung „nunchi eopda“ – kein Nunchi zu haben – ist eine Beleidigung und unterstellt, jemand sei blind für andere. Besonders in hierarchischen Umgebungen wirkt Nunchi stark, wo direkter Widerspruch vermieden und Bedeutung aus Ton und Kontext erschlossen wird."]},{"heading":"Geschenk und Bürde","paragraphs":["Ausländische Mitbewohner erleben Nunchi oft als Geschenk und Last zugleich: Fehlt es, gilt man als Außenseiter; ständiger Einsatz ermüdet. Das Verhalten variiert zudem nach Generation und Situation, denn jüngere Koreaner schätzen zunehmend Direktheit, während Andeutungen am Arbeitsplatz wichtig bleiben."]}],"en":[{"heading":"What nunchi means","paragraphs":["Nunchi literally means eye measure, the ability to read another person’s mood and the atmosphere of a situation quickly. It is praised as a social virtue: a person with nunchi notices when a guest is uncomfortable, when a boss is angry or when it is time to leave.","The phrase nunchi eopda, to have no nunchi, is an insult implying someone is oblivious to others. Nunchi operates strongly in hierarchical settings, where direct disagreement is avoided and meaning must be inferred from tone and context."]},{"heading":"Gift and burden","paragraphs":["Foreign residents often find nunchi both a gift and a burden, since its absence can mark them as outsiders while its constant use is exhausting. Behaviour also varies by generation and situation: younger Koreans increasingly value directness, though hints still matter in many workplaces."]}]},"context":{"countries":["KR"],"region":"South Korea","continent":"asia","languages":["ko"],"period":"contemporary"},"tags":["communication","South Korea"],"sources":[{"organization":"Wikipedia","title":{"ar":"Nunchi","de":"Nunchi","en":"Nunchi"},"url":"https://en.wikipedia.org/wiki/Nunchi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Korea","de":"Culture of Korea","en":"Culture of Korea"},"url":"https://en.wikipedia.org/wiki/Culture_of_Korea","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في عشاء للشركة يلاحظ موظف جديد أن قائد الفريق ينظر إلى ساعته، فيشير بهدوء إلى المجموعة بأن الأمسية يجب أن تنتهي، دون أن يقول أحد شيئاً.","de":"Bei einem Firmenessen bemerkt ein neuer Mitarbeiter, dass der Teamleiter auf die Uhr schaut, und signalisiert der Gruppe still, den Abend zu beenden – niemand hat etwas gesagt.","en":"At a company dinner a new hire notices the team leader checking the time and quietly signals the group that the evening should end — no one has said anything."},"misunderstanding":{"ar":"قد يُفهم الصمت أو عدم التعليق على أنه موافقة، بينما هو في الحقيقة تلميح إلى الاعتراض أو الانزعاج.","de":"Schweigen oder das Ausbleiben eines Kommentars kann als Zustimmung gedeutet werden, obwohl es oft ein Hinweis auf Ablehnung oder Unbehagen ist.","en":"Silence or the absence of a comment can be read as agreement, when it is often a signal of disagreement or discomfort."},"comparison":{"ar":"يشبه نونتشي قراءة الجو الاجتماعي في ثقافات أخرى، لكنه في كوريا مرتبط بالهرمية واحترام التسلسل أكثر من الصراحة المباشرة.","de":"Nunchi ähnelt dem Lesen sozialer Stimmungen in anderen Kulturen, ist in Korea aber stärker mit Hierarchie und Respekt vor der Rangordnung verbunden als mit direkter Offenheit.","en":"Nunchi resembles reading social atmosphere in other cultures, but in Korea it is tied more closely to hierarchy and respect for rank than to direct frankness."},"expression":{"original":"눈치","language":"한국어","gloss":{"ar":"قياس العين: القدرة على قراءة الموقف ومزاج الآخرين","de":"Augenmaß – die Fähigkeit, eine Situation und Stimmungen zu lesen","en":"eye measure – the ability to read a situation and others’ moods"},"usage":{"ar":"يُستخدم للثناء على شخص حساس للآخرين أو للانتقاد حين يغيب هذا الحس.","de":"Wird genutzt, um jemanden für Feingefühl zu loben oder fehlendes Gespür zu kritisieren.","en":"Used to praise someone’s sensitivity to others or to criticise a lack of it."},"transliteration":"nunchi"}},{"id":"asa-020","version":2,"slug":"kimjang-making-kimchi-together-as-a-seasonal-obligation","contentType":"feature","category":"food-and-hospitality","title":{"ar":"الكيمجانغ: صناعة الكيمتشي معًا كواجب موسمي","de":"Kimjang: Kimchi gemeinsam als saisonale Pflicht","en":"Kimjang: Making Kimchi Together as a Seasonal Duty"},"deck":{"ar":"في أواخر الخريف، تتحول الساحات والأفنية إلى ورشات جماعية لصنع الكيمتشي الذي يكفي الشتاء كله.","de":"Im Spätherbst verwandeln sich Höfe und Innenhöfe in Gemeinschaftswerkstätten, in denen Kimchi für den ganzen Winter entsteht.","en":"In late autumn, courtyards and yards turn into communal workshops for making kimchi to last the winter."},"teaser":{"ar":"لماذا يجتمع الجيران والأقارب لتحضير مؤونة الكيمتشي؟ رحلة في طقس كوري يجمع بين العمل المشترك والفرح.","de":"Warum versammeln sich Nachbarn und Verwandte, um Kimchi in großen Mengen herzustellen? Eine Reise in ein koreanisches Ritual voller Gemeinschaftsarbeit und Freude.","en":"Why do neighbours and relatives gather to prepare large batches of kimchi? A look at a Korean ritual that blends cooperative labour and celebration."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس الخريف الجماعي","paragraphs":["الكيمجانغ هو تحضير كميات كبيرة من الكيمتشي في أواخر الخريف لتدوم طوال الشتاء، ويُقام عادةً كحدث عائلي أو حيّ. يُملّح الملفوف ويُغسل ويُتبّل بالفلفل الحار والثوم والزنجبيل وصلصة السمك، ثم يُعبأ في برطمانات أو قدور أونغي ويُترك ليختمر. هذا العمل جماعي؛ إذ يتجمع الأقارب والجيران لغسل الخضار وتبهيرها وتعبئتها، وينتهي اليوم بوجبة مشتركة من لحم الخنزير والكيمتشي الطازج.","في نوفمبر، تفرش عائلة أغطية في فناء المنزل، يحمل الأطفال الملفوف المملح، وتحكم الجدات على التتبيلة، ويتبادل الجيران البرطمانات في صباح اليوم التالي. هذا التبادل ليس مجرد هدية، بل شبكة دعم متبادل تُبنى على مدى سنوات."]},{"heading":"لماذا يتقلص الطقس في المدن","paragraphs":["مع انتشار السكن في الشقق وثلاجات الكيمتشي المتخصصة، تقلصت طقوس الكيمجانغ، وكثير من العائلات الحضرية تشتري الكيمتشي أو تحضر دفعة رمزية فقط. ومع ذلك، يظل البعد التعاوني هو جوهر الممارسة، وقد اعترفت اليونسكو بالكيمجانغ تراثًا ثقافيًا غير مادي عام 2013، مشيرة إلى تبادل المعرفة والعمل التعاوني.","تختلف الوصفات والتوقيت حسب المنطقة والعائلة، والكيمتشي التجاري أصبح مهيمنًا؛ لكن النسخة الجماعية لا تزال مستمرة خاصة بين كبار السن والأسر الريفية. من المهم ألا نعمم: فبعض العائلات الشابة في المدن تعيد إحياء الطقس كمناسبة اجتماعية، بينما تكتفي أخرى بالشراء."]},{"heading":"المعنى الاجتماعي للكيمجانغ","paragraphs":["الكيمجانغ ليس مجرد حفظ للطعام، بل هو مناسبة لتجديد الروابط الاجتماعية وتبادل الخبرات بين الأجيال. في اليوم المشترك، تتعلم الفتيات الصغيرات من الجدات كيفية تقدير كمية الملح والتوابل، ويتبادل الجيران وصفاتهم ونكاتهم. هذا التبادل المعرفي هو ما جعل اليونسكو تعترف به كتراث.","في سياق آخر، تُظهر ممارسات مماثلة في مناطق أخرى كيف يمكن للعمل الجماعي الموسمي أن يعزز التضامن. لكن الكيمجانغ يبقى مميزًا بارتباطه الوثيق بالهوية الغذائية الكورية وتقاليد التخمير."]}],"de":[{"heading":"Das gemeinschaftliche Herbstritual","paragraphs":["Kimjang ist die Praxis, im Spätherbst große Mengen Kimchi für den Winter herzustellen, meist als Familien- oder Nachbarschaftsereignis. Der Kohl wird gesalzen, gespült und mit Chili, Knoblauch, Ingwer und Fischsauce gewürzt, dann in Gläser oder Onggi-Töpfe gefüllt und fermentiert. Die Arbeit ist gemeinschaftlich: Verwandte und Nachbarn versammeln sich zum Waschen, Würzen und Einpacken, und der Tag endet mit einem gemeinsamen Essen von Schweinefleisch und frischem Kimchi.","Im November breitet eine Familie Planen im Hof aus, Kinder tragen gesalzenen Kohl, Großmütter beurteilen die Würzung, und am nächsten Morgen tauschen Nachbarn Gläser aus. Dieser Austausch ist kein bloßes Geschenk, sondern ein über Jahre gewachsenes Netz gegenseitiger Unterstützung."]},{"heading":"Warum das Ritual in den Städten schrumpft","paragraphs":["Mit dem Leben in Wohnungen und speziellen Kimchi-Kühlschränken hat sich das Kimjang-Ritual verkleinert, und viele städtische Familien kaufen Kimchi oder stellen nur eine symbolische Charge her. Dennoch bleibt die kooperative Dimension der Kern der Praxis; die UNESCO erkannte Kimjang 2013 als immaterielles Kulturerbe an und verwies auf die Weitergabe von Wissen und die gemeinschaftliche Arbeit.","Rezepte und Zeitpunkt variieren je nach Region und Familie, und kommerzielles Kimchi dominiert heute; die gemeinschaftliche Version besteht vor allem bei älteren und ländlichen Haushalten fort. Man sollte nicht verallgemeinern: Manche jungen Stadtfamilien beleben das Ritual als gesellschaftliches Ereignis wieder, während andere es beim Kauf belassen."]},{"heading":"Die soziale Bedeutung von Kimjang","paragraphs":["Kimjang ist nicht nur Nahrungskonservierung, sondern ein Anlass, soziale Bindungen zu erneuern und Erfahrungen zwischen Generationen auszutauschen. Am gemeinsamen Tag lernen junge Mädchen von den Großmüttern, wie viel Salz und Gewürz nötig sind, und Nachbarn tauschen Rezepte und Scherze aus. Dieser Wissenstransfer war es, der zur UNESCO-Anerkennung führte.","In anderen Kontexten zeigen ähnliche saisonale Gemeinschaftsarbeiten, wie kollektives Handeln Solidarität stärken kann. Kimjang bleibt jedoch besonders durch seine enge Verbindung zur koreanischen Esskultur und Fermentationstradition."]}],"en":[{"heading":"The communal autumn ritual","paragraphs":["Kimjang is the late-autumn practice of making large batches of kimchi to last through winter, usually as a family or neighbourhood event. Cabbage is salted, rinsed and seasoned with chilli, garlic, ginger and fish sauce, then packed into jars or onggi pots and left to ferment. The work is communal: relatives and neighbours gather to wash, season and pack, and the day ends with a shared meal of pork and fresh kimchi.","In November a family spreads tarpaulins in a courtyard, children carry salted cabbage, grandmothers judge the seasoning, and neighbours exchange jars the next morning. This exchange is not merely a gift but a web of mutual support built over years."]},{"heading":"Why the ritual shrinks in cities","paragraphs":["Apartment living and kimchi refrigerators have shrunk the ritual, and many urban families now buy kimchi or make a symbolic batch. Nevertheless, the cooperative dimension remains the heart of the practice; UNESCO recognised kimjang as intangible cultural heritage in 2013, citing the sharing of knowledge and the cooperative labour.","Recipes and timing vary by region and family, and commercial kimchi is now dominant; the communal version persists mainly among older and rural households. One should not generalise: some young urban families are reviving the ritual as a social occasion, while others simply buy their kimchi."]},{"heading":"The social meaning of kimjang","paragraphs":["Kimjang is not just food preservation but an occasion to renew social ties and exchange know-how between generations. On the shared day, young girls learn from grandmothers how to judge the amount of salt and seasoning, and neighbours swap recipes and jokes. This transfer of knowledge is what led to the UNESCO recognition.","In other contexts, similar seasonal communal work shows how collective action can strengthen solidarity. But kimjang remains distinctive for its close tie to Korean food identity and fermentation traditions."]}]},"context":{"countries":["KR"],"region":"South Korea","continent":"asia","languages":["ko"],"period":"contemporary"},"tags":["food-and-hospitality","South Korea","Kimjang is","Cabbage is"],"sources":[{"organization":"Wikipedia","title":{"ar":"Gimjang","de":"Gimjang","en":"Gimjang"},"url":"https://en.wikipedia.org/wiki/Gimjang","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Kimchi","de":"Kimchi","en":"Kimchi"},"url":"https://en.wikipedia.org/wiki/Kimchi","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في نوفمبر، تفرش عائلة أغطية في فناء المنزل، يحمل الأطفال الملفوف المملح، وتحكم الجدات على التتبيلة، ويتبادل الجيران البرطمانات في صباح اليوم التالي.","de":"Im November breitet eine Familie Planen im Hof aus, Kinder tragen gesalzenen Kohl, Großmütter beurteilen die Würzung, und am nächsten Morgen tauschen Nachbarn Gläser aus.","en":"In November a family spreads tarpaulins in a courtyard, children carry salted cabbage, grandmothers judge the seasoning, and neighbours exchange jars the next morning."},"misunderstanding":{"ar":"ليس كل الكيمتشي يُصنع في المنزل؛ فالكثير من الكوريين يشترون الكيمتشي الجاهز، خاصة في المدن، لكن الطقس الجماعي لا يزال رمزًا ثقافيًا قويًا.","de":"Nicht jeder Kimchi wird zu Hause hergestellt; viele Koreaner kaufen fertigen Kimchi, besonders in Städten, doch das gemeinschaftliche Ritual bleibt ein starkes kulturelles Symbol.","en":"Not all kimchi is made at home; many Koreans buy ready-made kimchi, especially in cities, yet the communal ritual remains a powerful cultural symbol."},"comparison":{"ar":"على عكس تحضير المخللات في بعض الثقافات الغربية الذي يقتصر على فرد أو أسرة نووية، فإن الكيمجانغ يجمع بين الأقارب والجيران في عمل تعاوني واسع.","de":"Anders als das Einlegen von Gurken in manchen westlichen Kulturen, das oft von Einzelpersonen oder Kernfamilien erledigt wird, bringt Kimjang Verwandte und Nachbarn zu einer breiten Gemeinschaftsarbeit zusammen.","en":"Unlike pickling in some Western cultures, which is often done by individuals or nuclear families, kimjang brings relatives and neighbours together in broad cooperative labour."}},{"id":"asa-021","version":2,"slug":"seollal-bows-rice-cake-soup-and-a-family-ledger","contentType":"feature","category":"traditions","title":{"ar":"سولال: انحناءات وحساء الكعك الأرز ودفتر العائلة","de":"Seollal: Verbeugungen, Reiskuchensuppe und ein Familienregister","en":"Seollal: bows, rice-cake soup and a family ledger"},"deck":{"ar":"كيف تحوّل رأس السنة القمرية في كوريا إلى موعد سنوي لتجديد صلة الأحياء بالأسلاف وتوزيع الأدوار بين الأجيال.","de":"Wie das koreanische Mondneujahr jedes Jahr die Verbindung zwischen Lebenden und Ahnen erneuert und die Rollen der Generationen sichtbar macht.","en":"How Korea's lunar New Year renews the bond between the living and their ancestors and makes generational roles visible each year."},"teaser":{"ar":"في صباح رأس السنة القمرية، تجتمع العائلات الكورية حول مائدة الأسلاف، ثم ينحني الصغار للكبار ويأكل الجميع حساء الكعك الأرز. ماذا يعني هذا الطقس في الحياة اليومية؟","de":"Am Morgen des Mondneujahrs versammeln sich koreanische Familien am Ahnenaltar, die Jüngeren verneigen sich vor den Älteren, dann essen alle Reiskuchensuppe. Was bedeutet dieser Brauch im Alltag?","en":"On lunar New Year's morning Korean families set the ancestral table, the young bow to their elders, and everyone eats rice-cake soup. What does this practice mean in daily life?"},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس الانحناء ودفء المائدة","paragraphs":["سولال هو رأس السنة القمرية في كوريا، وأحد أكبر عيدين في السنة. تجتمع العائلات في مسقط رأس الأجداد، حيث يؤدي الصغار انحناءة عميقة تُسمى «سيبيه» أمام الكبار، فيبادلونهم التحية وغالباً نقوداً. بعد ذلك يجلس الجميع لتناول «توكوك»، وهو حساء من كعك الأرز يؤكل في هذا اليوم، ويُقال إن من يتناوله يكبر سنة."]},{"heading":"مائدة الأسلاف وترتيب المقام","paragraphs":["قبل الوجبة تقيم الأسرة طقس «جيسا» لتكريم الأسلاف، فتُرتَّب أطباق الطعام ترتيباً محدداً، ويقف أفراد الأسرة للانحناء حسب الأقدمية. هذا الترتيب ليس شكلياً، بل يعكس مكانة كل فرد في العائلة وواجبه تجاه من سبقوه.","تتغير العادة بتغير العائلات: فبعض الأسر الصغيرة أو البعيدة عن مسقط الرأس تكتفي بجزء من الطقس، وبعض الأزواج الشباب يقسمون يوم العيد بين بيتَي العائلتين. ومع ذلك يبقى الانحناء وتناول الحساء حاضرين في معظم البيوت، ولو بشكل مبسط. في صباح العيد، تجهز أسرة في سيول مائدة الأسلاف، ثم ينحني الجميع بالترتيب، قبل أن توزع الجدة مغلفات النقود على الأطفال، ثم يجلس الجميع لتناول «توكوك»."]},{"heading":"ضغوط العيد: المسافة والهدايا","paragraphs":["يشهد السفر في سولال ازدحاماً شديداً، إذ يقطع الناس مسافات طويلة للوصول إلى مسقط رأس العائلة. وتتبادل الأسر هدايا رمزية من الفواكه واللحوم ومنتجات صحية تعبيراً عن الاحترام. لكن هذه الهدايا باتت تشكل عبئاً مالياً على بعض الأسر، خاصة مع ارتفاع الأسعار، ما دفع البعض إلى تقليصها أو الاتفاق على حدود واضحة.","تختلف العادات بحسب المنطقة والجيل، فطقس «جيسا» أقل شيوعاً بين المسيحيين والأسر الحضرية الشابة، كما أن التواريخ تتبع التقويم القمري وتتغير كل عام."]}],"de":[{"heading":"Die Verbeugung und die Wärme am Tisch","paragraphs":["Seollal ist das koreanische Mondneujahr und einer der beiden größten Feiertage des Jahres. Die Familien kommen in der Heimatstadt der Vorfahren zusammen. Die Jüngeren führen „Sebae“ aus, eine tiefe Verbeugung vor den Älteren, die mit einem Gruß und oft mit Geld erwidert wird. Danach setzt man sich zu „Tteokguk“, einer Reiskuchensuppe, die an diesem Tag gegessen wird und symbolisch ein Lebensjahr hinzufügt."]},{"heading":"Der Ahnenaltar und die Ordnung des Respekts","paragraphs":["Vor dem Essen halten die Familien die „Jesa“-Riten für die Ahnen ab. Die Speisen werden in einer festgelegten Anordnung aufgestellt, und die Familienmitglieder verneigen sich der Reihenfolge nach, beginnend mit den Ältesten. Diese Ordnung ist kein bloßes Zeremoniell, sondern spiegelt die Stellung jedes Einzelnen in der Familie und seine Pflicht gegenüber den Früheren.","Die Praxis wandelt sich mit den Familien: Kleine Haushalte oder weit entfernt lebende Angehörige beschränken sich manchmal auf einen Teil des Ritus, und junge Paare teilen den Feiertag mitunter zwischen zwei Haushalten auf. Dennoch bleiben Verbeugung und Suppe in den meisten Häusern erhalten, wenn auch in vereinfachter Form. Am Feiertagsmorgen richtet eine Familie in Seoul den Ahnenaltar her, alle verneigen sich der Reihe nach, dann verteilt die Großmutter Geldumschläge an die Kinder, bevor man sich zum Tteokguk setzt."]},{"heading":"Druck auf das Fest: Entfernung und Geschenke","paragraphs":["Reisen zu Seollal ist oft mit starkem Verkehr verbunden, da viele Menschen weite Strecken in die Heimat zurücklegen. Die Familien tauschen symbolische Geschenke aus – Obst, Fleisch und Gesundheitsprodukte – als Zeichen des Respekts. Für manche Haushalte sind diese Geschenke jedoch eine finanzielle Belastung, besonders bei hohen Preisen, sodass einige sie reduzieren oder klare Absprachen treffen.","Die Bräuche unterscheiden sich je nach Region und Generation: Der Jesa-Ritus ist bei Christen und jüngeren städtischen Haushalten weniger verbreitet, und die Daten folgen dem Mondkalender, verschieben sich also jedes Jahr."]}],"en":[{"heading":"The bow and the warmth of the table","paragraphs":["Seollal is the Korean Lunar New Year and one of the two biggest holidays of the year. Families gather in the ancestral hometown. Younger people perform sebae, a deep bow to elders, who respond with a greeting and often money. Then everyone sits down to tteokguk, a rice-cake soup eaten on this day and said to mark a year of age."]},{"heading":"The ancestral table and the order of respect","paragraphs":["Before the meal, families hold jesa rites for their ancestors: food is set out in a prescribed arrangement, and family members bow in order of seniority. This ordering is not mere ceremony; it reflects each person's place in the family and their duty to those who came before.","The practice shifts with family circumstances: small households or those living far away may keep only part of the rite, and some young couples now split the day between two households. Yet the bow and the soup remain in most homes, even in simplified form. On New Year's morning a Seoul family sets the ancestral table, bows in turn, then the grandmother hands envelopes of money to the children before everyone sits down to tteokguk."]},{"heading":"Pressure on the holiday: distance and gifts","paragraphs":["Travel at Seollal is severely congested, as people cover long distances to reach the family hometown. Households exchange gift sets—fruit, meat and health products—as tokens of respect. For some families these gifts are a financial burden, especially with high prices, leading some to scale them down or agree on limits.","Customs differ by region and generation: the jesa rite is less common among Christians and younger urban households, and the dates follow the lunar calendar, shifting each year."]}]},"context":{"countries":["KR"],"region":"South Korea","continent":"asia","languages":["ko"],"period":"contemporary"},"tags":["traditions","South Korea","Seollal is","Younger people"],"sources":[{"organization":"Wikipedia","title":{"ar":"Korean New Year","de":"Korean New Year","en":"Korean New Year"},"url":"https://en.wikipedia.org/wiki/Korean_New_Year","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Korea","de":"Culture of Korea","en":"Culture of Korea"},"url":"https://en.wikipedia.org/wiki/Culture_of_Korea","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في صباح العيد، تجهز أسرة في سيول مائدة الأسلاف، ثم ينحني الجميع بالترتيب، قبل أن توزع الجدة مغلفات النقود على الأطفال، ثم يجلس الجميع لتناول «توكوك».","de":"Am Neujahrsmorgen richtet eine Familie in Seoul den Ahnenaltar her, alle verneigen sich der Reihe nach, dann übergibt die Großmutter den Kindern Geldumschläge, bevor alle Tteokguk essen.","en":"On New Year's morning a Seoul family sets the ancestral table, bows in turn, then the grandmother hands envelopes of money to the children before everyone sits down to tteokguk."},"misunderstanding":{"ar":"ليس كل الكوريين يحتفلون بالطقس نفسه؛ فطقوس الأسلاف قد تغيب لدى بعض الأسر، والانحناء قد يقتصر على التحية البسيطة، فلا يصح تعميم صورة واحدة.","de":"Nicht alle Koreaner begehen das Fest auf die gleiche Weise; Ahnenriten können fehlen, und die Verbeugung fällt manchmal einfacher aus – ein einheitliches Bild gibt es nicht.","en":"Not every Korean family celebrates the same way; ancestral rites may be absent and the bow can be simpler, so a single picture does not fit all."},"comparison":{"ar":"في كثير من الثقافات يُحتفل برأس السنة بالاجتماع حول مائدة فقط، بينما في سولال تُضاف إلى المائدة خطوات منظمة نحو الأسلاف والكبار.","de":"In vielen Kulturen wird Neujahr nur mit einem gemeinsamen Essen gefeiert, während in Seollal zusätzlich festgelegte Gesten gegenüber Ahnen und Älteren dazugehören.","en":"In many cultures New Year is marked mainly by a shared meal, whereas Seollal adds prescribed gestures toward ancestors and elders."}},{"id":"asa-022","version":2,"slug":"jesa-setting-a-table-for-ancestors-who-are-no-longer-there","contentType":"feature","category":"beliefs-and-folklore","title":{"ar":"جيسا: مائدة يُعدّها الأحياء لمن رحلوا","de":"Jesa: ein gedeckter Tisch für die Verstorbenen","en":"Jesa: setting a table for ancestors who are no longer there"},"deck":{"ar":"طقس كوري يضع الطعام أمام الأسلاف مرة كل عام، ويجعل من الوليمة الختامية جزءاً من الحداد نفسه.","de":"Ein koreanisches Ritual stellt einmal im Jahr Speisen für die Ahnen bereit und macht aus dem gemeinsamen Essen einen Teil der Trauer.","en":"A Korean rite lays out food for the dead once a year and turns the shared meal afterwards into part of the mourning itself."},"teaser":{"ar":"مائدة تُرتب صفوفاً قبل الفجر، وكأس يُسكب ثلاث مرات، ثم يأكل الجميع ما قُدّم لمن غابوا. كيف يعيش الكوريون هذا الطقس اليوم؟","de":"Ein Tisch, der vor der Morgendämmerung gedeckt wird, dreimal eingeschenkter Reiswein und ein Mahl, das die Familie anschließend teilt. Wie wird Jesa heute gelebt?","en":"A table arranged before dawn, a cup poured three times, and then everyone eats what was offered to those who are gone. How do Koreans live this rite today?"},"readingMinutes":1,"sections":{"ar":[{"heading":"مائدة تُقام قبل الفجر","paragraphs":["تُقام الجيسا في ذكرى وفاة أحد الأقارب، وفي رأس السنة القمرية وعيد تشوسوك، حيث تُفرش مائدة منخفضة أمام صورة المتوفى أو لوحته. تُرتّب الأطباق في صفوف ومواضع محددة: فاكهة وأرز وحساء ولحم وكعك أرز، بحسب قواعد تختلف من أسرة إلى أخرى ومن إقليم إلى آخر.","يقود رب الأسرة الطقس: ينحني مع أفراد أسرته، ويسكب النبيذ ثلاث مرات، ويتلو عبارات التذلل. وبعد انتهاء الطقس يتقاسم الحاضرون الطعام، وهو تقليد يُعرف بـ«أومبوك»، إذ يُنظر إلى الأكل من المائدة كبركة وشركة مع الميت لا كمجرد وجبة.","يعكس الطقس أفكاراً كونفوشيوسية عن بر الوالدين واستمرار النسب من جهة الأب، وقد كان دور المتصدر ينتقل تقليدياً إلى الابن الأكبر. غير أن المشاركة تراجعت مع صغر الأسر وانتشار المسيحية، فبسّطت بعض الأسر الطقس أو نقلته إلى حدائق تذكارية."]},{"heading":"من يحمل المائدة اليوم","paragraphs":["تختلف الصورة كثيراً بحسب المنطقة والدين والجيل: فالمسيحيون الكوريون لا يقيمون الجيسا عادةً، وكثير من الأسر الحضرية استبدلتها بزيارات صامتة إلى المقابر أو بحديث قصير عن الفقيد. ومع ذلك يبقى الطقس حياً في أسر كثيرة، خصوصاً في الريف وخلال الأعياد الكبرى، حيث يجتمع الأقارب من مدن بعيدة.","في إحدى الأسر، في ذكرى وفاة الأب، يضع الابن مائدة منخفضة قبل الفجر، ويسكب نبيذ الأرز ثلاث مرات، وينحني مع أسرته، ثم يأكل الجميع ما قُدّم. هذه اللحظة تجمع بين الحزن والطمأنينة، وتُعلّم الأبناء أن الصلة بالأسلاف ليست ذكرى بعيدة بل فعل يُمارس على مائدة."]}],"de":[{"heading":"Ein Tisch vor der Morgendämmerung","paragraphs":["Jesa wird am Todestag eines Angehörigen, zum Mondneujahr und zu Chuseok gefeiert. Vor einem Bild oder einer Gedenktafel der Verstorbenen wird ein niedriger Tisch gedeckt. Obst, Reis, Suppe, Fleisch und Reiskuchen werden nach festen Regeln in Reihen und Positionen angeordnet, die sich von Familie zu Familie und von Region zu Region unterscheiden.","Das Familienoberhaupt führt das Ritual an: Es verneigt sich mit der Familie, gießt dreimal Reiswein aus und spricht Worte des Gedenkens. Danach teilen die Anwesenden die Speisen, eine Praxis namens Eumbok. Das Essen vom Tisch gilt als Segen und als Gemeinschaft mit den Toten, nicht als bloße Mahlzeit.","Das Ritual spiegelt konfuzianische Vorstellungen von Kindespflicht und väterlicher Linie; traditionell ging die Rolle des Haupttrauernden auf den ältesten Sohn über. Mit kleineren Familien und wachsender christlicher Zugehörigkeit ist die Teilnahme jedoch zurückgegangen. Manche Familien vereinfachen das Ritual oder verlegen es in Gedenkparks."]},{"heading":"Wer den Tisch heute trägt","paragraphs":["Das Bild unterscheidet sich stark nach Region, Religion und Generation: Christliche Koreaner feiern in der Regel kein Jesa, und viele städtische Familien haben es durch stille Gedenkbesuche oder ein kurzes Gespräch über die Verstorbenen ersetzt. In vielen Familien, besonders auf dem Land und zu den großen Feiertagen, bleibt das Ritual dennoch lebendig, wenn Verwandte aus weit entfernten Städten zusammenkommen.","In einer Familie stellt der Sohn am Todestag seines Vaters vor der Morgendämmerung einen niedrigen Tisch auf, gießt dreimal Reiswein aus, verneigt sich mit seiner Familie, und anschließend essen alle gemeinsam die Speisen. Dieser Moment verbindet Trauer und Ruhe und lehrt die Kinder, dass die Verbindung zu den Ahnen kein fernes Gedenken ist, sondern eine Handlung am Tisch."]}],"en":[{"heading":"A table set before dawn","paragraphs":["Jesa is held on the anniversary of a death, at Lunar New Year and at Chuseok. A low table is laid before a portrait or memorial tablet of the deceased, with fruit, rice, soup, meat and rice cakes arranged in strict rows and positions that vary by family and region.","The head of the household leads the rite, bowing with the family, pouring rice wine three times and reciting words of remembrance. Afterwards those present share the food, a practice called eumbok: eating from the table is understood as blessing and communion with the dead, not simply a meal.","The rite reflects Confucian ideas of filial duty and patrilineal continuity, and the role of chief mourner traditionally passed to the eldest son. Participation has declined with smaller families and Christian affiliation, and some families simplify the rite or move it to a memorial park."]},{"heading":"Who carries the table now","paragraphs":["The picture varies widely by region, religion and generation: Christian Koreans usually do not hold jesa, and many urban families have replaced it with quiet memorial visits or a short conversation about the deceased. Yet the rite stays alive in many families, especially in the countryside and at the major holidays, when relatives gather from distant cities.","On the anniversary of his father's death a son sets a low table before dawn, pours rice wine three times, bows with his family, and then the group eats the offerings. The moment holds grief and calm together, teaching children that the bond with ancestors is not a distant memory but something done at a table."]}]},"context":{"countries":["KR"],"region":"South Korea","continent":"asia","languages":["ko"],"period":"contemporary"},"tags":["beliefs-and-folklore","South Korea","Jesa is","The table"],"sources":[{"organization":"Wikipedia","title":{"ar":"Jesa","de":"Jesa","en":"Jesa"},"url":"https://en.wikipedia.org/wiki/Jesa","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Veneration of the dead","de":"Veneration of the dead","en":"Veneration of the dead"},"url":"https://en.wikipedia.org/wiki/Veneration_of_the_dead","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في ذكرى وفاة أبيه يضع الابن مائدة منخفضة قبل الفجر، ويسكب نبيذ الأرز ثلاث مرات، وينحني مع أسرته، ثم يأكل الجميع ما قُدّم.","de":"Am Todestag seines Vaters stellt der Sohn vor der Morgendämmerung einen niedrigen Tisch auf, gießt dreimal Reiswein aus, verneigt sich mit seiner Familie, und danach essen alle die Speisen.","en":"On the anniversary of his father's death a son sets a low table before dawn, pours rice wine three times, bows with his family, and then the group eats the offerings."},"misunderstanding":{"ar":"ليس كل كوري يقيم الجيسا؛ فالدين والانتماء الأسري يغيّران الممارسة أكثر مما تغيّرها المنطقة وحدها.","de":"Nicht jeder Koreaner feiert Jesa; Religion und Familienzugehörigkeit verändern die Praxis stärker als die Region allein.","en":"Not every Korean holds jesa; religion and family background shape the practice more than region alone."},"comparison":{"ar":"يشبه الطقس في جوهره زيارات المقابر في كثير من المجتمعات الريفية، لكنه يختلف في أنه يجعل من الطعام المشترك لحظة عبور بين الأحياء والموتى.","de":"Im Kern ähnelt das Ritual den Grabbesuchen in vielen ländlichen Gesellschaften, doch es macht das gemeinsame Essen zu einem Übergang zwischen Lebenden und Toten.","en":"In essence the rite resembles grave visits in many rural societies, but it makes the shared meal a crossing point between the living and the dead."}},{"id":"asa-023","version":2,"slug":"arirang-a-folk-song-that-everyone-sings-a-different-way","contentType":"note","category":"music-and-dance","title":{"ar":"أريرانغ: أغنية يغنّيها كلٌّ بطريقته","de":"Arirang: ein Lied, das jeder anders singt","en":"Arirang: a folk song everyone sings differently"},"deck":{"ar":"أغنية شعبية كورية واحدة، لكنها تعيش في مئات الصور المحلية، من فرق المزارعين إلى الأوركسترا، ومن الجنازات إلى المهرجانات.","de":"Ein koreanisches Volkslied, das in hunderten lokalen Fassungen lebt, von Bauernkapellen bis zu Sinfonieorchestern, von Begräbnissen bis zu Massenfesten.","en":"One Korean folk song lives in hundreds of local versions, from farmers' bands to symphony orchestras, from rural funerals to mass festivals."},"teaser":{"ar":"أغنية شعبية كورية تتقاسمها الكوريتان والمهاجرون، وتحمل في كل منطقة نبرة فراق وشوق خاصة بها.","de":"Ein Volkslied, das beide Koreas und die Diaspora teilen, und das in jeder Region einen eigenen Ton von Abschied und Sehnsucht trägt.","en":"A folk song shared by both Koreas and diaspora communities, carrying its own tone of parting and longing in every region."},"readingMinutes":1,"sections":{"ar":[{"heading":"لازمة يتقاسمها الناس","paragraphs":["أريرانغ أغنية شعبية كورية لها نسخ إقليمية كثيرة، تجمعها لازمة واحدة ونبرة فراق وشوق. تُغنّى اللازمة غالبًا بالنداء والاستجابة، وتُؤلَّف المقاطع محليًا أو تُرتجل، فتعيش الأغنية في مئات الصور المختلفة.","يتراوح المؤدّون بين فرق المزارعين والأوركستراهات السيمفونية، وصارت الأغنية معيارًا في مجتمعات الشتات الكوري. وفي كوريا الشمالية أُطلق الاسم على مهرجان جمباز جماهيري، ما يُظهر كيف يمكن لأغنية واحدة أن تتبنّاها ثقافات سياسية متنافسة.","يختلف الأداء أيضًا بين الأجيال والمناطق؛ فالشباب في المدينة قد يعرفون اللازمة دون بقية المقاطع، بينما يحفظ الكبار صورًا محلية كاملة."]},{"heading":"رمز يتجاوز الغناء","paragraphs":["استُخدمت الأغنية في حركة الاستقلال، ثم تبنّتها الكوريتان لاحقًا رمزًا لأمة مشتركة، وأدرجت اليونسكو نسختين منها عام 2012.","في مناسبة ريفية وفي قاعة حفلات تُعزف اللحن نفسه بإيقاعات مختلفة جدًا، وغالبًا يشارك الجمهور في اللازمة دون حاجة إلى ورقة كلمات."]}],"de":[{"heading":"Ein Refrain, den alle teilen","paragraphs":["Arirang ist ein koreanisches Volkslied mit vielen regionalen Fassungen, die einen Refrain und einen Ton von Abschied und Sehnsucht teilen. Der Refrain wird oft im Wechselgesang gesungen, Strophen werden lokal gedichtet oder improvisiert, sodass das Lied in Hunderten Varianten existiert.","Die Ausführenden reichen von Bauernkapellen bis zu Sinfonieorchestern, und das Lied wurde auch in koreanischen Diasporagemeinden zum Standard. In Nordkorea trägt ein Massenturnfest den Namen, was zeigt, wie rivalisierende politische Kulturen dasselbe Lied beanspruchen.","Auch zwischen Generationen und Regionen unterscheidet sich die Aufführung: Jüngere in der Stadt kennen oft nur den Refrain, Ältere bewahren vollständige lokale Fassungen."]},{"heading":"Ein Zeichen über das Singen hinaus","paragraphs":["Das Lied wurde in der Unabhängigkeitsbewegung genutzt, später von beiden Koreas als Symbol gemeinsamer Nation, und die UNESCO verzeichnete 2012 zwei Fassungen.","Bei einem ländlichen Begräbnis und in einem Konzertsaal erklingt dieselbe Melodie in sehr unterschiedlichem Tempo; das Publikum stimmt oft in den Refrain ein, ohne ein Textblatt zu brauchen."]}],"en":[{"heading":"A refrain people share","paragraphs":["Arirang is a Korean folk song with many regional versions, all sharing the refrain Arirang and a tone of parting and longing. The refrain is often sung as a call-and-response, and verses are improvised or composed locally, so the song exists in hundreds of variants.","Performers range from farmers' bands to symphony orchestras, and the song also became a standard in Korean diaspora communities. In North Korea the name was given to a mass gymnastics festival, showing how one song can be claimed by rival political cultures.","Performance also shifts across generations and regions: younger city singers may know only the refrain, while older people keep full local verses."]},{"heading":"A symbol beyond singing","paragraphs":["It was used in the independence movement and later by both Koreas as a symbol of shared nationhood; UNESCO listed two versions in 2012.","At a rural funeral and at a concert hall the same melody is played at very different tempos; audiences often join the refrain without needing a lyric sheet."]}]},"context":{"countries":["KR","KP"],"region":"Korea","continent":"asia","languages":["ko"],"period":"contemporary"},"tags":["music-and-dance","Korea"],"sources":[{"organization":"Wikipedia","title":{"ar":"Arirang","de":"Arirang","en":"Arirang"},"url":"https://en.wikipedia.org/wiki/Arirang","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Korea","de":"Culture of Korea","en":"Culture of Korea"},"url":"https://en.wikipedia.org/wiki/Culture_of_Korea","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في جنازة ريفية وفي قاعة حفلات تُعزف اللحن نفسه بإيقاعات مختلفة جدًا، وغالبًا يشارك الجمهور في اللازمة دون حاجة إلى ورقة كلمات.","de":"Bei einem ländlichen Begräbnis und in einem Konzertsaal erklingt dieselbe Melodie in sehr unterschiedlichem Tempo; das Publikum stimmt oft in den Refrain ein, ohne ein Textblatt zu brauchen.","en":"At a rural funeral and at a concert hall the same melody is played at very different tempos; audiences often join the refrain without needing a lyric sheet."},"misunderstanding":{"ar":"ليس هناك نسخة واحدة معتمدة: تختلف الألحان والكلمات وسياقات الأداء بحسب المنطقة والعصر، وتستخدم الكوريتان الأغنية في سياقات سياسية مختلفة.","de":"Es gibt keine einzige autorisierte Fassung: Melodien, Texte und Aufführungskontexte unterscheiden sich nach Region und Zeit, und beide Koreas nutzen das Lied in unterschiedlichen politischen Zusammenhängen.","en":"There is no single authorised version: melodies, lyrics and performance settings differ by region and era, and the two Koreas use the song in different political contexts."},"comparison":{"ar":"حيث تُغنّى في الجنازات الريفية ببطء وحزن، تُعزف في القاعات بإيقاع مهيب، وفي المهرجانات الجماهيرية بإيقاع جماعي منضبط.","de":"Auf dem Land bei Begräbnissen klingt es langsam und traurig, im Konzertsaal feierlich, bei Massenfesten in strengem kollektivem Takt.","en":"Sung slowly and mournfully at rural funerals, played solemnly in concert halls, and performed in strict collective rhythm at mass festivals."}},{"id":"asa-024","version":2,"slug":"suneung-the-exam-morning-when-the-country-makes-way","contentType":"feature","category":"work-and-education","title":{"ar":"صباح السونيونغ: يوم يصنع فيه البلد الطريق","de":"Suneung: Der Prüfungsmorgen, an dem das Land Platz macht","en":"Suneung: The Exam Morning When the Country Makes Way"},"deck":{"ar":"كيف يتحول امتحان واحد إلى حدث وطني يعيد ترتيب الوقت والعمل والتعاطف الجماعي.","de":"Wie eine einzige Prüfung zum nationalen Ereignis wird, das Zeit, Arbeit und Mitgefühl neu ordnet.","en":"How a single test becomes a national event that rearranges time, work and collective sympathy."},"teaser":{"ar":"في صباح خميس من نوفمبر، تتأخر المكاتب، وتتوقف الرحلات، وتفتح المدن طرقها لطلاب يحملون مستقبلهم في حقيبة.","de":"An einem Donnerstag im November öffnen Büros später, Flüge warten, und Polizeimotorräder eskortieren Jugendliche, die ihre Zukunft in der Tasche tragen.","en":"On a Thursday in November, offices open late, flights wait, and police motorcycles clear the road for teenagers carrying their future in a bag."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقوس الصباح: الطعام والشرطة والدعاء","paragraphs":["يُعقد امتحان القدرة الدراسية الجامعية، المعروف بالسونيونغ، في يوم خميس من شهر نوفمبر، وتعتمده الجامعات في جميع أنحاء كوريا الجنوبية. وفي ذلك الصباح تتغير إيقاعات الحياة اليومية: تفتح المكاتب أبوابها متأخرة لتخفيف الزحام، وتُحتجز الرحلات الجوية أثناء قسم الاستماع في اللغة الإنجليزية، وترافق الدراجات النارية التابعة للشرطة الطلاب المتأخرين إلى قاعات الاختبار. أما العائلات والكنائس فتقيم صلوات وسهرات دعاء، ويقف الطلاب الأصغر عند البوابات ليشجعوا زملاءهم الأكبر.","في هذا اليوم تحمل الأم لابنتها كعكة أرز لزجة، إذ يعتقد البعض أن اللزوجة تجعل المعرفة تلتصق بالذهن، بينما تشق دراجات الشرطة الطريق إلى قاعة الاختبار. هذه التفاصيل الصغيرة ليست مجرد خرافة، بل طريقة تجعل بها الأسر والمجتمعات المحلية الامتحان حدثًا جماعيًا لا فرديًا، وتعبّر عن القلق والرجاء في آن واحد."]},{"heading":"منافسة تنتج اقتصادًا موازيًا","paragraphs":["تغذي المنافسة على الجامعات المرموقة صناعة كبيرة من المعاهد الخاصة، وساعات دراسة طويلة تمتد إلى المساء. ويجد الطلاب أنفسهم بين واجب مدرسي مكثف وتوقعات أسرية عالية، فيصبح الامتحان محورًا ينظم السنة الدراسية بأكملها.","لكن الصورة ليست موحدة: فقد أضافت الإصلاحات مسارات قبول شاملة وأخرى قائمة على المقال، ويختلف وزن الامتحان باختلاف الجامعات والتخصصات والمناطق. كما أن التغطية الأجنبية كثيرًا ما تبالغ في تأثيره، متجاهلة أن عددا متزايدا من الطلاب يسلكون طرقًا بديلة."]},{"heading":"ما بعد القاعة: جدل مستمر","paragraphs":["يظل السونيونغ مهيمنًا على التقويم الاجتماعي رغم الجدل الذي يدور حوله منذ سنوات. ففي اليوم التالي يعود الطلاب إلى حياتهم العادية، لكن النقاش حول عدالة الامتحان وثقله يستمر في الإعلام والمدارس والبيوت.","يختلف الأمر بين الأجيال: فبعض الأسر التي مرت بتجربة الامتحان في السابق تتعامل معه بهدوء أكبر، بينما يعيش الطلاب الجدد ضغطًا مضاعفًا بسبب المنافسة والتوقعات. وهكذا يبقى السونيونغ مرآة لمجتمع يتغير، لكنه يحتفظ بطقس جماعي يعرف فيه الجميع ما يجب فعله في صباح الخميس."]}],"de":[{"heading":"Morgendliche Rituale: Reis, Polizei und Gebete","paragraphs":["Der Suneung, die College Scholastic Ability Test, findet an einem Donnerstag im November statt und wird von Universitäten in ganz Südkorea herangezogen. An diesem Morgen verändert sich der Alltag: Büros öffnen später, um den Verkehr zu entlasten, Flüge werden während des Hörverstehens im Englischteil zurückgehalten, und Polizeimotorräder begleiten verspätete Schüler zu den Prüfungssälen. Familien und Kirchen halten Gebetswachen ab, jüngere Schüler jubeln den Prüflingen an den Toren zu.","An diesem Morgen reicht eine Mutter ihrer Tochter einen klebrigen Reiskuchen, weil man glaubt, die Klebrigkeit lasse das Wissen haften, während Polizeimotorräder die Straße zum Prüfungssaal freimachen. Solche Gesten sind keine bloße Folklore, sondern eine Art, wie Familien und Nachbarschaften die Prüfung zu einer gemeinschaftlichen statt individuellen Angelegenheit machen."]},{"heading":"Wettbewerb und die private Bildungsindustrie","paragraphs":["Der Wettbewerb um Spitzenuniversitäten nährt eine große Industrie privater Nachhilfeinstitute und lange Lernstunden bis in den Abend. Schüler stehen zwischen dichtem Schulpensum und hohen familiären Erwartungen, sodass die Prüfung den gesamten Jahresablauf strukturiert.","Doch das Bild ist nicht einheitlich: Reformen haben umfassende Zulassungsverfahren und aufsatzbasierte Wege ergänzt, und das Gewicht der Prüfung variiert je nach Universität, Fach und Region. Ausländische Berichte übertreiben ihren Einfluss oft und übersehen, dass zunehmend mehr Schüler alternative Wege gehen."]},{"heading":"Nach dem Saal: eine anhaltende Debatte","paragraphs":["Trotz jahrelanger Diskussionen dominiert der Suneung weiterhin den gesellschaftlichen Kalender. Am Tag danach kehren die Schüler in ihren Alltag zurück, doch die Debatte über Fairness und Belastung setzt sich in Medien, Schulen und Haushalten fort.","Die Erfahrung unterscheidet sich zwischen den Generationen: Familien, die die Prüfung selbst durchlaufen haben, gehen oft gelassener damit um, während jüngere Schüler durch Konkurrenz und Erwartungen doppelt belastet sind. So bleibt der Suneung ein Spiegel einer sich wandelnden Gesellschaft und zugleich ein kollektives Ritual, bei dem alle wissen, was an einem Donnerstagmorgen zu tun ist."]}],"en":[{"heading":"Morning Rituals: Sticky Rice, Police and Prayer","paragraphs":["The suneung, the College Scholastic Ability Test, is held on a Thursday in November and used by universities across South Korea. On that morning the rhythm of daily life shifts: offices open later to clear traffic, flights are held during the English listening section, and police motorcycles escort late students to testing halls. Families and churches hold prayer vigils, and younger students cheer the test-takers at the gates.","On the morning of the test a mother hands her daughter a sticky rice cake, believing the stickiness will make the knowledge stick, while police motorcycles clear the road to the testing hall. These small gestures are not mere folklore; they are how families and neighbourhoods turn the exam into a shared occasion rather than a private ordeal."]},{"heading":"Competition and the Private Academy Economy","paragraphs":["Competition for top universities feeds a large private academy industry and long study hours that stretch into the evening. Students find themselves between a dense school curriculum and high family expectations, so the exam organises the entire academic year.","Yet the picture is not uniform: reforms have added comprehensive admissions and essay-based routes, and the exam's weight varies by university, major and region. Foreign coverage often exaggerates its influence, overlooking that a growing number of students take alternative paths."]},{"heading":"After the Hall: A Debate That Continues","paragraphs":["Despite years of debate, the suneung still dominates the social calendar. The day after, students return to ordinary life, but discussion of fairness and pressure continues in media, schools and homes.","Experience differs across generations: families who sat the exam themselves often treat it with more calm, while younger students feel a double burden of competition and expectation. The suneung remains a mirror of a changing society and, at the same time, a collective ritual in which everyone knows what to do on a Thursday morning."]}]},"context":{"countries":["KR"],"region":"South Korea","continent":"asia","languages":["ko"],"period":"contemporary"},"tags":["work-and-education","South Korea","The suneung","On exam"],"sources":[{"organization":"Wikipedia","title":{"ar":"College Scholastic Ability Test","de":"College Scholastic Ability Test","en":"College Scholastic Ability Test"},"url":"https://en.wikipedia.org/wiki/College_Scholastic_Ability_Test","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Education in South Korea","de":"Education in South Korea","en":"Education in South Korea"},"url":"https://en.wikipedia.org/wiki/Education_in_South_Korea","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في صباح الاختبار تعطي الأم ابنتها كعكة أرز لزجة، معتقدة أن اللزوجة تجعل المعرفة تلتصق، بينما تفتح دراجات الشرطة الطريق إلى قاعة الاختبار.","de":"Am Prüfungsmorgen reicht eine Mutter ihrer Tochter einen klebrigen Reiskuchen in der Hoffnung, das Wissen bleibe haften, während Polizeimotorräder den Weg zum Prüfungssaal freimachen.","en":"On the morning of the test a mother hands her daughter a sticky rice cake, believing the stickiness will make the knowledge stick, while police motorcycles clear the road to the testing hall."},"misunderstanding":{"ar":"يعتقد كثيرون خارج كوريا أن السونيونغ هو الطريق الوحيد للجامعة، لكن مسارات القبول الشاملة والمقالية أصبحت جزءًا من النظام، وإن بقي الامتحان الأكثر حضورًا في الوعي العام.","de":"Viele außerhalb Koreas glauben, der Suneung sei der einzige Weg zur Universität, doch ganzheitliche und aufsatzbasierte Zulassungswege sind Teil des Systems – auch wenn die Prüfung im öffentlichen Bewusstsein am stärksten präsent bleibt.","en":"Many outside Korea assume the suneung is the only route to university, but comprehensive and essay-based admissions are part of the system, even if the exam remains the most visible in public consciousness."},"comparison":{"ar":"بخلاف امتحانات القبول التي تظل شأنًا فرديًا في كثير من البلدان، يتحول السونيونغ في كوريا الجنوبية إلى حدث وطني تعيد فيه المؤسسات ترتيب وقتها.","de":"Anders als in vielen Ländern, wo Aufnahmeprüfungen eine individuelle Angelegenheit bleiben, wird der Suneung in Südkorea zum nationalen Ereignis, bei dem Institutionen ihren Zeitplan umstellen.","en":"Unlike entrance exams that stay a private matter in many countries, the suneung becomes a national event in South Korea, with institutions rearranging their schedules around it."}},{"id":"asa-025","version":2,"slug":"taiwanese-hokkien-a-mother-tongue-lost-within-a-generation","contentType":"language","category":"languages","title":{"ar":"هوكين تايوان: لغة أم تضيع خلال جيل","de":"Taiwanisch-Hokkien: eine Muttersprache, die in einer Generation verloren geht","en":"Taiwanese Hokkien: a mother tongue lost within a generation"},"deck":{"ar":"لغة كانت لسان حال معظم العائلات قبل 1945، تراجعت أمام الماندرين في المدارس والتلفزيون، فبقي الفهم وصار الكلام نادراً.","de":"Bis 1945 war Hokkien die Alltagssprache der meisten Familien; Schulen und Fernsehen drängten es zurück. Verstehen blieb, Sprechen schwand.","en":"Before 1945 it was the everyday language of most families; schools and television pushed it back. Understanding survived, speaking faded."},"teaser":{"ar":"كيف تحوّلت لغة العائلة اليومية إلى مهارة سلبية عند الأجيال الشابة في المدن التايوانية؟","de":"Warum verstehen viele junge Städter Taiwanisch-Hokkien noch, sprechen es aber kaum mehr – und was ändert sich langsam?","en":"Why do many younger urban Taiwanese still understand Hokkien but rarely speak it, and what is slowly changing?"},"readingMinutes":1,"sections":{"ar":[{"heading":"لغة البيت قبل الماندرين","paragraphs":["كانت هوكين التايوانية لغة الحياة اليومية لمعظم العائلات في تايوان قبل 1945، ولا تزال اللغة السلفية لأكثرية السكان. بعد وصول الكومينتانغ عام 1949، رُوّجت الماندرين لغةً وطنية، وعاقبت قواعد المدارس التلاميذ على التحدث بالهوكين، وفضّل التلفزيون الماندرين طويلاً.","النتيجة فهم واسع لكن طلاقة نشطة تتراجع، خصوصاً بين الشبان في المدن. ويختلف هذا الوضع بحدة بحسب المنطقة والجيل والعائلة، كما أن للهكة ولغات السكان الأصليين حركات إحياء خاصة بها، وتبقى الماندرين مهيمنة في الحياة العامة."]},{"heading":"إحياء متأخر وكتابة ملتبسة","paragraphs":["أُعيد تعليم اللغات المحلية منذ التسعينيات، وظهرت الهوكين في الحملات والأغاني الشعبية والترجمة المرئية. لكن غياب نظام كتابة معياري واحد يجعل النصوص تخلط بين المقاطع الصينية والرومنة ومقاطع مبتكرة، ما يعقّد التدريس.","مثال متكرر: جدة تسأل طفلاً «هل أكلت؟» تحيةً، فيفهم ويجيب بالماندرين، فتعيد السؤال بالهوكين."]}],"de":[{"heading":"Die Sprache des Hauses vor dem Mandarin","paragraphs":["Vor 1945 war Taiwanisch-Hokkien die Alltagssprache der meisten Familien in Taiwan und ist bis heute die Herkunftssprache der Bevölkerungsmehrheit. Nach der Ankunft der Kuomintang 1949 wurde Mandarin als Nationalsprache gefördert; Schulregeln bestraften Schüler für Hokkien, und das Fernsehen bevorzugte lange Mandarin.","Das Ergebnis ist ein weit verbreitetes passives Verstehen bei abnehmender aktiver Sprachfähigkeit, besonders unter jüngeren Stadtbewohnern. Die Lage unterscheidet sich stark nach Region, Generation und Familie; Hakka und indigene Sprachen haben eigene Revitalisierungsbewegungen, und Mandarin bleibt im öffentlichen Leben dominant."]},{"heading":"Späte Förderung und uneinheitliche Schrift","paragraphs":["Seit den 1990er-Jahren wurde muttersprachlicher Unterricht wieder eingeführt; Hokkien erscheint heute in Kampagnen, Popmusik und Untertiteln. Doch es gibt kein einheitliches Schriftsystem, sodass Texte chinesische Zeichen, Romanisierung und erfundene Zeichen mischen – was den Unterricht erschwert.","Oft fragt eine Großmutter ein Kind chia̍h pá--bē („Hast du gegessen?“) als Gruß; das Kind versteht, antwortet aber auf Mandarin, und sie wiederholt die Frage auf Hokkien."]}],"en":[{"heading":"The language of home before Mandarin","paragraphs":["Taiwanese Hokkien was the everyday language of most families in Taiwan before 1945 and remains the ancestral language of a majority of the population. After the Kuomintang arrived in 1949, Mandarin was promoted as the national language; school rules punished pupils for speaking Hokkien, and television long favoured Mandarin.","The result is widespread passive understanding but declining active fluency, especially among younger urban Taiwanese. Fluency varies sharply by region, generation and family; Hakka and Indigenous languages have their own revival movements, and Mandarin remains dominant in public life."]},{"heading":"Late revival and an unsettled script","paragraphs":["Local-language education was reintroduced from the 1990s, and Hokkien now appears in campaigns, pop music and subtitles. But the language has no single standard writing system, so texts mix Chinese characters, romanisation and invented characters, which complicates teaching.","A grandmother often asks a child chia̍h pá--bē (have you eaten?) as a greeting; the child understands but answers in Mandarin, and she repeats the question in Hokkien."]}]},"context":{"countries":["TW"],"region":"Taiwan","continent":"asia","languages":["zh"],"period":"contemporary"},"tags":["languages","Taiwan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Taiwanese Hokkien","de":"Taiwanese Hokkien","en":"Taiwanese Hokkien"},"url":"https://en.wikipedia.org/wiki/Taiwanese_Hokkien","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Languages of Taiwan","de":"Languages of Taiwan","en":"Languages of Taiwan"},"url":"https://en.wikipedia.org/wiki/Languages_of_Taiwan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"جدة تسأل طفلاً chia̍h pá--bē (هل أكلت؟) تحيةً؛ يفهم الطفل لكنه يجيب بالماندرين، فتعيد الجدة السؤال بالهوكين.","de":"Eine Großmutter fragt ein Kind chia̍h pá--bē („Hast du gegessen?“) als Gruß; das Kind versteht, antwortet aber auf Mandarin, und die Großmutter wiederholt die Frage auf Hokkien.","en":"A grandmother asks a child chia̍h pá--bē (have you eaten?) as a greeting; the child understands but answers in Mandarin, and the grandmother repeats the question in Hokkien."},"misunderstanding":{"ar":"يُفهم الفهم السلبي أحياناً كإتقان كامل، لكن القدرة على الفهم لا تعني القدرة على الكلام بطلاقة.","de":"Passives Verstehen wird oft mit voller Beherrschung verwechselt, doch Verstehen bedeutet nicht automatisch flüssiges Sprechen.","en":"Passive understanding is often mistaken for full command, but being able to follow a language does not mean being able to speak it fluently."},"comparison":{"ar":"يشبه الأمر عائلات تفهم لغة الأجداد لكنها تتواصل مع أطفالها بلغة المدرسة والمهنة.","de":"Ähnlich geht es Familien, die die Sprache der Großeltern verstehen, mit Kindern aber in der Schul- und Berufssprache reden.","en":"It resembles families who understand their grandparents' language but raise children in the language of school and work."},"expression":{"original":"食飽未","language":"臺灣話","gloss":{"ar":"هل أكلت حتى الشبع؟ تحية يومية شائعة","de":"Hast du schon gegessen? – ein alltäglicher Gruß","en":"have you eaten yet? - a common everyday greeting"},"usage":{"ar":"تُقال عند اللقاء كسؤال ودّي عن الحال، لا كدعوة فعلية للطعام.","de":"Wird bei Begegnungen freundlich als Frage nach dem Wohlbefinden gesagt, nicht als echte Einladung zum Essen.","en":"Said warmly when meeting someone as a way of asking how they are, not as a real invitation to eat."},"transliteration":"chia̍h pá--bē"}},{"id":"asa-026","version":2,"slug":"taiwan-s-night-markets-the-street-as-the-family-dining-room","contentType":"scene","category":"cities-and-community","title":{"ar":"ليلة السوق في تايوان","de":"Nachtmärkte als Esszimmer Taiwans","en":"Taiwan's Night Markets as Dining Rooms"},"deck":{"ar":"أسواق الليل في تايوان ليست أماكن للطعام فقط، بل غرف طعام عائلية تمتد على الرصيف حتى وقت متأخر.","de":"In Taiwans Nachtmärkten wird die Straße zum gemeinsamen Esszimmer, in dem Familien und Nachbarn bis spät am Abend zusammenkommen.","en":"On Taiwan's night markets the street becomes a shared family dining room, where generations eat side by side until late."},"teaser":{"ar":"من مهرجانات المعابد إلى موائد قابلة للطي، يتحول الشارع مساءً إلى مطبخ جماعي يجمع الأجيال على وجبة واحدة.","de":"Zwischen Tempel und Straßenküche essen Großeltern, Kinder und Pendler an einem Ort – jeder Stand mit eigener Spezialität und eigenem Ruf.","en":"From temple fairs to folding tables, evening streets turn into a communal kitchen where grandparents, children and commuters share one meal."},"readingMinutes":1,"sections":{"ar":[{"heading":"من المعبد إلى العشاء","paragraphs":["تنتشر أسواق الليل في معظم مدن تايوان، حيث تقدم الأكشاك الوجبات الخفيفة والمشروبات والبضائع الصغيرة حتى ساعة متأخرة. نشأت هذه الأسواق من مهرجانات المعابد والأسواق المسائية، ولا يزال كثير منها قريباً من معبد ينتقل إليه الناس من العبادة إلى العشاء.","يتخصص كل كشك في صنف واحد: هذا يبيع عجة المحار فقط، وذاك الحلوى المجروشة فقط، وتنتشر السمعة بالكلام المتداول ومدونات الطعام."]},{"heading":"الشارع كغرفة عائلية","paragraphs":["تعامل العائلات السوق كغرفة طعام: يؤدي الأطفال واجباتهم على طاولات قابلة للطي، ويجلس الأجداد مع الشاي، ويقتنص الموظفون عشاءهم في طريقهم إلى البيت. يختلف حجم الأسواق وطابعها اختلافاً كبيراً بين مدينة وأخرى وبين جيل وآخر، فبعضها سياحي وبعضها محلي الطابع.","غيّرت السياحة ولوائح النظافة هذه الأسواق، فانتقل بعضها الشهير إلى الداخل أو أصبحت الشوارع المحيطة به مخصصة للمشاة."]}],"de":[{"heading":"Vom Tempel zum Abendessen","paragraphs":["Nachtmärkte sind abendliche Straßenessensviertel in den meisten taiwanesischen Städten, wo Stände bis spät Snacks, Getränke und kleine Waren verkaufen. Sie entstanden aus Tempelfesten und Abendmärkten, und viele liegen noch nahe einem Tempel, wo die Menge vom Gebet zum Abendessen übergeht.","Jeder Stand ist spezialisiert: einer verkauft nur Austernomelett, ein anderer nur Eis mit zerkleinertem Eis, und der Ruf verbreitet sich durch Mundpropaganda und Foodblogs."]},{"heading":"Die Straße als Wohnzimmer","paragraphs":["Familien nutzen den Markt als Esszimmer: Kinder machen Hausaufgaben an Klapptischen, Großeltern sitzen beim Tee, Büroangestellte holen ihr Abendessen auf dem Heimweg. Größe und Charakter der Märkte unterscheiden sich stark je nach Region und Generation, manche sind touristisch, andere bodenständig.","Tourismus und Hygienevorschriften haben die Märkte verändert; einige berühmte zogen in Gebäude um oder ihre Straßen wurden für Fußgänger geöffnet."]}],"en":[{"heading":"From Temple to Dinner","paragraphs":["Night markets are evening street-food districts in most Taiwanese cities, with stalls selling snacks, drinks and small goods until late. They grew from temple fairs and evening markets, and many still sit near a temple, where the crowd moves from worship to dinner.","Stalls specialise: one sells only oyster omelettes, another only shaved ice, and reputations spread by word of mouth and food blogs."]},{"heading":"The Street as a Living Room","paragraphs":["Families treat the market as a dining room: children do homework on folding tables, grandparents sit with tea, and office workers grab dinner on the way home. Markets differ greatly in size and authenticity between regions and generations, with tourist-oriented ones raising prices.","Tourism and hygiene regulation have changed the markets, with some famous ones moving indoors or pedestrianising surrounding streets."]}]},"context":{"countries":["TW"],"region":"Taiwan","continent":"asia","languages":["zh"],"period":"contemporary"},"tags":["cities-and-community","Taiwan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Night market","de":"Night market","en":"Night market"},"url":"https://en.wikipedia.org/wiki/Night_market","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Taiwanese cuisine","de":"Taiwanese cuisine","en":"Taiwanese cuisine"},"url":"https://en.wikipedia.org/wiki/Taiwanese_cuisine","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"ليلة جمعة تسير عائلة في المسار نفسه: طبق نودلز عند كشك، ودجاج مقلي عند آخر، ثم حلوى مجروشة يتقاسمونها على طاولة زاوية بينما تمر الدراجات البخارية ببطء.","de":"An einem Freitagabend geht eine Familie dieselbe Runde: eine Schale Nudeln an einem Stand, frittiertes Huhn am nächsten, dann geteiltes Eis an einem Ecktisch, während Roller vorbeifahren.","en":"On a Friday night a family walks the same route: a bowl of noodles at one stall, fried chicken at another, then shaved ice shared at a corner table while scooters edge past."},"misunderstanding":{"ar":"يظن بعض الزوار أن السوق مكان واحد للوجبات السريعة، لكنه شبكة أكشاك متخصصة لكل منها صنف واحد وسمعة خاصة.","de":"Manche Besucher halten den Markt für einen einzigen Imbiss, doch er ist ein Netz spezialisierter Stände mit je einer Spezialität.","en":"Some visitors expect one big restaurant, but the market is a network of specialised stalls, each with a single dish and its own reputation."},"comparison":{"ar":"يشبه السوق مطعم العائلة الممتد في الهواء الطلق، لكنه يعتمد على التنقل بين الأكشاك بدل الجلوس في مكان واحد.","de":"Der Markt wirkt wie ein Familienrestaurant unter freiem Himmel, doch man wandert von Stand zu Stand statt an einem Tisch zu bleiben.","en":"It works like a family restaurant spread outdoors, except you move from stall to stall instead of staying at one table."}},{"id":"asa-027","version":2,"slug":"kowloon-walled-city-the-densest-place-people-ever-called-home","contentType":"note","category":"cities-and-community","title":{"ar":"مدينة كاولون المسورة: أكثف مكان سكنه البشر","de":"Kowloon Walled City: der dichteste Wohnort","en":"Kowloon Walled City: the densest home"},"deck":{"ar":"كيف تحولت قلعة صغيرة إلى جيب حضري مكتظ عاش فيه آلاف العائلات وسط متاهة من الأزقة والأسطح.","de":"Wie eine kleine Festung zu einer überfüllten urbanen Enklave wurde, in der Tausende Familien in einem Labyrinth aus Gassen und Dächern lebten.","en":"How a small fort became a packed urban enclave where thousands of families lived in a maze of alleys and rooftops."},"teaser":{"ar":"في 2.6 هكتار فقط، عاش نحو 33 ألف شخص في مبانٍ غير مخطط لها، شكلت تجربة فريدة في الحياة الحضرية.","de":"Auf nur 2,6 Hektar lebten schätzungsweise 33.000 Menschen in ungeplanten Gebäuden – eine einzigartige städtische Erfahrung.","en":"On just 2.6 hectares, an estimated 33,000 people lived in unplanned buildings, creating a unique experiment in urban life."},"readingMinutes":1,"sections":{"ar":[{"heading":"حياة في متاهة","paragraphs":["بدأت المدينة المسورة كقلعة تشينغ، ثم أصبحت جيبًا صينيًا لا تديره هونغ كونغ البريطانية، فامتلأت بالمهاجرين والورش والعيادات.","داخل الأزقة الضيقة، شكلت السلالم والأسطح متاهة؛ عمل أطباء أسنان ومصانع نودلز وأطباء غير مرخصين في مساحات نادرًا ما تظهر على الخرائط الرسمية.","يصف السكان تسلق سلالم مظلمة للوصول إلى سطح حيث يطير الأطفال الطائرات الورقية، بينما يجلس طبيب أسنان في غرفة بلا ضوء طبيعي."]},{"heading":"نهاية وإرث","paragraphs":["اتفقت بريطانيا والصين على هدم المدينة المسورة في عام 1987، وأُخلي الموقع بين عامي 1993 و1994، ليحل محله حديقة.","أصبحت المدينة مرجعًا عالميًا للعمران غير الرسمي الكثيف، يدرسه المعماريون وتستشهد به الأفلام والألعاب.","تختلف روايات السكان باختلاف الأجيال والمناطق؛ فالبعض يتذكر التضامن الاجتماعي، بينما يرى آخرون أن الأسطورة غالبًا ما تتجاوز الأدلة."]}],"de":[{"heading":"Leben im Labyrinth","paragraphs":["Die Kowloon Walled City begann als Qing-Festung, wurde zu einer chinesischen Exklave, die das britische Hongkong nicht verwaltete, und füllte sich mit Squattern, Werkstätten und Kliniken.","Im Inneren bildeten enge Treppenhäuser und Dächer ein Labyrinth; Zahnärzte, Nudelfabriken und nicht zugelassene Ärzte arbeiteten in Räumen, die auf offiziellen Karten kaum verzeichnet waren.","Bewohner beschreiben den Aufstieg über unbeleuchtete Treppen zu einem Dach, auf dem Kinder Drachen steigen ließen, während unten ein Zahnarztstuhl in einem Raum ohne Tageslicht stand."]},{"heading":"Ende und Vermächtnis","paragraphs":["Großbritannien und China vereinbarten 1987 den Abriss, und das Gelände wurde zwischen 1993 und 1994 geräumt; heute befindet sich dort ein Park.","Die Walled City gilt weltweit als Referenz für dichte informelle Urbanität, wird von Architekten studiert und in Filmen und Spielen zitiert.","Die Erzählungen der Bewohner variieren je nach Generation und Region; manche erinnern sich an sozialen Zusammenhalt, andere sehen den Mythos oft größer als die Belege."]}],"en":[{"heading":"Life in the maze","paragraphs":["The Kowloon Walled City began as a Qing fort, became a Chinese exclave that British Hong Kong did not administer, and filled with squatters, workshops and clinics.","Inside, narrow stairways and rooftops formed a maze; dentists, noodle factories and unlicensed doctors operated in spaces that official maps barely recorded.","Residents describe climbing unlit stairs to a rooftop where children flew kites, while below a dentist's chair sat in a room with no natural light."]},{"heading":"End and legacy","paragraphs":["Britain and China agreed to demolish it in 1987, and the site was cleared between 1993 and 1994; a park now occupies the location.","The walled city has become a global reference for dense informal urbanism, studied by architects and cited in films and games.","Residents' accounts vary by generation and region; some recall social solidarity, while others note that the mythology often outruns the evidence."]}]},"context":{"countries":["HK"],"region":"Hong Kong","continent":"asia","languages":["zh","en"],"period":"contemporary"},"tags":["cities-and-community","Hong Kong"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kowloon Walled City","de":"Kowloon Walled City","en":"Kowloon Walled City"},"url":"https://en.wikipedia.org/wiki/Kowloon_Walled_City","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Hong Kong","de":"Hong Kong","en":"Hong Kong"},"url":"https://en.wikipedia.org/wiki/Hong_Kong","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يصف السكان تسلق سلالم مظلمة للوصول إلى سطح حيث يطير الأطفال الطائرات الورقية، بينما يجلس طبيب أسنان في غرفة بلا ضوء طبيعي.","de":"Bewohner beschreiben den Aufstieg über unbeleuchtete Treppen zu einem Dach, auf dem Kinder Drachen steigen ließen, während unten ein Zahnarztstuhl in einem Raum ohne Tageslicht stand.","en":"Residents describe climbing unlit stairs to a rooftop where children flew kites, while below a dentist's chair sat in a room with no natural light."},"misunderstanding":{"ar":"غالبًا ما يُفترض أن المدينة المسورة كانت نموذجًا لكل سكن هونغ كونغ، لكنها كانت استثناءً فريدًا وظروفها لا تمثل الوضع العام.","de":"Oft wird angenommen, die Walled City sei typisch für Hongkongs Wohnverhältnisse gewesen, doch sie war eine einzigartige Ausnahme.","en":"It is often assumed that the walled city was typical of Hong Kong housing, but it was a unique exception with conditions that did not represent the general situation."},"comparison":{"ar":"على عكس الأحياء الحضرية المخططة، كانت المدينة المسورة تنمو عضويًا دون تنظيم، مما جعلها حالة استثنائية في تاريخ الإسكان.","de":"Im Gegensatz zu geplanten Stadtvierteln wuchs die Walled City organisch und ohne Regulierung, was sie zu einem Sonderfall in der Wohnungsgeschichte macht.","en":"Unlike planned urban neighborhoods, the walled city grew organically without regulation, making it an exceptional case in housing history."}},{"id":"asa-028","version":2,"slug":"macanese-a-creole-community-built-between-empires","contentType":"feature","category":"migration-and-identity","title":{"ar":"ماكاو: مجتمع كريولي بين إمبراطوريتين","de":"Macanesen: eine Kreolengemeinschaft zwischen Imperien","en":"Macanese: a creole community between empires"},"deck":{"ar":"من أصول أوراسية، يحمل الماكانيون إرثاً برتغالياً وصينياً وجنوب آسيوي، يعيشون هوية تتجاوز حدود الإمبراطوريات.","de":"Von portugiesischen Siedlern, chinesischen und südasiatischen Händlern geprägt, leben die Macanesen eine Identität, die über Imperien hinausreicht.","en":"Descended from Portuguese settlers, Chinese and South Asian merchants, the Macanese carry a Eurasian identity that outlives the empires that shaped it."},"teaser":{"ar":"في ماكاو، تشكّل مجتمع الماكانيين من البرتغاليين والصينيين والتجار الجنوب آسيويين، فأنتجوا لغة كريولية ومطبخاً فريداً يعيش اليوم في الشتات.","de":"In Macau entstand aus Portugiesen, Chinesen und südasiatischen Händlern eine eurasische Gemeinschaft mit eigener Kreolsprache und Küche – heute vor allem in der Diaspora lebendig.","en":"In Macau, Portuguese, Chinese and South Asian lives intertwined over four centuries, producing a creole language and cuisine now kept alive largely in diaspora."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور أوراسية في ميناء عالمي","paragraphs":["نشأ الماكانيون في ماكاو على مدى أربعة قرون من اختلاط المستوطنين البرتغاليين بتجار صينيين وجنوب آسيويين وبأشخاص استُعبدوا وعاشوا في المدينة. هذا التمازج جعلهم مجتمعاً أوراسياً متميزاً، يحمل في دمه وذاكرته أثر الإمبراطوريات التي مرّت بالميناء.","خلال الإدارة البرتغالية، احتل المجتمع موقعاً وسطاً في السلم الاستعماري، بين السلطة البرتغالية والسكان الصينيين. هذا الموقع منحهم أدواراً وسيطة في التجارة والإدارة، لكنه جعل هويتهم عرضة للتغير مع تحولات السلطة."]},{"heading":"لغة كريولية ومطبخ مزدوج","paragraphs":["طوّر الماكانيون لغة كريولية خاصة بهم تُعرف بـ«باتوا»، تمزج البرتغالية بالصينية والملايوية وغيرها. كما ابتكروا مطبخاً يجمع مكونات برتغالية وصينية وهندية وماليزية، في أطباق مثل «مينشي» و«كابيلا» التي تُعد رموزاً للهوية.","لكن «باتوا» أصبحت اليوم مهددة بالانقراض، إذ لم يعد هناك سوى عدد قليل من المتحدثين بها بطلاقة. ورغم ذلك، لا يزال المطبخ حياً في البيوت والمهرجانات، حيث يُستخدم كوسيلة للحفاظ على الذاكرة الجماعية."]},{"heading":"شتات يعيد تعريف الهوية","paragraphs":["بعد تسليم ماكاو إلى الصين عام 1999، هاجر كثير من الماكانيين إلى البرتغال وأستراليا وكندا. وهناك، أعادوا تشكيل هويتهم عبر شبكات العائلة والمهرجانات الغذائية وجمعيات التراث، بدلاً من الاستخدام اليومي للغة.","تختلف الهوية الماكانية بين ماكاو والبرتغال والشتات، كما تتباين بين الأجيال: فبعض الشباب يتعلم «باتوا» من الأجداد، وآخرون يتمسكون بالمطبخ كعلامة انتماء. هذا التنوع يعكس حيوية مجتمع صغير لكنه متشابك.","يُظهر الماكانيون كيف تنتج مدن الموانئ ثقافات هجينة تعيش أطول من الإمبراطوريات التي صنعتها. فالهوية هنا ليست حدوداً ثابتة، بل حواراً مستمراً بين الأجيال والأماكن."]}],"de":[{"heading":"Eurasische Wurzeln im Hafen","paragraphs":["Über vier Jahrhunderte entstand in Macau die Gemeinschaft der Macanesen aus portugiesischen Siedlern, chinesischen und südasiatischen Händlern sowie versklavten Menschen, die in der Stadt lebten. Diese Mischung machte sie zu einer eurasischen Gemeinschaft, die die Spuren der Imperien in sich trägt.","Unter portugiesischer Verwaltung nahmen sie eine mittlere Position in der Kolonialgesellschaft ein, zwischen portugiesischer Obrigkeit und chinesischer Bevölkerung. Diese Rolle verschaffte ihnen Aufgaben im Handel und in der Verwaltung, machte ihre Identität aber anfällig für politische Verschiebungen."]},{"heading":"Kreolsprache und doppelte Küche","paragraphs":["Die Macanesen entwickelten eine eigene Kreolsprache, Patuá, die Portugiesisch mit Chinesisch, Malaiisch und anderen Einflüssen verbindet. Ebenso entstand eine Küche aus portugiesischen, chinesischen, indischen und malaiischen Zutaten, mit Gerichten wie Minchi und Capela, die als Identitätssymbole gelten.","Doch Patuá ist heute vom Aussterben bedroht; nur wenige sprechen es noch fließend. Die Küche dagegen lebt in Haushalten und Festivals weiter und dient als Mittel, das kollektive Gedächtnis zu bewahren."]},{"heading":"Diaspora definiert Identität neu","paragraphs":["Nach der Übergabe Macaus an China 1999 wanderten viele Macanesen nach Portugal, Australien und Kanada aus. Dort formen sie ihre Identität über Familiennetzwerke, Essensfestivals und Heritage-Vereine neu, statt über den täglichen Gebrauch der Sprache.","Die macanesische Identität ist klein und intern vielfältig; sie bedeutet in Macau, Portugal und der Diaspora Unterschiedliches und variiert zwischen den Generationen. Manche Jüngere lernen Patuá von den Großeltern, andere halten an der Küche als Zugehörigkeitszeichen fest.","Die Macanesen zeigen, wie Hafenstädte hybride Kulturen hervorbringen, die die Imperien überleben, die sie schufen. Identität ist hier keine feste Grenze, sondern ein andauernder Dialog zwischen Generationen und Orten."]}],"en":[{"heading":"Eurasian roots in a port city","paragraphs":["Over four centuries in Macau, Portuguese settlers, Chinese and South Asian merchants, and enslaved people lived and mixed, forming the Macanese as a distinct Eurasian community. This blending left the imprint of successive empires in their families and memories.","Under Portuguese administration, the community held a middle position in colonial society, between Portuguese authority and the Chinese population. That role gave them intermediary work in trade and administration, but also made their identity sensitive to political change."]},{"heading":"Creole language and mixed cuisine","paragraphs":["The Macanese developed their own creole language, Patuá, mixing Portuguese with Chinese, Malay and other influences. They also created a cuisine combining Portuguese, Chinese, Indian and Malay ingredients, with dishes like minchi and capela serving as markers of identity.","Today Patuá is critically endangered, with very few fluent speakers left. The cuisine, however, remains alive in homes and festivals, used as a way to preserve collective memory."]},{"heading":"Diaspora redefines belonging","paragraphs":["After the 1999 handover to China, many Macanese emigrated to Portugal, Australia and Canada. There they reshape identity through family networks, food festivals and heritage associations rather than everyday use of Patuá.","Macanese identity is small and internally varied; it means different things in Macau, Portugal and the diaspora, and varies between generations. Some younger people learn Patuá from grandparents, while others hold on to cuisine as a sign of belonging.","The community illustrates how port cities produce hybrid cultures that outlive the empires that made them. Identity here is not a fixed border but an ongoing conversation between generations and places."]}]},"context":{"countries":["MO"],"region":"Macau","community":"Macanese","continent":"asia","languages":["pt","zh"],"period":"contemporary"},"tags":["migration-and-identity","Macau"],"sources":[{"organization":"Wikipedia","title":{"ar":"Macau","de":"Macau","en":"Macau"},"url":"https://en.wikipedia.org/wiki/Macau","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Macanese Patois","de":"Macanese Patois","en":"Macanese Patois"},"url":"https://en.wikipedia.org/wiki/Macanese_Patois","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة ماكانية في لشبونة تطبخ «مينشي» و«كابيلا» كل أحد، وتتحدث البرتغالية في البيت، وتتبادل عبارات «باتوا» مع الأقارب في ماكاو عبر مكالمات الفيديو.","de":"Eine macanesische Familie in Lissabon kocht sonntags Minchi und Capela, spricht zu Hause Portugiesisch und tauscht per Videoanruf Patuá-Wendungen mit Verwandten in Macau aus.","en":"A Macanese family in Lisbon cooks minchi and capela on Sundays, speaks Portuguese at home and trades Patuá phrases with relatives in Macau over video calls."},"misunderstanding":{"ar":"ليس كل من يحمل اسماً برتغالياً في ماكاو ماكانياً، وليس كل ماكاني يتقن «باتوا»؛ فالهوية تُبنى عبر العائلة والذاكرة أكثر من اللغة.","de":"Nicht jeder mit portugiesischem Namen in Macau ist macanesisch, und nicht jeder Macanese spricht Patuá; Identität entsteht eher über Familie und Erinnerung als über Sprache.","en":"Not everyone with a Portuguese surname in Macau is Macanese, and not every Macanese speaks Patuá; identity is built through family and memory more than language."},"comparison":{"ar":"يشبه الماكانيون مجتمعات كريولية أخرى في مدن الموانئ، حيث يولد الهجين من التجارة والاستعمار ثم يستمر بعد زوال الإمبراطوريات.","de":"Die Macanesen ähneln anderen Kreolengemeinschaften in Hafenstädten, wo Hybridität aus Handel und Kolonialismus entsteht und nach dem Ende der Imperien fortbesteht.","en":"The Macanese resemble other creole communities in port cities, where hybridity is born from trade and colonialism and persists after empires fade."}},{"id":"asa-029","version":2,"slug":"naadam-three-sports-one-national-holiday","contentType":"note","category":"games-and-leisure","title":{"ar":"نادام: ثلاثة رياضات وعطلة وطنية","de":"Naadam: drei Sportarten, ein Nationalfest","en":"Naadam: three sports, one national holiday"},"deck":{"ar":"مهرجان منغولي يجمع المصارعة وسباق الخيل والرماية في منتصف يوليو، ويجمع العائلات من المدن والمراعي.","de":"Mongolisches Festival im Juli mit Ringen, Pferderennen und Bogenschießen, das Familien aus Stadt und Steppe zusammenbringt.","en":"Mongolia's July festival of wrestling, horse racing and archery brings families together from the capital and the steppe."},"teaser":{"ar":"مهرجان نادام الوطني في منغوليا يجمع ثلاث رياضات تقليدية في منتصف يوليو، ويحتفل به الناس في العاصمة والأرياف على حد سواء.","de":"Naadam ist Mongoliens Nationalfest im Juli: Ringen, Pferderennen und Bogenschießen bringen Menschen in Ulaanbaatar und in den Provinzen zusammen.","en":"Naadam is Mongolia's national festival in mid-July, when wrestling, horse racing and archery draw people together in Ulaanbaatar and provincial towns."},"readingMinutes":1,"sections":{"ar":[{"heading":"ثلاثة ألعاب في قلب الصيف","paragraphs":["يُقام مهرجان نادام في منتصف يوليو، ويقوم على ثلاث رياضات: المصارعة وسباق الخيل والرماية. يتصارع الرجال دون فئات وزن، وتُقام سباقات الخيل في السهوب المفتوحة بأيدي فرسان من الأطفال، وتُطلق السهام في فرق.","يفتتح المهرجان باحتفالات مفصلة في أولان باتور، لكنه يُحتفل به أيضاً في البلدات الريفية ومستوطنات الرعاة بمسابقات محلية. وتختلف القواعد والأحجام من مقاطعة إلى أخرى، كما أن نادام المدن أصبح جزئياً عرضاً رسمياً.","تختلف ممارسة نادام بين الأجيال والمناطق؛ فالشباب في المدن يتابعون المسابقات عبر الشاشات، بينما يحافظ الرعاة في البوادي على طقوسهم الخاصة."]},{"heading":"عائلة وسوق وذاكرة","paragraphs":["أدرجت اليونسكو مهرجان نادام في قائمة التراث الثقافي غير المادي عام 2010، لما له من دور في نقل المهارات البدوية والقيم الاجتماعية.","نادام أيضاً مناسبة للقاء العائلات والتجارة، مع أكشاك طعام وحفلات وموسيقى وعودة الزوار من العاصمة.","في نادام محلي، يمتطي طفل جواداً لمسافة خمسة عشر كيلومتراً، ويرقص المصارعون بأحذيتهم المزخرفة نحو الحلبة، وتنصب العائلات خيامها حول أطراف الميدان."]}],"de":[{"heading":"Drei Spiele im Sommer","paragraphs":["Naadam findet Mitte Juli statt und ruht auf drei Sportarten: Ringen, Pferderennen und Bogenschießen. Ringer treten ohne Gewichtsklassen an, Pferderennen führen über offene Steppe mit kindlichen Jockeys, und Bogenschützen schießen in Teams.","Eröffnet wird das Fest mit aufwendigen Zeremonien in Ulaanbaatar, gefeiert aber auch in Provinzstädten und Hirten siedlungen mit lokalen Wettbewerben. Regeln und Maßstäbe unterscheiden sich je nach Provinz, und das städtische Naadam ist teils staatliches Spektakel.","Wie Naadam gelebt wird, variiert regional und zwischen Generationen: Junge Städter verfolgen Wettkämpfe auf Bildschirmen, Hirten draußen halten an eigenen Ritualen fest."]},{"heading":"Familie, Markt und Erinnerung","paragraphs":["2010 nahm die UNESCO das Naadam-Fest in die Liste des immateriellen Kulturerbes auf und würdigte seine Rolle bei der Weitergabe nomadischer Fähigkeiten und sozialer Werte.","Naadam ist zugleich Familientreffen und Handelsanlass, mit Essensständen, Konzerten und Besuchern, die aus der Hauptstadt zurückkehren.","Bei einem Naadam in der Provinz reitet ein Kind 15 Kilometer weit, Ringer in genagelten Stiefeln tanzen in den Ring, und Familien bauen Filzzelte am Rand des Feldes auf."]}],"en":[{"heading":"Three games in high summer","paragraphs":["Naadam is held in mid-July and is built around three sports: wrestling, horse racing and archery. Wrestlers compete without weight classes, horse races are run across open steppe by child jockeys, and archery targets are shot in teams.","The festival opens with elaborate ceremonies in Ulaanbaatar, but it is also celebrated in provincial towns and herding settlements with local competitions. Rules and scales vary by province, and urban Naadam is partly a state spectacle.","How Naadam is lived varies by region and generation: young city dwellers follow the contests on screens, while herders outside keep their own rituals."]},{"heading":"Family, market and memory","paragraphs":["UNESCO listed the Naadam festival as intangible cultural heritage in 2010, noting its role in transmitting nomadic skills and social values.","Naadam is also a family reunion and trading occasion, with food stalls, concerts and visitors returning from the capital.","In a provincial Naadam a child jockey rides a horse for 15 kilometres, wrestlers in studded boots dance into the ring, and families set up felt tents around the edge of the field."]}]},"context":{"countries":["MN"],"region":"Mongolia","continent":"asia","languages":["mn"],"period":"contemporary"},"tags":["games-and-leisure","Mongolia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Naadam","de":"Naadam","en":"Naadam"},"url":"https://en.wikipedia.org/wiki/Naadam","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Mongolian wrestling","de":"Mongolian wrestling","en":"Mongolian wrestling"},"url":"https://en.wikipedia.org/wiki/Mongolian_wrestling","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في نادام محلي، يمتطي طفل جواداً لمسافة خمسة عشر كيلومتراً، ويرقص المصارعون بأحذيتهم المزخرفة نحو الحلبة، وتنصب العائلات خيامها حول أطراف الميدان.","de":"Bei einem Naadam in der Provinz reitet ein Kind 15 Kilometer weit, Ringer in genagelten Stiefeln tanzen in den Ring, und Familien bauen Filzzelte am Rand des Feldes auf.","en":"In a provincial Naadam a child jockey rides a horse for 15 kilometres, wrestlers in studded boots dance into the ring, and families set up felt tents around the edge of the field."},"misunderstanding":{"ar":"يُظن أحياناً أن نادام عرض سياحي في العاصمة فقط، لكنه في جوهره عيد شعبي تعيشه البلدات والمراعي بمسابقاتها المحلية.","de":"Manchmal gilt Naadam nur als touristische Show der Hauptstadt, doch im Kern ist es ein Volksfest, das Provinzstädte und Hirtenlager mit eigenen Wettbewerben leben.","en":"Naadam is sometimes mistaken for a tourist show in the capital only, but at heart it is a people's holiday lived in provincial towns and herding camps with their own competitions."},"comparison":{"ar":"يشبه نادام المهرجانات الوطنية التي تجمع الرياضة واللقاء العائلي، لكن ما يميزه أنه ينقل مهارات الحياة البدوية من جيل إلى جيل.","de":"Naadam ähnelt nationalen Festen, die Sport und Familientreffen verbinden, doch es gibt nomadische Fertigkeiten über Generationen weiter.","en":"Naadam resembles national festivals that combine sport with family reunion, yet it stands apart by passing nomadic skills from one generation to the next."}},{"id":"asa-030","version":2,"slug":"namaste-a-greeting-that-measures-respect","contentType":"note","category":"communication","title":{"ar":"ناماستي: تحية تقيس الاحترام","de":"Namaste: Ein Gruß, der Respekt misst","en":"Namaste: a greeting that measures respect"},"deck":{"ar":"كيف تنقل تحية بسيطة بالكفين معنى الاحترام في جنوب آسيا.","de":"Wie eine einfache Geste mit zusammengelegten Handflächen in Südasien Respekt ausdrückt.","en":"How a simple gesture with pressed palms carries respect across South Asia."},"teaser":{"ar":"تحية بكفين مضمومتين عند الصدر، تستخدمها مجتمعات هندوسية وبوذية وجاينية وسيخية، وتحمل معنى أعمق من مجرد التحية.","de":"Ein Gruß mit gefalteten Händen vor der Brust, verbreitet unter hinduistischen, buddhistischen, jainistischen und sikhischen Gemeinschaften – mehr als ein Hallo.","en":"A greeting with palms together at the chest, used across Hindu, Buddhist, Jain and Sikh communities, means far more than a simple hello."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف تُؤدى التحية","paragraphs":["ناماستي تحية تُؤدى بضم الكفين عند الصدر، مع انحناءة خفيفة أحيانًا، وتنتشر بين مجتمعات هندوسية وبوذية وجاينية وسيخية في جنوب آسيا.","الكلمة من السنسكريتية، وتُفسَّر غالبًا بـ«أنحني لك»، إذ تعترف بذات داخلية مشتركة بدل التواصل الجسدي.","تصلح للتحية والوداع معًا، وتتفادى مشكلة المصافحة المرتبطة بتفاوت المكانة والطهارة الطقسية."]},{"heading":"من يبدأ ومن يزيد","paragraphs":["عادةً يبدأ الأصغر بتحية الأكبر، وصيغة أكثر تفصيلًا مثل ناماسكار أو انحناءة أعمق تعبّر عن احترام أكبر.","تختلف الأشكال بحسب المنطقة والدين، ويزداد الهنود الحضريون مزجًا بين ناماستي والمصافحة أو العناق، كما يتغير معناها في استوديوهات اليوغا خارج جنوب آسيا.","انتقلت التحية عالميًا عبر اليوغا وانتشار المهاجرين، وكثيرًا ما خفّ معناها الديني ليصبح إشارة عافية."]}],"de":[{"heading":"Wie der Gruß ausgeführt wird","paragraphs":["Namaste ist ein Gruß mit vor der Brust zusammengelegten Handflächen, manchmal mit leichtem Verneigen, verbreitet unter hinduistischen, buddhistischen, jainistischen und sikhischen Gemeinschaften in Südasien.","Das Wort stammt aus dem Sanskrit und wird oft mit „Ich verneige mich vor dir“ übersetzt; es anerkennt ein gemeinsames inneres Selbst statt körperlichen Kontakts.","Es dient als Hallo und Auf Wiedersehen und vermeidet das Problem des Händedrucks bei ungleichem Status und ritueller Reinheit."]},{"heading":"Wer beginnt und wer vertieft","paragraphs":["Meist grüßt die jüngere Person zuerst eine ältere, und eine ausführlichere Form wie Namaskar oder eine tiefere Verbeugung zeigt größeren Respekt.","Die Formen unterscheiden sich je nach Region und Religion, und Stadtbewohner in Indien mischen Namaste zunehmend mit Händedruck oder Umarmung; auch in Yogastudios außerhalb Südasiens verändert sich die Bedeutung.","Durch Yoga und Diaspora ist der Gruß global geworden, oft mit abgeflachter religiöser Bedeutung als Wellness-Signal."]}],"en":[{"heading":"How the greeting is made","paragraphs":["Namaste is a greeting made with palms pressed together at the chest, sometimes with a slight bow, used across Hindu, Buddhist, Jain and Sikh communities in South Asia.","The word comes from Sanskrit and is often glossed as I bow to you, acknowledging a shared inner self rather than physical contact.","It works for both hello and goodbye and avoids the handshake problem of unequal status and ritual purity."]},{"heading":"Who starts and who deepens it","paragraphs":["A younger person usually greets an elder first, and a more elaborate form such as namaskar or a deeper bow signals greater respect.","Forms differ by region and religion, and urban Indians increasingly mix namaste with handshakes or hugs; the gesture's meaning changes in yoga studios outside South Asia.","The gesture has travelled globally through yoga and diaspora practice, often with its religious meaning flattened into a wellness signal."]}]},"context":{"countries":["IN","NP"],"region":"South Asia","continent":"asia","languages":["hi"],"period":"contemporary"},"tags":["communication","South Asia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Namaste","de":"Namaste","en":"Namaste"},"url":"https://en.wikipedia.org/wiki/Namaste","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Indian honorifics","de":"Indian honorifics","en":"Indian honorifics"},"url":"https://en.wikipedia.org/wiki/Indian_honorifics","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"طالبة تدخل صفًا في فاراناسي، تضم كفيها وتقول ناماستي للمعلّم قبل أن تجلس، فيردّ التحية بإيماءة خفيفة.","de":"Eine Schülerin betritt in Varanasi ein Klassenzimmer, legt die Handflächen zusammen und sagt Namaste zur Lehrerin, bevor sie sich setzt; die Lehrerin erwidert es mit einem kurzen Nicken.","en":"A student enters a classroom in Varanasi, presses her palms together and says namaste to the teacher before sitting; the teacher returns it with a small nod."},"misunderstanding":{"ar":"قد يُظن أن ناماستي مجرد إيماءة عافية أو تحية دينية واحدة، مع أنها تحية يومية مشتركة بين ديانات عدة.","de":"Manchmal gilt Namaste nur als Wellness-Geste oder als Gruß einer einzigen Religion, obwohl er im Alltag mehrerer Gemeinschaften verbreitet ist.","en":"It is sometimes treated as only a wellness gesture or a single religion's greeting, though it is everyday practice across several communities."},"comparison":{"ar":"بينما تعتمد المصافحة على التواصل الجسدي، تعتمد ناماستي على إشارة غير لمسية تحفظ المسافة والاحترام.","de":"Während der Händedruck auf Körperkontakt setzt, wahrt Namaste ohne Berührung Distanz und Respekt.","en":"Where a handshake relies on physical contact, namaste keeps a respectful distance without touch."},"expression":{"original":"नमस्ते","language":"हिन्दी","gloss":{"ar":"أنحني لك — مرحبًا ووداعًا","de":"Ich verneige mich vor dir – Hallo und Auf Wiedersehen","en":"I bow to you - hello and goodbye"},"usage":{"ar":"تُقال عند اللقاء والوداع، ويبدأ بها الأصغر عادةً عند تحية الأكبر.","de":"Wird zur Begrüßung und zum Abschied gesagt; meist grüßt die jüngere Person zuerst.","en":"Said at meeting and parting; a younger person usually offers it first to an elder."},"transliteration":"namaste"}},{"id":"asa-031","version":2,"slug":"jugaad-the-improvisation-people-admire-and-sometimes-resent","contentType":"note","category":"everyday-life","title":{"ar":"جوگاد: الابتكار المرحلي بين الإعجاب والانتقاد","de":"Jugaad: Improvisation zwischen Bewunderung und Unbehagen","en":"Jugaad: improvisation people admire and sometimes resent"},"deck":{"ar":"كيف يوازن الهنود بين الحلول السريعة والجودة والسلامة في حياتهم اليومية.","de":"Wie Inder mit knappen Mitteln Alltagsprobleme lösen – und wo die Grenze zur Risikobereitschaft liegt.","en":"How Indians balance quick fixes with quality and safety in daily life."},"teaser":{"ar":"مصطلح هندي يصف حلولاً مبتكرة بأقل الإمكانيات، يمتدحه البعض ويعتبره آخرون تجاوزاً للقواعد.","de":"Ein Hindi-Wort für findige Notlösungen: gefeiert als Ressourcenreichtum, kritisiert als Umgehung von Sicherheit und Vorschriften.","en":"A Hindi term for frugal, improvised solutions: praised as resourcefulness, criticised as cutting corners on safety, quality or paperwork."},"readingMinutes":1,"sections":{"ar":[{"heading":"براعة عملية في مواجهة نقص الموارد","paragraphs":["يصف جوگاد حلاً مبتكراً وقليل التكلفة، غالباً ما يُصنع من مواد متاحة. الصورة الكلاسيكية مركبة محلية تجمع بين مضخة مياه ودراجة نارية، لكن الكلمة تشمل إصلاح الأجهزة والنقل غير الرسمي.","يُحتفى به في كليات إدارة الأعمال وثقافة الشركات الناشئة، حيث يُعتبر الابتكار المقتصد قريباً منه. وتختلف مظاهره بين المناطق والطبقات والأجيال، فيظهر أكثر في المدن الصغيرة حيث تكون الخدمات أقل انتظاماً."]},{"heading":"الجانب الآخر: المخاطر والالتفاف على القواعد","paragraphs":["ينتقد البعض جوگاد لأنه قد يعني التهاون في السلامة أو الجودة أو الأوراق الرسمية، وقد يشير إلى شخص يتجاوز القواعد. الشركات الأجنبية العاملة في الهند تتعلم غالباً العمل معه بدلاً من مقاومته، لأن الحلول غير الرسمية تسد فجوات في الخدمات."]}],"de":[{"heading":"Praktische Findigkeit bei knappen Ressourcen","paragraphs":["Jugaad bezeichnet eine sparsame, improvisierte Lösung – einen Behelf aus dem, was gerade da ist – und ist ein häufig verwendeter Hindi-Begriff im indischen Englisch. Das klassische Bild ist ein selbstgebautes Fahrzeug aus Wasserpumpe und Motorrad, doch das Wort umfasst alles von reparierten Geräten bis zu informellen Transportmitteln.","In Business Schools und der Startup-Kultur wird es als Einfallsreichtum gefeiert, frugale Innovation ist ein enger Verwandter. Je nach Region, Klasse und Generation zeigt es sich unterschiedlich stark, besonders in kleineren Städten, wo Dienstleistungen weniger verlässlich sind."]},{"heading":"Die Kehrseite: Sicherheit und Regelbruch","paragraphs":["Kritiker betonen die andere Seite: Jugaad kann bedeuten, bei Sicherheit, Qualität oder Papierkram Abstriche zu machen, und das Wort kann jemanden andeuten, der Regeln beugt. Ausländische Firmen in Indien müssen oft lernen, mit ihm zu arbeiten statt dagegen, weil informelle Lösungen Lücken in der Versorgung füllen."]}],"en":[{"heading":"Practical ingenuity when resources are scarce","paragraphs":["Jugaad describes a frugal, improvised solution—a workaround made from what is at hand—and is a widely used Hindi term in Indian English. The classic image is a homemade vehicle cobbled together from a water pump and a motorcycle, but the word covers everything from repaired appliances to informal transport.","It is celebrated as resourcefulness in business schools and startup culture, where frugal innovation is a close cousin. Usage varies across regions, classes and generations, appearing most where services are less reliable, such as smaller towns and informal settlements."]},{"heading":"The flip side: safety and rule-bending","paragraphs":["Critics note the flip side: jugaad can mean cutting corners on safety, quality or paperwork, and the word can hint at someone who bends rules. Foreign companies operating in India often must learn to work with it rather than against it, since informal solutions fill gaps in services."]}]},"context":{"countries":["IN"],"region":"India","continent":"asia","languages":["hi","en"],"period":"contemporary"},"tags":["everyday-life","India"],"sources":[{"organization":"Wikipedia","title":{"ar":"Jugaad","de":"Jugaad","en":"Jugaad"},"url":"https://en.wikipedia.org/wiki/Jugaad","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Frugal innovation","de":"Frugal innovation","en":"Frugal innovation"},"url":"https://en.wikipedia.org/wiki/Frugal_innovation","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عندما ينقطع الإنترنت في المكتب قبل موعد التسليم، يربط الموظف هاتفه بالحاسوب، ويستعير شاحن جهاز من جاره، ويرسل الملف من السطح حيث الإشارة قوية.","de":"Wenn das Büro-Internet vor einer Frist ausfällt, verbindet ein Angestellter sein Handy mit dem Laptop, leiht sich ein Ladegerät vom Nachbarn und schickt die Datei vom Dach, wo das Signal stark ist.","en":"When the office internet fails before a deadline, a clerk tethers his phone, borrows a laptop charger from a neighbour and sends the file from the rooftop where the signal is strong."},"misunderstanding":{"ar":"يُفهم جوگاد أحياناً على أنه مجرد حل رديء، لكنه قد يكون هندسة حقيقية، والفرق بين الاثنين يتوقف على السياق والسلامة.","de":"Jugaad wird manchmal als bloße Pfuscherei missverstanden, doch es kann echte Ingenieurskunst sein; der Unterschied hängt von Kontext und Sicherheit ab.","en":"Jugaad is sometimes mistaken for mere shoddiness, but it can be genuine engineering; the difference depends on context and safety."},"comparison":{"ar":"يشبه جوگاد مفهوم 'الفهلوة' في بعض الثقافات العربية، لكنه أكثر ارتباطاً بالهندسة المقتصدة والظروف الاقتصادية.","de":"Ähnlich dem deutschen 'Provisorium' oder 'Notlösung', aber stärker mit frugaler Technik und wirtschaftlicher Knappheit verbunden.","en":"Similar to the English 'hack' or 'workaround', but more strongly tied to frugal engineering and economic scarcity."}},{"id":"asa-032","version":2,"slug":"dabbawalas-130-years-of-lunch-delivery-without-an-app","contentType":"note","category":"work-and-education","title":{"ar":"دبّاوالا: 130 عامًا من توصيل الغداء بدون تطبيق","de":"Dabbawalas: 130 Jahre Mittagessen ohne App","en":"Dabbawalas: 130 years of lunch delivery without an app"},"deck":{"ar":"في مومباي، يحمل عمال توصيل الغداء المنزلي صناديق الطعام إلى المكاتب كل يوم، معتمدين على رموز ملونة وثقة متبادلة.","de":"In Mumbai bringen Dabbawalas täglich hausgemachtes Mittagessen in Büros – mit farbigen Codes und gegenseitigem Vertrauen.","en":"In Mumbai, dabbawalas deliver home-cooked lunches to office workers daily, relying on colour codes and mutual trust."},"teaser":{"ar":"نظام توصيل الغداء في مومباي يعمل منذ 130 عامًا دون باركود أو هواتف ذكية، ويعتمد على أكواد ملونة وثقة بين العمال والعملاء.","de":"Seit 130 Jahren liefern Dabbawalas in Mumbai Mittagessen ohne Barcodes oder Smartphones – ein System aus Farbcodes und Vertrauen.","en":"For 130 years, Mumbai's dabbawalas have delivered lunches without barcodes or smartphones, using a hand-written code and trust."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف يعمل النظام","paragraphs":["في مومباي، يجمع عمال الدبّاوالا وجبات الغداء المنزلية من المنازل في الضواحي ويوصلونها إلى موظفي المكاتب في جميع أنحاء المدينة، ثم يعيدون الصناديق الفارغة. يتعاملون مع حوالي 200,000 صندوق يوميًا باستخدام كود مكتوب بخط اليد من الألوان والرموز، دون باركود أو هواتف ذكية في الفرز الأساسي.","بدأت الخدمة في تسعينيات القرن التاسع عشر وتُنظم كتعاونية من فرق صغيرة، كل منها يمتلك حقوق مسارات وعملاء معينين. تختلف الأساليب قليلًا بين الأجيال، حيث يستخدم بعض العمال الشباب الهواتف لتنسيق الاستلام، لكن الفرز الأساسي لا يزال يدويًا."]},{"heading":"الثقة والتحديات","paragraphs":["معدلات الخطأ منخفضة بشكل ملحوظ - وجدت دراسة Six Sigma عام 2001 حوالي خطأ واحد لكل ستة ملايين معاملة، على الرغم من أن هذا الرقم غالبًا ما يُكرر دون تمحيص. نجا النظام من نمو تطبيقات توصيل الطعام بالاعتماد على الثقة والتكلفة المنخفضة جدًا، على الرغم من أن كوفيد-19 قلل الطلب إلى النصف لفترة وجيزة. الخدمة متركزة في مومباي وتأثرت بالعمل عن بعد وتطبيقات الطعام."]}],"de":[{"heading":"Wie das System funktioniert","paragraphs":["In Mumbai holen Dabbawalas hausgemachte Mittagessen aus Vorstadthäusern ab und liefern sie an Büroangestellte in der ganzen Stadt, dann bringen sie die leeren Boxen zurück. Sie bewältigen täglich etwa 200.000 Boxen mit einem handgeschriebenen Farb- und Symbolcode, ohne Barcodes oder Smartphones in der Kernsortierung.","Der Dienst begann in den 1890er Jahren und ist als Genossenschaft kleiner Teams organisiert, die jeweils die Rechte an bestimmten Routen und Kunden besitzen. Die Methoden variieren leicht zwischen den Generationen: Einige jüngere Arbeiter nutzen Telefone zur Koordination der Abholung, aber die Kernsortierung bleibt manuell."]},{"heading":"Vertrauen und Herausforderungen","paragraphs":["Die Fehlerquote ist bemerkenswert niedrig – eine Six-Sigma-Studie von 2001 fand etwa einen Fehler pro sechs Millionen Transaktionen, obwohl diese Zahl oft unkritisch wiederholt wird. Das System überlebte das Wachstum von Liefer-Apps durch Vertrauen und sehr niedrige Kosten, obwohl COVID-19 die Nachfrage kurzzeitig halbierte. Der Dienst konzentriert sich auf Mumbai und wurde durch Heimarbeit und Food-Apps beeinträchtigt."]}],"en":[{"heading":"How the system works","paragraphs":["In Mumbai, dabbawalas collect home-cooked lunches from suburban homes and deliver them to office workers across the city, then return the empty boxes. They handle roughly 200,000 boxes a day with a hand-written colour-and-symbol code, and no barcodes or smartphones in the core sorting.","The service began in the 1890s and is organised as a cooperative of small teams, each owning the rights to certain routes and customers. Methods vary slightly across generations: some younger workers use phones to coordinate pickups, but the core sorting remains manual."]},{"heading":"Trust and challenges","paragraphs":["Error rates are famously low – a Six Sigma study in 2001 found about one mistake per six million transactions, though the claim is often repeated uncritically. The system survived the growth of food delivery apps by relying on trust and very low cost, though COVID-19 briefly halved demand. The service is concentrated in Mumbai and has been disrupted by remote work and food apps."]}]},"context":{"countries":["IN"],"region":"Mumbai","continent":"asia","languages":["mr","hi"],"period":"contemporary"},"tags":["work-and-education","Mumbai"],"sources":[{"organization":"Wikipedia","title":{"ar":"Dabbawala","de":"Dabbawala","en":"Dabbawala"},"url":"https://en.wikipedia.org/wiki/Dabbawala","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Mumbai","de":"Mumbai","en":"Mumbai"},"url":"https://en.wikipedia.org/wiki/Mumbai","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يطبخ شخص في المنزل صندوقي غداء، يلتقطهما عداء في المحطة، يطابق الفرز الكود اللوني مع مبنى، ويجد الموظف غداءه ساخنًا على مكتبه في الساعة 12:30.","de":"Eine Hausköchin packt zwei Tiffin-Boxen, ein Läufer holt sie am Bahnhof ab, Sortierer ordnen den Farbcode einem Gebäude zu, und die Büroangestellte findet um 12:30 Uhr ihr warmes Mittagessen auf dem Schreibtisch.","en":"A home cook packs two tiffin boxes, a runner picks them up at the station, sorters match the colour code to a building, and the office worker finds hot lunch on her desk at 12:30."},"misunderstanding":{"ar":"يُفترض أحيانًا أن النظام يستخدم التكنولوجيا الحديثة، لكن الفرز الأساسي يعتمد على الأكواد اليدوية والثقة.","de":"Manchmal wird angenommen, das System nutze moderne Technologie, aber die Kernsortierung basiert auf handgeschriebenen Codes und Vertrauen.","en":"It is sometimes assumed that the system uses modern technology, but the core sorting relies on hand-written codes and trust."},"comparison":{"ar":"على عكس تطبيقات التوصيل التي تعتمد على الخوارزميات، يعتمد الدبّاوالا على علاقات شخصية طويلة الأمد وتكلفة منخفضة.","de":"Anders als Liefer-Apps, die auf Algorithmen setzen, verlassen sich Dabbawalas auf langfristige persönliche Beziehungen und niedrige Kosten.","en":"Unlike delivery apps that rely on algorithms, dabbawalas depend on long-term personal relationships and low cost."}},{"id":"asa-033","version":2,"slug":"langar-the-free-kitchen-where-everyone-sits-on-the-floor","contentType":"feature","category":"food-and-hospitality","title":{"ar":"لنغار: المطبخ المفتوح حيث يجلس الجميع على الأرض","de":"Langar: die offene Küche, in der alle am Boden sitzen","en":"Langar: the open kitchen where everyone sits on the floor"},"deck":{"ar":"في معابد السيخ، تُقدَّم وجبة مجانية للجميع، ويجلس الناس جنبًا إلى جنب في صفوف على الأرض، لا فرق بين غني وفقير.","de":"In Sikh-Tempeln wird jedem ein kostenloses Essen serviert, und die Menschen sitzen nebeneinander in Reihen auf dem Boden – arm und reich gleichermaßen.","en":"In Sikh temples a free meal is served to anyone, and people sit side by side in rows on the floor, rich and poor alike."},"teaser":{"ar":"مطبخ لا يعرف زبائن ولا أثمانًا، يجلس فيه الوزير والعامل على السجادة ذاتها. كيف يعمل هذا التقليد يوميًا، ولماذا يطبخ فيه المتطوعون بأنفسهم؟","de":"Eine Küche ohne Gäste und ohne Preise, in der der Unternehmer und der Arbeiter auf derselben Matte sitzen. Wie funktioniert diese tägliche Praxis, und warum kochen die Gläubigen selbst?","en":"A kitchen with no customers and no prices, where a business owner and a labourer share the same mat. How does this daily practice work, and why do devotees cook it themselves?"},"readingMinutes":1,"sections":{"ar":[{"heading":"مبدأ المساواة في طبق واحد","paragraphs":["اللنغار هو المطبخ الجماعي في معبد السيخ (الغوردوارا)، حيث تُقدَّم وجبة مجانية لأي شخص بصرف النظر عن دينه أو طبقته أو جنسه أو ثروته. وتُعبّر هذه الممارسة عن فكرتين مركزيتين في العقيدة السيخية: المساواة، و«سيفا» أي الخدمة غير الأنانية. وتُعدّ الوجبة بسيطة عادةً: عدس وأرز وخبز وخضار وخير.","يجلس الآكلون معًا على الأرض في صفوف تُسمّى «بانغات»، فلا طاولات تفصل بينهم ولا أماكن محجوزة. ويطبخ المتطوعون الطعام ويقدّمونه، وهم أنفسهم من يغسلون الأواني وينظّفون القاعة، وتتبدّل الأدوار بينهم. ويُموّل التشغيل من تبرعات المصلّين بالمكوّنات، فلا يدفع أحد شيئًا مقابل ما يأكله."]},{"heading":"مطبخ يعمل بالتبرع والتنظيم","paragraphs":["إدارة لنغار الغوردوارا عملية تطوعية كبرى: مواد غذائية تصل من المصلّين، وأيدي تعمل في المطبخ، وأخرى ترتّب الصفوف وتغسل الصحون. وفي المعبد الذهبي في أمريتسار تُقدَّم عشرات الآلاف من الوجبات يوميًا، ما يجعل التنظيم نفسه جزءًا من الخدمة.","في أحد أيام الأحد في أمريتسار، يغرف متطوع العدس في أوعية فولاذية بينما يجلس رجل أعمال وعامل كتفًا بكتف على الأرض، ويُخدم الجميع قبل أن تبدأ الدفعة التالية. وتختلف التفاصيل من غوردوارا إلى أخرى، إذ تستخدم بعض المواقع الكبرى معدات ضخمة، لكن الفكرة تبقى واحدة: الوجبة ليست صدقة موجّهة إلى الغرباء، بل تعبير عن مبادئ المجتمع نفسه."]},{"heading":"لنغار يسافر مع المهاجرين","paragraphs":["ينتقل اللنغار مع الشتات السيخي، فمجتمعات السيخ في بريطانيا وكندا والولايات المتحدة معروفة بإطعام العاملين في الصفوف الأمامية والمشرّدين. وهكذا يتحوّل المطبخ الديني إلى شبكة تضامن يومية خارج الوطن، وتتباين ممارسته بين الأجيال والأماكن تبعًا لموارد كل مجتمع."]}],"de":[{"heading":"Gleichheit auf einem Teller","paragraphs":["Langar ist die Gemeinschaftsküche im Gurdwara, dem Tempel der Sikhs, in der jedem Menschen unabhängig von Religion, Kaste, Geschlecht oder Wohlstand ein kostenloses Essen serviert wird. Die Praxis drückt zwei zentrale Ideen des Sikh-Glaubens aus: Gleichheit und Seva, den selbstlosen Dienst. Die Mahlzeit ist meist einfach – Dal, Reis, Brot, Gemüse und Kheer.","Die Essenden sitzen gemeinsam auf dem Boden in Reihen, die Pangat genannt werden; keine Tische trennen sie, keine Plätze sind reserviert. Freiwillige kochen und servieren, waschen anschließend das Geschirr und reinigen den Saal, und die Aufgaben wechseln untereinander. Finanziert wird der Betrieb durch Spenden der Gläubigen in Form von Zutaten – niemand zahlt für das, was er isst."]},{"heading":"Ein Küchenbetrieb aus Spenden und Organisation","paragraphs":["Ein Langar zu betreiben ist ein großer ehrenamtlicher Betrieb: Lebensmittel kommen von den Gläubigen, Hände arbeiten in der Küche, andere ordnen die Reihen und spülen. Im Goldenen Tempel von Amritsar werden täglich Zehntausende Mahlzeiten ausgegeben, sodass die Organisation selbst Teil des Dienstes wird.","An einem Sonntag in Amritsar schöpft eine Freiwillige Dal in Stahlschalen, während ein Geschäftsmann und ein Arbeiter Schulter an Schulter auf dem Boden sitzen; alle werden bedient, bevor die nächste Runde beginnt. Die Details unterscheiden sich je nach Gurdwara, und manche große Orte nutzen inzwischen industrielle Geräte, doch die Grundidee bleibt: Das Essen ist keine Wohltätigkeit für Außenstehende, sondern Ausdruck der eigenen Grundsätze."]},{"heading":"Langar reist mit der Diaspora","paragraphs":["Langar wandert mit der sikhischen Diaspora, und Sikh-Gemeinden in Großbritannien, Kanada und den USA sind dafür bekannt, Beschäftigte an vorderster Front und Obdachlose zu verpflegen. So wird die religiöse Küche außerhalb der Heimat zu einem täglichen Solidaritätsnetz, dessen Praxis sich je nach Generation und Ort unterschiedlich gestaltet."]}],"en":[{"heading":"Equality on a single plate","paragraphs":["Langar is the community kitchen in a gurdwara, the Sikh temple, where a free meal is served to anyone regardless of religion, caste, gender or wealth. The practice expresses two core Sikh ideas: equality and seva, selfless service. The meal is usually simple – dal, rice, bread, vegetables and kheer.","Diners sit together on the floor in rows called pangat; no tables separate them and no seats are reserved. Volunteers cook and serve the food, then wash the dishes and clean the hall, and the roles rotate among them. The operation is funded by worshippers donating ingredients, so nobody pays for what they eat."]},{"heading":"A kitchen run on donations and organisation","paragraphs":["Running a gurdwara's langar is a major voluntary operation: ingredients arrive from devotees, some hands work in the kitchen while others arrange the rows and wash up. At the Golden Temple in Amritsar tens of thousands of meals are served daily, which makes the organisation itself part of the service.","On a Sunday in Amritsar a volunteer ladles dal into steel bowls while a businessman and a labourer sit shoulder to shoulder on the floor, and everyone is served before the next batch begins. Details differ from one gurdwara to another, and some larger sites now use industrial equipment, but the principle holds: the meal is not charity aimed at outsiders but an expression of the community's own values."]},{"heading":"Langar travels with the diaspora","paragraphs":["Langar travels with the Sikh diaspora, and Sikh communities in Britain, Canada and the United States are known for feeding frontline workers and the homeless. Outside the homeland the religious kitchen thus becomes a daily network of solidarity, practised differently depending on generation and local resources."]}]},"context":{"countries":["IN"],"region":"Punjab","community":"Sikhs","continent":"asia","languages":["pa","hi"],"period":"contemporary"},"tags":["food-and-hospitality","Punjab","Langar is","The meal"],"sources":[{"organization":"Wikipedia","title":{"ar":"Langar (Sikhism)","de":"Langar (Sikhism)","en":"Langar (Sikhism)"},"url":"https://en.wikipedia.org/wiki/Langar_(Sikhism)","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Gurdwara","de":"Gurdwara","en":"Gurdwara"},"url":"https://en.wikipedia.org/wiki/Gurdwara","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في أحد أيام الأحد في أمريتسار، يغرف متطوع العدس في أوعية فولاذية بينما يجلس رجل أعمال وعامل كتفًا بكتف على الأرض، ويُخدم الجميع قبل أن تبدأ الدفعة التالية.","de":"An einem Sonntag in Amritsar schöpft eine Freiwillige Dal in Stahlschalen, während ein Geschäftsmann und ein Arbeiter Schulter an Schulter auf dem Boden sitzen; alle werden bedient, bevor die nächste Runde beginnt.","en":"On a Sunday in Amritsar a volunteer ladles dal into steel bowls while a businessman and a labourer sit shoulder to shoulder on the floor, and everyone is served before the next batch begins."},"misunderstanding":{"ar":"يُفهم اللنغار أحيانًا على أنه عمل خيري موجّه إلى الفقراء أو الغرباء، لكنه في جوهره مبدأ داخلي يجمع أبناء المجتمع أنفسهم على طبق واحد.","de":"Langar wird oft als Wohltätigkeit für Arme oder Fremde verstanden, doch im Kern ist es ein inneres Prinzip, das die Gemeinschaft selbst an einen Tisch – genauer: auf einen Boden – bringt.","en":"Langar is sometimes read as charity for the poor or for outsiders, but at its core it is an internal principle that brings the community itself together over one meal."},"comparison":{"ar":"بعكس المطابخ الخيرية التي تفصل بين مقدّم الخدمة ومتلقّيها، يجلس هنا الجميع على الأرض ذاتها، ويتبادل المتطوعون والأكلاء الأدوار.","de":"Anders als in Suppenküchen, die zwischen Gebenden und Empfangenden trennen, sitzen hier alle auf demselben Boden, und Freiwillige und Essende tauschen die Rollen.","en":"Unlike soup kitchens that separate those who serve from those who receive, here everyone sits on the same floor, and volunteers and diners swap roles."}},{"id":"asa-034","version":2,"slug":"hinglish-the-code-switch-that-runs-indian-cities","contentType":"note","category":"communication","title":{"ar":"هِنغليش: لغة المدن الهندية المختلطة","de":"Hinglish: der Code-Switch indischer Städte","en":"Hinglish: the code-switch that runs Indian cities"},"deck":{"ar":"كيف ينتقل المتحدثون في الهند الحضرية بين الهندية والإنجليزية داخل الجملة الواحدة، فيصبح هذا الانتقال عادة اجتماعية لا خطأً لغوياً.","de":"Wie Menschen in urbanen Regionen Indiens mitten im Satz zwischen Hindi und Englisch wechseln und daraus eine feste soziale Praxis machen.","en":"How urban Indians move between Hindi and English inside a single sentence, turning the switch into a stable social habit rather than a bilingual failure."},"teaser":{"ar":"في مدن الهند يبدأ المتحدث جمله بالهندية وينهيه بالإنجليزية، ويضع الأفعال الهندية على كلمات إنجليزية، فيفهمه الجميع دون جهد.","de":"In indischen Städten beginnen Sätze auf Hindi und enden auf Englisch, englische Wörter tragen hindi Verbendungen – alle verstehen es ohne Mühe.","en":"In Indian cities sentences start in Hindi and end in English, English words wear Hindi verb endings, and everyone follows without changing register."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف يُنطق الخليط في الحياة اليومية","paragraphs":["في الهند الحضرية ينتقل الناس بين الهندية والإنجليزية داخل الجملة نفسها، فتحمل الكلمات الإنجليزية نهايات أفعال هندية. جذور هذا الخليط تعود إلى الحقبة الاستعمارية، لكنه صار لغة جماهيرية عبر الأفلام والإعلانات والإنترنت، خصوصاً بين الشباب.","يحمل هذا الأسلوب دلالات ثلاثاً في وقت واحد: الطبقة والتعليم والعفوية. فجملة هندية بأسماء تقنية إنجليزية تبدو حديثة، أما الإفراط فيه في مجلس رسمي فقد يبدو فظاً.","يختلف مقدار الخلط بحسب المنطقة والطبقة والجيل ووسيلة التواصل، وكثير من مناطق الهند تستخدم خلائط أخرى أو لا تستخدم الهندية ولا الإنجليزية."]},{"heading":"لماذا يكتب به الكتّاب والمعلنون","paragraphs":["يلجأ الكتّاب والمعلنون إلى هذا الخليط ليبدو كلامهم صادقاً وقريباً من الناس، ويدرسه اللغويون كنموذج على التبديل اللغوي كممارسة اجتماعية مستقرة لا كفشل في ثنائية اللغة.","تسرّبت مفرداته إلى الإنجليزية الهندية، مثل prepone بمعنى تقديم الموعد وtimepass بمعنى تسلية الوقت، وهي كلمات تدل على الاستخدام الجنوب آسيوي.","في اللقاءات اليومية يقول زميل: تم تقديم الاجتماع، تعال في الحادية عشرة، فتختلط الأسماء الإنجليزية بالقواعد الهندية ويفهم الجميع دون تغيير في مستوى الكلام."]}],"de":[{"heading":"Wie der Mix im Alltag klingt","paragraphs":["Im urbanen Indien wechseln Sprecher innerhalb eines Satzes zwischen Hindi und Englisch, englische Wörter bekommen hindi Verbendungen. Die Wurzeln reichen in die Kolonialzeit, doch durch Filme, Werbung und Internet wurde daraus ein Massenregister, besonders unter jungen Städtern.","Der Mix trägt drei Signale zugleich: Klasse, Bildung und Informalität. Ein hindi Satz mit englischen Fachbegriffen wirkt modern, zu viel Hinglish in formellem Rahmen kann derb klingen.","Wie stark gemischt wird, hängt von Region, Klasse, Generation und Medium ab; viele Gegenden Indiens nutzen andere Mischungen oder weder Hindi noch Englisch."]},{"heading":"Warum Autoren und Werber darauf setzen","paragraphs":["Autoren und Werbetreibende greifen zu Hinglish, um authentisch zu klingen; die Linguistik untersucht es als Beispiel für Code-Switching als stabile soziale Praxis, nicht als Scheitern der Zweisprachigkeit.","Sein Wortschatz drang ins indische Englisch ein – prepone für ein früheres Meeting, timepass für müßigen Zeitvertreib; solche Wörter markieren südasiatischen Gebrauch.","Im Büro sagt eine Kollegin, das Meeting sei vorverlegt, man solle um elf kommen: englische Nomen, hindi Grammatik, und alle verstehen, ohne die Gesprächsebene zu wechseln."]}],"en":[{"heading":"How the mix sounds in daily life","paragraphs":["In urban India, speakers switch between Hindi and English mid-clause, and English words take Hindi verb endings. The mix has colonial roots but became a mass register through films, advertising and the internet, especially among young urban speakers.","It signals class, education and informality at once: a Hindi sentence with English technical nouns sounds modern, while heavy Hinglish in a formal setting can sound crude.","How much mixing happens varies by region, class, generation and medium, and large parts of India use other mixtures or neither Hindi nor English."]},{"heading":"Why writers and advertisers use it","paragraphs":["Writers and advertisers use Hinglish to sound authentic, and linguists study it as code-switching that works as a stable social practice rather than a failure of bilingualism.","Its vocabulary has spread into Indian English — prepone for moving a meeting earlier, timepass for idle distraction — words that mark South Asian usage.","At work a colleague says the meeting is preponed, come at eleven, mixing English nouns with Hindi grammar; everyone understands without shifting register."]}]},"context":{"countries":["IN"],"region":"Urban India","continent":"asia","languages":["hi","en"],"period":"contemporary"},"tags":["communication","Urban India"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hinglish","de":"Hinglish","en":"Hinglish"},"url":"https://en.wikipedia.org/wiki/Hinglish","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Code-switching","de":"Code-switching","en":"Code-switching"},"url":"https://en.wikipedia.org/wiki/Code-switching","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يقول زميل في العمل إن الموعد قُدّم إلى الساعة الحادية عشرة، ممزوجاً بين مفردات إنجليزية وقواعد هندية، ويفهمه الحاضرون جميعاً.","de":"Eine Kollegin sagt, das Meeting sei vorverlegt, man solle um elf kommen – englische Nomen in hindi Grammatik, für alle verständlich.","en":"A colleague says meeting prepone kar diya hai, 11 baje aa jao, mixing English nouns with Hindi grammar; everyone understands without changing register."},"misunderstanding":{"ar":"الاعتقاد الشائع أن هذا الخليط دليل على ضعف إتقان اللغتين، والحال أنه ممارسة مستقرة لها قواعدها الاجتماعية.","de":"Viele halten den Mix für mangelhafte Zweisprachigkeit; tatsächlich ist er eine stabile Praxis mit eigenen sozialen Regeln.","en":"Many assume the mix proves weak command of both languages; in fact it is a stable practice with its own social rules."},"comparison":{"ar":"يشبه هذا الخليط ما يحدث في مدن أخرى حين تتداخل لغة محلية مع لغة عالمية، لكنه في الهند أوسع انتشاراً وأكثر حضوراً في الإعلان والسينما.","de":"Ähnlich wie in anderen Städten, wo Lokalsprachen mit Weltsprachen verschmelzen, ist der Mix in Indien nur weiter verbreitet und in Werbung und Film allgegenwärtig.","en":"It resembles other cities where a local language blends with a global one, but in India the mix is far more widespread and constant in film and advertising."},"expression":{"original":"अच्छा","language":"Hinglish / हिन्दी","gloss":{"ar":"حسناً، فهمت — إقرار شائع في المحادثة","de":"okay, verstehe – gängige Gesprächsbestätigung","en":"okay, I see — a common conversational acknowledgment"},"usage":{"ar":"تُقال في أثناء الحديث للدلالة على المتابعة أو الموافقة دون مقاطعته","de":"mitten im Gespräch gesagt, um Zustimmung oder Weiterverfolgen zu signalisieren","en":"said mid-conversation to signal agreement or that one is following"},"transliteration":"achhā"}},{"id":"asa-035","version":2,"slug":"caste-how-heredity-still-shapes-the-everyday","contentType":"note","category":"social-behaviour","title":{"ar":"الطائفة في الهند: إرث يتسلل إلى الحياة اليومية","de":"Kaste in Indien: Herkunft im Alltag","en":"Caste in India: heredity in everyday life"},"deck":{"ar":"نظام اجتماعي يجمع بين تصنيف قديم ومجموعات محلية كثيرة، ويظل حاضراً في الزواج والسكن والعمل رغم حظره قانوناً.","de":"Ein Ordnungsschema und tausende lokale Gruppen prägen weiterhin Heirat, Wohnen und Berufe, obwohl Diskriminierung verboten ist.","en":"A classical schema and thousands of local groups still shape marriage, housing and work, even where discrimination is illegal."},"teaser":{"ar":"كيف يظل الانتماء الوراثي إلى جماعة محددة عاملاً في قرارات الزواج والسكن والعمل في الهند اليوم؟","de":"Warum entscheiden Familienherkunft und lokale Gruppe in Indien noch immer mit, wen man heiratet, wo man wohnt und mit wem man arbeitet?","en":"Why does family origin still influence whom people marry, where they live and which networks they join across urban and rural India?"},"readingMinutes":1,"sections":{"ar":[{"heading":"بين التصنيف القديم والمجموعات المحلية","paragraphs":["يجمع نظام الطائفة في الهند بين «فارنا»، وهو مخطط كلاسيكي من أربعة أقسام، وبين «جاتي»، وهي آلاف المجموعات الوراثية المحلية التي تنظّم الزواج والمهنة والمكانة الطقسية.","وأكثر ما صمد من هذه الأعراف هو الزواج داخل المجموعة نفسها، سواء في المدينة أو الريف. ويختلف شكل الطائفة من إقليم لآخر اختلافاً كبيراً، فتتباين أشكالها في كيرالا والبنجاب وبيهار تبايناً واضحاً.","كما تتفاعل الطائفة مع الطبقة والدين، وتتخذ لدى السيخ والمسيحيين والمسلمين أشكالاً مختلفة، ويغيّر التحضّر والتعليم والقانون من صورتها بمرور الأجيال."]},{"heading":"قانون يحظر، وواقع يعيد إنتاج الفوارق","paragraphs":["ألغى الدستور الهندي «نبذ المنبوذين» وأنشأ مقاعد محجوزة في التعليم والوظائف والمجالس التشريعية للطوائف المصنّفة والقبائل المصنّفة، ثم أُضيفت طوائف أخرى متخلفة لاحقاً.","والتمييز على أساس الطائفة غير قانوني، لكن الدراسات والتقارير الإخبارية توثّق عقبات مستمرة في السكن والزواج وشبكات العمل.","فالعائلات ما زالت تعلن عن عروس من «مجتمعنا»، ومواقع الزواج تتيح مرشّحاً إلزامياً للطائفة، حتى في مدن يتشارك فيها الزملاء طعام الغداء دون سؤال."]}],"de":[{"heading":"Zwischen altem Schema und lokalen Gruppen","paragraphs":["Kaste in Indien verbindet varna, ein klassisches vierstufiges Schema, mit jati, tausenden lokalen Erbgruppen, die Heirat, Beruf und rituellen Status regeln.","Am stärksten erhalten hat sich die Endogamie der jati, also die Heirat innerhalb der eigenen Gruppe, in Stadt und Land. Dabei unterscheidet sich die Kaste regional erheblich: In Kerala, Punjab und Bihar nimmt sie deutlich verschiedene Formen an.","Kaste wirkt mit Klasse und Religion zusammen und verändert sich mit Urbanisierung, Bildung und Recht von Generation zu Generation; bei Sikhs, Christen und Muslimen zeigt sie eigene Gestalten."]},{"heading":"Verbote und fortbestehende Barrieren","paragraphs":["Die Verfassung schaffte die Unberührbarkeit ab und schuf reservierte Plätze in Bildung, Berufen und Parlamenten für Scheduled Castes und Scheduled Tribes, später kamen Other Backward Classes hinzu.","Diskriminierung aufgrund der Kaste ist illegal, doch Studien und Presseberichte dokumentieren weiterhin Hürden bei Wohnungssuche, Heirat und beruflichen Netzwerken.","Familien suchen weiterhin eine Braut „aus unserer Gemeinschaft“, und Heiratsportale bieten einen Pflichtfilter für Kaste an – auch in Städten, in denen Kollegen mittags zusammen essen, ohne danach zu fragen."]}],"en":[{"heading":"Between an old schema and local groups","paragraphs":["Caste in India combines varna, a classical four-part schema, with jati, thousands of local hereditary groups that regulate marriage, occupation and ritual status.","The practice that has most persisted, in cities and villages alike, is jati endogamy: marrying within one's own group. Caste also varies substantially by region, taking clearly different forms in Kerala, Punjab and Bihar.","It interacts with class and religion and shifts across generations with urbanisation, education and law; among Sikhs, Christians and Muslims it takes distinct shapes."]},{"heading":"A legal ban and stubborn barriers","paragraphs":["India's constitution abolished untouchability and created reserved places in education, jobs and legislatures for Scheduled Castes and Scheduled Tribes, with Other Backward Classes added later.","Discrimination based on caste is illegal, but studies and news reports document continued barriers in housing, marriage and workplace networks.","Families still advertise for a bride within our community, and a matrimonial website offers a compulsory caste filter, even in cities where colleagues share lunch without asking."]}]},"context":{"countries":["IN"],"region":"India","continent":"asia","languages":["hi"],"period":"contemporary"},"tags":["social-behaviour","India"],"sources":[{"organization":"Wikipedia","title":{"ar":"Caste system in India","de":"Caste system in India","en":"Caste system in India"},"url":"https://en.wikipedia.org/wiki/Caste_system_in_India","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Jāti","de":"Jāti","en":"Jāti"},"url":"https://en.wikipedia.org/wiki/J%C4%81ti","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تعلن عائلة عن رغبتها في عروس من «مجتمعنا»، ويعرض موقع للزواج مرشّحاً إلزامياً للطائفة، حتى في مدن يتقاسم فيها الزملاء الغداء دون أن يسأل أحد عن نسب الآخر.","de":"Eine Familie sucht eine Braut „aus unserer Gemeinschaft“, und ein Heiratsportal verlangt einen Pflichtfilter für Kaste – auch in Städten, in denen Kollegen zusammen zu Mittag essen, ohne danach zu fragen.","en":"A family advertises for a bride within our community, and a matrimonial website offers a compulsory caste filter, even in cities where colleagues share lunch without asking."},"misunderstanding":{"ar":"يُفهم نظام الطائفة أحياناً كهرم واحد موحّد، لكنه في الحقيقة متغيّر إقليمياً ومتفاعل مع الطبقة والدين، والتعميم من إقليم واحد قد يضلّل.","de":"Kaste wird oft als eine einzige, einheitliche Hierarchie verstanden; tatsächlich ist sie regional verschieden und mit Klasse und Religion verwoben, Verallgemeinerungen aus einer Region führen in die Irre.","en":"Caste is often read as one uniform hierarchy; in fact it varies regionally and overlaps with class and religion, so generalisations from a single region can mislead."},"comparison":{"ar":"يشبه الأمر عائلات تعرف بعضها في حيّ واحد: القرب اليومي لا يلغي الحدود الخفية، لكن الحدود نفسها تختلف من حيّ إلى آخر.","de":"Es ähnelt Nachbarschaften, in denen man sich kennt: Alltägliche Nähe hebt unsichtbare Grenzen nicht auf, doch diese Grenzen verlaufen von Ort zu Ort anders.","en":"It resembles neighbourhoods where everyone knows everyone: daily closeness does not erase quiet boundaries, yet those boundaries run differently from place to place."}},{"id":"asa-036","version":2,"slug":"the-hindu-joint-family-a-household-with-many-centres-of-authority","contentType":"note","category":"family-and-friendship","title":{"ar":"العائلة الهندوسية المشتركة: بيت متعدد المراكز","de":"Die hinduistische Großfamilie: ein Haushalt mit vielen Machtzentren","en":"The Hindu joint family: a household with many centres of authority"},"deck":{"ar":"عائلة تمتد عبر الأجيال، تتقاسم المال والطقوس، وتوزع السلطة بين الأكبر سنًا، مع تحولات حديثة نحو الاستقلال.","de":"Eine mehrgenerationale Familie, die Geld und Rituale teilt und Autorität unter den Ältesten verteilt – im Wandel durch Urbanisierung und Berufstätigkeit von Frauen.","en":"A multi-generation family sharing money and rituals, with authority distributed among elders – now shifting with urban migration and women's employment."},"teaser":{"ar":"في بيت واحد، ثلاثة أجيال تتفاوض على السلطة والمساحة والرعاية، حيث تلتقي التقاليد مع متطلبات الحياة الحديثة.","de":"Unter einem Dach verhandeln drei Generationen Macht, Raum und Fürsorge, während Tradition auf moderne Anforderungen trifft.","en":"Under one roof, three generations negotiate power, space and care, as tradition meets the demands of modern life."},"readingMinutes":1,"sections":{"ar":[{"heading":"بنية السلطة والمسؤولية","paragraphs":["العائلة الهندوسية المشتركة هي أسرة متعددة الأجيال، تقليدياً أبوية من حيث النسب والسكن، حيث يجلب الأبناء زوجاتهم إلى بيت الوالدين وتُشارك الملكية. عادةً ما تكون السلطة بيد الذكر الأكبر، بينما تدير المرأة الكبرى المطبخ والعمل المنزلي؛ وتنتقل البنات إلى عائلة الزوج.","هذا البيت ليس مجرد مسكن، بل هو وحدة طقسية واقتصادية: يحافظ على مزار العائلة، ويمول الأعراس، ويرعى كبار السن. هذا التداخل بين الاقتصاد والطقوس يجعل من الصعب فصل الحياة اليومية عن الالتزامات العائلية.","تختلف الممارسة حسب المنطقة والطبقة والانتماء الديني، كما تتباين بين الأجيال: فبعض الشباب يفضلون الاستقلال، بينما يتمسك كبار السن بالترتيبات المشتركة."]},{"heading":"بين الدعم والقيود","paragraphs":["يمكن أن تكون المشتركة مورداً: رعاية مشتركة للأطفال، ومدخرات مجمعة، ودعم متبادل في الأزمات. لكنها قد تكون قيداً أيضاً، مع خصوصية محدودة وتوزيع غير متكافئ للعمل المنزلي، خاصة على النساء.","مع الهجرة إلى المدن، وصغر حجم الأسر، وانخراط النساء في العمل، زادت الأسر النووية. ومع ذلك، تستمر العائلات المشتركة في مجتمعات الأعمال وفي ترتيبات الرعاية، حيث تظل شبكة الأمان العائلية ذات قيمة.","في النهاية، العائلة المشتركة نموذج مثالي وليست ترتيباً عالمياً؛ فالواقع يختلف بين من يعيشون تحت سقف واحد ومن تفرقت بهم المدن."]}],"de":[{"heading":"Struktur von Autorität und Verantwortung","paragraphs":["Die hinduistische Großfamilie ist ein mehrgenerationaler Haushalt, traditionell patrilinear und patrilokal: Söhne bringen ihre Frauen ins Elternhaus, und Eigentum wird geteilt. Die Autorität liegt meist beim ältesten Mann, während die älteste Frau die Küche und die Hausarbeit organisiert; Töchter ziehen zur Familie des Ehemanns.","Der Haushalt ist auch eine rituelle und wirtschaftliche Einheit: Er unterhält den Hausschrein, finanziert Hochzeiten und kümmert sich um ältere Mitglieder. Diese Verflechtung von Wirtschaft und Ritual macht es schwer, Alltag und Familienpflichten zu trennen.","Die Praxis variiert je nach Region, Kaste, Religion und Klasse sowie zwischen den Generationen: Manche Jüngere bevorzugen Unabhängigkeit, während Ältere an gemeinsamen Arrangements festhalten."]},{"heading":"Zwischen Ressource und Einschränkung","paragraphs":["Gemeinsamkeit kann eine Ressource sein: geteilte Kinderbetreuung, gemeinsame Ersparnisse und gegenseitige Unterstützung in Krisen. Sie kann aber auch eine Einschränkung bedeuten, mit begrenzter Privatsphäre und ungleicher Hausarbeit, besonders für Frauen.","Durch Migration in die Städte, kleinere Familien und die Erwerbstätigkeit von Frauen haben Kernfamilien zugenommen. Dennoch bestehen Großfamilien in Geschäftsgemeinschaften und in Pflegearrangements fort, wo das familiäre Netz als Sicherheit gilt.","Letztlich ist die Großfamilie ein Idealtypus, keine universelle Lebensform; die Realität unterscheidet sich zwischen denen, die unter einem Dach leben, und denen, die über Städte verteilt sind."]}],"en":[{"heading":"Structure of authority and responsibility","paragraphs":["A Hindu joint family is a multi-generation household, traditionally patrilineal and patrilocal, in which sons bring wives into the parental home and property is shared. Authority usually sits with the eldest male, while the eldest woman manages the kitchen and household labour; daughters move to their husband's family.","The household is also a ritual and economic unit: it maintains the family shrine, funds weddings and cares for elderly members. This intertwining of economy and ritual makes it hard to separate daily life from family obligations.","Practice varies by region, caste, religion and class, and across generations: some younger members prefer independence, while elders hold on to joint arrangements."]},{"heading":"Between resource and constraint","paragraphs":["Jointness can be a resource – shared childcare, pooled savings and mutual support in crises. But it can also be a constraint, with limited privacy and unequal domestic labour, especially for women.","Urban migration, smaller families and women's employment have increased nuclear households. Yet joint families persist in business communities and in care arrangements, where the family network remains a safety net.","Ultimately, the joint family is an ideal type, not a universal living arrangement; reality differs between those under one roof and those split across cities."]}]},"context":{"countries":["IN"],"region":"India","continent":"asia","languages":["hi"],"period":"contemporary"},"tags":["family-and-friendship","India"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hindu joint family","de":"Hindu joint family","en":"Hindu joint family"},"url":"https://en.wikipedia.org/wiki/Hindu_joint_family","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of India","de":"Culture of India","en":"Culture of India"},"url":"https://en.wikipedia.org/wiki/Culture_of_India","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في منزل عائلي، تتقاسم ثلاثة أجيال جدول المطبخ؛ تشرف الجدة على الطبخ، ويدير أحد الأبناء متجر العائلة، وتتفاوض زوجة الابن حول موعد زيارة والديها.","de":"In einem Familienhaus teilen drei Generationen einen Küchenplan; die Großmutter beaufsichtigt das Kochen, ein Sohn führt den Laden der Familie, und eine Schwiegertochter verhandelt, wann sie ihre eigenen Eltern besucht.","en":"In a family home three generations share a kitchen schedule; the grandmother supervises cooking, one son manages the family shop, and a daughter-in-law negotiates when to visit her own parents."},"misunderstanding":{"ar":"يُفترض أحياناً أن العائلة المشتركة تعني انسجاماً تاماً وسلطة مطلقة، لكنها في الواقع مساحة تفاوض يومي حول الأدوار والمساحات.","de":"Manchmal wird angenommen, die Großfamilie bedeute völlige Harmonie und absolute Autorität, doch tatsächlich ist sie ein Raum täglicher Aushandlung von Rollen und Räumen.","en":"It is sometimes assumed that the joint family means perfect harmony and absolute authority, but in practice it is a space of daily negotiation over roles and room."},"comparison":{"ar":"على عكس الأسر النووية في الغرب، حيث تُفصل السلطة عادةً بين الزوجين، تعتمد العائلة المشتركة على تسلسل هرمي متعدد المراكز.","de":"Anders als Kernfamilien im Westen, wo Autorität oft zwischen Partnern aufgeteilt wird, beruht die Großfamilie auf einer vielzentrierten Hierarchie.","en":"Unlike nuclear families in the West, where authority is often shared between partners, the joint family relies on a multi-centred hierarchy."}},{"id":"asa-037","version":2,"slug":"garba-navaratri-s-all-night-circle-dance","contentType":"scene","category":"music-and-dance","title":{"ar":"غاربا: رقصة الدائرة حتى الفجر","de":"Garba: der Nachttanz im Kreis","en":"Garba: dancing in circles till dawn"},"deck":{"ar":"في ليالي نافاراتري التسع يتحول ساحات الأحياء في غوجارات إلى دوائر واسعة من الراقصين الذين يحيون الإلهة بالتصفيق والدوران حتى الصباح.","de":"In den neun Nächten von Navaratri verwandeln sich Nachbarschaftsplätze in Gujarat in weite Kreise von Tänzerinnen und Tänzern, die die Göttin mit Klatschen und Drehungen bis zum Morgengrauen feiern.","en":"During the nine nights of Navaratri, neighbourhood grounds in Gujarat fill with wide circles of dancers honouring the goddess with claps and turns until morning."},"teaser":{"ar":"رقصة شعبية تجمع الجيران في حلقة حول مصباح طيني، لا جمهور لها ولا خشبة مسرح، بل عبادة ومشاركة تمتد طوال الليل.","de":"Ein Volkstanz, der Nachbarn im Kreis um eine Tonlampe versammelt – ohne Bühne und Publikum, als Andacht und Gemeinschaft, die die ganze Nacht dauert.","en":"A folk dance that gathers neighbours in a ring around an earthen lamp — no stage, no audience, just devotion and community lasting all night."},"readingMinutes":1,"sections":{"ar":[{"heading":"حلقة حول المصباح","paragraphs":["تُؤدى رقصة غاربا في دائرة حول مصباح طيني مزين أو صورة للإلهة، وخاصة في الليالي التسع لنافاراتري. وتأخذ الكلمة اسمها من المصباح نفسه الموضوع في المركز، فتربط الحركة بين المكان والعبادة.","تتناوب الخطوات بين التصفيق والدوران، وتؤديها تقليدياً النساء والفتيات، بينما ينضم الرجال إلى رقصة دانديا راس القريبة. وليست الرقصة عرضاً لجمهور بل تعبيراً عن التعبد والانتماء الجماعي."]},{"heading":"من الساحة إلى القاعات","paragraphs":["في غوجارات تستقطب ساحات غاربا في الأحياء آلاف الراقصين، بينما تستأجر مجموعات الجاليات في مدن المهجر القاعات وتحافظ على صيغة السهر حتى الفجر. وتختلف الأساليب والأغاني بحسب المنطقة والطائفة، كما غيّرت الفعاليات التجارية الكبيرة أجواء الرقصة، وصيغة السهر ليست شاملة إذ تحتفظ بعض العائلات بطقوس منزلية أهدأ.","أدرجت اليونسكو غاربا غوجارات في قائمة التراث غير المادي عام 2023، noting طابعها الشامل القائم على المشاركة."]}],"de":[{"heading":"Ein Kreis um die Lampe","paragraphs":["Garba wird im Kreis um eine geschmückte Tonlampe oder ein Bild der Göttin getanzt, besonders in den neun Nächten von Navaratri. Das Wort bezeichnet die Lampe in der Mitte, und so verbindet der Tanz Ort und Andacht miteinander.","Die Schritte wechseln zwischen Klatschen und Drehungen; traditionell tanzen Frauen und Mädchen, während Männer in der Nähe beim Dandiya Raas mitmachen. Der Tanz ist keine Aufführung für ein Publikum, sondern drückt Hingabe und Zusammengehörigkeit aus."]},{"heading":"Vom Hof zur gemieteten Halle","paragraphs":["In Gujarat ziehen die Garba-Plätze der Nachbarschaften Tausende Tänzer an; in Städten im Ausland mieten Gemeinschaftsgruppen Säle und behalten das Format bis zum Morgengrauen bei. Stile und Lieder unterscheiden sich je nach Region und Gemeinschaft, große kommerzielle Veranstaltungen haben die Atmosphäre verändert, und das nächtelange Tanzen ist nicht überall üblich – manche Familien pflegen stillere häusliche Feiern.","2023 nahm die UNESCO Garba aus Gujarat in die Liste des immateriellen Kulturerbes auf und betonte den inklusiven, partizipativen Charakter."]}],"en":[{"heading":"A ring around the lamp","paragraphs":["Garba is performed in a circle around a decorated earthen lamp or an image of the goddess, especially during the nine nights of Navaratri. The word garba names the lamp at the centre, so the dance ties the place itself to devotion.","Steps alternate claps and turns; traditionally women and girls dance while men join dandiya raas nearby. It is not a performance for an audience but an enactment of devotion and community."]},{"heading":"From courtyards to hired halls","paragraphs":["In Gujarat, neighbourhood garba grounds draw thousands of dancers; in cities abroad, community groups hire halls and keep the all-night format. Styles and songs vary by region and community, large commercial events have changed the atmosphere, and the all-night format is not universal, as some families keep quieter domestic observances.","UNESCO added Garba of Gujarat to its intangible heritage list in 2023, noting its inclusive, participatory character."]}]},"context":{"countries":["IN"],"region":"Gujarat","continent":"asia","languages":["gu","hi"],"period":"contemporary"},"tags":["music-and-dance","Gujarat"],"sources":[{"organization":"Wikipedia","title":{"ar":"Garba (dance)","de":"Garba (dance)","en":"Garba (dance)"},"url":"https://en.wikipedia.org/wiki/Garba_(dance)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Navaratri","de":"Navaratri","en":"Navaratri"},"url":"https://en.wikipedia.org/wiki/Navaratri","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الليلة الثالثة من نافاراتري يمتلئ فناء بالنساء ذوات التنانير المرصعة بالمرايا؛ تتسع الدائرة مع انضمام الجيران وتستمر الأغاني حتى الفجر.","de":"In der dritten Nacht von Navaratri füllt sich ein Hof mit Frauen in spiegelbestickten Röcken; der Kreis wächst, als Nachbarn dazukommen, und die Lieder laufen bis zum Morgengrauen.","en":"On the third night of Navaratri a courtyard fills with women in mirror-work skirts; the circle expands as neighbours join, and the songs run until dawn."},"misunderstanding":{"ar":"يظن بعض الزوار أنها عرض مسرحي يحتاج جمهوراً، لكنها في جوهرها مشاركة جماعية لا فصل فيها بين مؤدٍّ ومشاهد.","de":"Manche Besucher halten Garba für eine Bühnenshow mit Publikum, doch im Kern ist sie gemeinsames Mitmachen ohne Trennung von Darstellenden und Zuschauenden.","en":"Some visitors expect a staged show with spectators, but garba is shared participation, with no line between performer and onlooker."},"comparison":{"ar":"تشبه في روحها الاحتفالات الجماعية التي تملأ الساحات في مناطق أخرى، لكن ما يميزها هو الدائرة حول المصباح والتصفيق المنتظم.","de":"Im Geist ähnelt sie gemeinschaftlichen Festen auf Plätzen anderer Regionen, doch der Kreis um die Lampe und das gleichmäßige Klatschen machen sie besonders.","en":"In spirit it resembles communal street celebrations elsewhere, yet the ring around the lamp and the steady clapping give it a form of its own."}},{"id":"asa-038","version":2,"slug":"upi-paying-the-vegetable-seller-with-a-qr-code","contentType":"feature","category":"cultural-change","title":{"ar":"الدفع بالهاتف عند بائع الخضار","de":"Mit dem Handy beim Gemüsehändler zahlen","en":"Paying the vegetable seller with a QR code"},"deck":{"ar":"كيف غيّر تطبيق الدفع الفوري حياة الناس في الهند، من تقسيم الفاتورة إلى دفع أجرة العاملات المنزليات.","de":"Wie die indische Sofortzahlung UPI den Alltag verändert – vom Rechnungsteilen bis zur Bezahlung von Haushaltshilfen.","en":"How India's instant payment system UPI has changed everyday life, from splitting bills to paying domestic workers."},"teaser":{"ar":"في الهند، أصبح مسح رمز الاستجابة السريعة لدفع ثمن الخضار أمراً يومياً، لكن ليس للجميع.","de":"In Indien ist das Scannen eines QR-Codes beim Gemüsekauf alltäglich geworden, doch nicht für alle.","en":"In India, scanning a QR code to buy vegetables has become routine, but the digital payment revolution still leaves some behind."},"readingMinutes":1,"sections":{"ar":[{"heading":"ثورة في التعاملات اليومية","paragraphs":["في الهند، لم يعد دفع ثمن الخضار أو أجرة التوكتوك يتطلب نقوداً ورقية. فمنذ إطلاق نظام الدفع الفوري (UPI) في 2016، أصبح بمقدور ملايين الأشخاص تحويل الأموال فوراً بين الحسابات البنكية عبر تطبيق على الهاتف.该系统 يعمل عبر عنوان افتراضي ورمز QR ملصق على عربة أو كشك، مما يسمح للباعة الجائلين وسائقي التوكتوك وحتى المعابد بقبول المدفوعات الرقمية.","ما سهّل انتشاره هو أنه يعمل بين مختلف البنوك والتطبيقات، على عكس المحافظ الإلكترونية التي كانت مقتصرة على شركة واحدة. هذا التكامل جعله أسرع انتشاراً وأكثر فائدة للناس العاديين."]},{"heading":"أمثلة من الحياة اليومية","paragraphs":["عند بسطة على جانب الطريق، يمسح الزبون رمز QR مغلفاً، يدفع عشرين روبية، ويظهر علامة خضراء، بينما يعلن مكبر صوت البائع المبلغ بالهندية. هذه اللحظة البسيطة تلخص كيف أصبح الدفع الرقمي جزءاً من النسيج اليومي.","يستخدم الناس UPI لتقسيم فاتورة المطعم بين الأصدقاء، أو لدفع أجرة العاملة المنزلية، أو لإرسال المال إلى الأهل في القرية. لكن هناك من لا يزال خارج هذه الدائرة: مستخدمو الهواتف الميزة (feature phones) ومن يعانون ضعف الاتصال بالإنترنت."]},{"heading":"تفاوت في الاعتماد والثقة","paragraphs":["الدفع الرقمي واسع الانتشار لكنه ليس شاملاً. هناك مخاوف حقيقية بشأن الاحتيال والخصوصية وضعف الاتصال في المناطق الريفية. ويختلف الاعتماد على النظام حسب الولاية والعمر والدخل.","كما أن النظام مدعوم من الدولة، وتدرسه دول أخرى كبديل لشبكات البطاقات. ومع ذلك، يبقى التحدي في ضمان ألا يُستبعد أحد من هذه الثورة الرقمية."]}],"de":[{"heading":"Eine Revolution im Alltag","paragraphs":["In Indien erfordert das Bezahlen von Gemüse oder einer Auto-Rikscha längst kein Bargeld mehr. Seit der Einführung des Unified Payments Interface (UPI) im Jahr 2016 können Millionen Menschen Geld sofort zwischen Bankkonten über eine Handy-App überweisen. Das System funktioniert über eine virtuelle Adresse und einen QR-Code, der an einem Stand oder Kiosk klebt, sodass Straßenhändler, Auto-Rikscha-Fahrer und sogar Tempel digitale Zahlungen akzeptieren.","Was die Verbreitung beschleunigte, ist die Interoperabilität zwischen Banken und Apps – anders als bei Wallet-Angeboten einzelner Firmen. Diese Offenheit machte UPI schneller und nützlicher für normale Leute."]},{"heading":"Beispiele aus dem Alltag","paragraphs":["An einem Straßenstand scannt ein Kunde einen laminierten QR-Code, zahlt zwanzig Rupien und zeigt das grüne Häkchen, während ein Lautsprecher beim Verkäufer den Betrag auf Hindi ansagt. Dieser Moment fasst zusammen, wie digitales Bezahlen selbstverständlich geworden ist.","Die Menschen nutzen UPI, um Restaurantrechnungen zu teilen, Haushaltshilfen zu bezahlen oder Geld an die Familie im Dorf zu schicken. Doch nicht alle sind dabei: Nutzer von Feature-Phones und Menschen mit schlechter Internetverbindung bleiben ausgeschlossen."]},{"heading":"Ungleichheit bei Nutzung und Vertrauen","paragraphs":["Digitales Bezahlen ist weit verbreitet, aber nicht universell. Betrug, Datenschutz und ländliche Konnektivität sind reale Sorgen. Die Nutzung variiert je nach Bundesstaat, Alter und Einkommen.","Das staatlich unterstützte System wird von anderen Ländern als Alternative zu Kartennetzwerken studiert. Die Herausforderung bleibt, niemanden von dieser digitalen Entwicklung auszuschließen."]}],"en":[{"heading":"A revolution in daily transactions","paragraphs":["In India, paying for vegetables or an auto-rickshaw ride no longer requires cash. Since the Unified Payments Interface (UPI) launched in 2016, millions of people can transfer money instantly between bank accounts via a phone app. The system works through a virtual address and a QR code stuck to a stall or kiosk, so street vendors, auto-rickshaw drivers and even temples accept digital payments.","What accelerated its spread was interoperability across banks and apps, unlike single-company wallets. This openness made UPI faster and more useful for ordinary people."]},{"heading":"Examples from everyday life","paragraphs":["At a roadside stall a customer scans a laminated QR code, pays twenty rupees and shows the green tick, while the seller's voice speaker announces the amount in Hindi. This simple moment captures how digital payment has become part of the daily fabric.","People use UPI to split restaurant bills, pay domestic workers or send money home to the village. But not everyone is included: feature-phone users and those with poor connectivity remain excluded."]},{"heading":"Uneven adoption and trust","paragraphs":["Digital payment is widespread but not universal. Fraud, privacy and rural connectivity are real concerns. Adoption varies by state, age and income.","The state-backed infrastructure is studied by other countries as an alternative to card networks. Yet the challenge remains ensuring no one is left out of this digital shift."]}]},"context":{"countries":["IN"],"region":"India","continent":"asia","languages":["hi","en"],"period":"contemporary"},"tags":["cultural-change","India"],"sources":[{"organization":"Wikipedia","title":{"ar":"Unified Payments Interface","de":"Unified Payments Interface","en":"Unified Payments Interface"},"url":"https://en.wikipedia.org/wiki/Unified_Payments_Interface","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Digital India","de":"Digital India","en":"Digital India"},"url":"https://en.wikipedia.org/wiki/Digital_India","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عند بسطة على جانب الطريق، يمسح الزبون رمز QR مغلفاً، يدفع عشرين روبية، ويظهر علامة خضراء، بينما يعلن مكبر صوت البائع المبلغ بالهندية.","de":"An einem Straßenstand scannt ein Kunde einen laminierten QR-Code, zahlt zwanzig Rupien und zeigt das grüne Häkchen, während ein Lautsprecher beim Verkäufer den Betrag auf Hindi ansagt.","en":"At a roadside stall a customer scans a laminated QR code, pays twenty rupees and shows the green tick, while the seller's voice speaker announces the amount in Hindi."},"misunderstanding":{"ar":"يعتقد البعض أن الدفع الرقمي أصبح عالمياً في الهند، لكن الواقع أن مستخدمي الهواتف الميزة وسكان المناطق ضعيفة الاتصال لا يزالون خارج النظام.","de":"Manche glauben, digitales Bezahlen sei in Indien allgegenwärtig, doch Nutzer von Feature-Phones und Menschen mit schlechter Verbindung bleiben außen vor.","en":"Some assume digital payment is universal in India, but feature-phone users and people with poor connectivity remain outside the system."},"comparison":{"ar":"على عكس المحافظ الإلكترونية التي كانت حكراً على شركة واحدة، فإن UPI يعمل بين البنوك والتطبيقات المختلفة، مما ساعده على الانتشار أسرع.","de":"Anders als Wallet-Apps einzelner Firmen funktioniert UPI banken- und app-übergreifend, was seine schnelle Verbreitung erklärte.","en":"Unlike single-company wallets, UPI works across banks and apps, which helped it spread faster."}},{"id":"asa-039","version":2,"slug":"the-monsoon-a-season-that-sets-the-household-calendar","contentType":"feature","category":"nature-and-seasons","title":{"ar":"الموسم الذي يضبط إيقاع البيوت","de":"Der Monsun ordnet den Alltag der Familien","en":"The monsoon that sets the household calendar"},"deck":{"ar":"في جنوب آسيا لا يُقاس الصيف بالحرارة وحدها، بل بوصول المطر الأول الذي يعيد ترتيب العمل والزرع والأعراس والأسعار.","de":"In Südasien beginnt der Sommer nicht mit der Hitze allein, sondern mit dem ersten Regen, der Arbeit, Aussaat, Hochzeiten und Preise neu ordnet.","en":"In South Asia summer is not measured by heat alone but by the first rain, which rearranges work, sowing, weddings and prices."},"teaser":{"ar":"من يونيو إلى سبتمبر ينتظره الفلاحون والتجار والعرائس، ويحمل معه الفرح والقلق معًا في الهند وباكستان وبنغلاديش ونيبال.","de":"Von Juni bis September warten Bauern, Händler und Brautpaare auf ihn, und er bringt Freude und Sorge zugleich in Indien, Pakistan, Bangladesch und Nepal.","en":"From June to September farmers, traders and brides wait for it, and it carries both joy and worry across India, Pakistan, Bangladesh and Nepal."},"readingMinutes":1,"sections":{"ar":[{"heading":"وصول المطر الأول","paragraphs":["في جنوب آسيا يصل الموسم المطري في يونيو وينسحب بحلول سبتمبر، حاملًا معظم أمطار السنة. هذا الإيقاع لا يخص الطقس وحده، بل يعيد ترتيب حياة الناس: الزرع والري وأسعار السوق وحتى مواعيد الأعراس التي تنتظر الأشهر الجافة بعده.","تنتظر الأسر الأمطار الأولى لتزرع، وتراقب السماء كما يراقب التاجر أسعاره. وعندما تهطل الأمطار الغزيرة على السطح، يخرج الأطفال ليتعرّضوا لها، وتبدأ الجدة في تخطيط موسم الزرع، في مشهد يتكرر في بيوت كثيرة."]},{"heading":"الخبر والقلق","paragraphs":["تنشر دائرة الأرصاد الجوية الهندية توقعاتها وخريطة تقدم يومية، فيتابعها الفلاحون كما يتابع الناس أخبارًا تخصّ قوتهم اليومي. تأخر الأمطار أو فشلها قد يرفع أسعار الغذاء ويزيد الضيق في الريف، بينما تسبّب هطولاتها العنيفة فيضانات في مدن مثل مومباي.","لذلك يحمل الموسم وجهين: هو سبب الفرح والاحتفال في الشعر والموسيقى والمهرجانات، وفي الوقت نفسه مصدر قلق لمن يعتمد على الأرض. ورائحة المطر الأول صورة ثقافية شائعة يعرفها الكبار والصغار."]},{"heading":"موسم يتغير","paragraphs":["يقول الباحثون إن تغيّر المناخ يجعل الموسم أكثر تقلبًا، بفترات جفاف أطول وأمطار أشد. هذا التغير لا يغيّر الحقول فقط، بل يغيّر خطط الأسر ومواعيد الأعراس والاحتفالات المرتبطة بالمطر.","تختلف شدة الأمطار وتوقيتها كثيرًا بين مناطق الهند وجنوب آسيا، فالموسم ليس فصلًا واحدًا متشابهًا، ولكل منطقة معناها الخاص به. كما تختلف نظرته بين الأجيال: من كبار يذكرون مواسم منتظمة، وشباب يتابعون التوقعات على هواتفهم."]}],"de":[{"heading":"Der erste Regen","paragraphs":["In Südasien kommt der Monsun im Juni und zieht bis September wieder ab; er bringt den größten Teil des Jahresregens. Dieser Rhythmus betrifft nicht nur das Wetter, sondern ordnet das Leben der Menschen: Aussaat, Bewässerung, Marktpreise und sogar die Termine der Hochzeiten, die auf die trockenen Monate danach warten.","Familien warten auf den ersten Regen, um zu säen, und beobachten den Himmel wie Händler ihre Preise. Wenn der erste schwere Regen auf das Dach trommelt, laufen Kinder hinaus und lassen sich nass werden, und die Großmutter beginnt die Aussaat zu planen – ein Bild, das sich in vielen Häusern wiederholt."]},{"heading":"Prognose und Sorge","paragraphs":["Der India Meteorological Department veröffentlicht Vorhersagen und eine tägliche Karte des Fortschritts; Bauern verfolgen sie so aufmerksam wie andere Menschen Nachrichten über ihren Alltag. Ein verspäteter oder ausbleibender Monsun kann Lebensmittelpreise treiben und die Not auf dem Land erhöhen, während heftige Regenfälle Städte wie Mumbai überfluten.","So hat die Saison zwei Gesichter: Sie ist Grund für Freude und Feiern in Poesie, Musik und Festen und zugleich Anlass zur Sorge für alle, die von ihrem Land leben. Der Geruch des ersten Regens ist ein verbreitetes kulturelles Bild, das Jung und Alt kennen."]},{"heading":"Eine Saison im Wandel","paragraphs":["Der Klimawandel, so Forschende, macht den Monsun unbeständiger, mit längeren Trockenphasen und heftigeren Regengüssen. Das verändert nicht nur die Felder, sondern auch Familienpläne, Hochzeitstermine und regenbezogene Feste.","Zeitpunkt und Stärke des Regens unterscheiden sich stark zwischen den Regionen Indiens und Südasiens; der Monsun ist keine einheitliche Jahreszeit, und jede Region verbindet eigene Bedeutungen mit ihm. Auch zwischen den Generationen unterscheidet sich der Blick: Ältere erinnern sich an regelmäßige Saisons, Jüngere verfolgen Vorhersagen auf dem Handy."]}],"en":[{"heading":"The arrival of the first rain","paragraphs":["The South Asian monsoon arrives in June and withdraws by September, delivering most of the region's annual rainfall. This rhythm shapes more than the weather: it rearranges agriculture, irrigation, market prices and even wedding dates, which often wait for the dry months after.","Families wait for the first rains to sow, watching the sky the way a trader watches prices. When the first heavy rain drums on the roof, children run outside to get wet and the grandmother starts planning the sowing, a scene repeated in many homes."]},{"heading":"Forecast and worry","paragraphs":["The India Meteorological Department publishes forecasts and a daily progression map; farmers follow these as closely as others follow the news. Monsoon failure or delay can raise food prices and rural distress, while intense spells cause floods in cities such as Mumbai.","So the season carries two faces: it is celebrated in poetry, music and festivals, and it is also a source of anxiety for those who live from the land. The smell of the first rain is a common cultural image known to old and young."]},{"heading":"A season in change","paragraphs":["Climate change is making the monsoon more variable, with longer dry spells and heavier downpours, researchers say. This changes not only fields but also family plans, wedding dates and rain-linked festivals.","Rainfall timing and intensity vary greatly across India and South Asia; the monsoon is not a single uniform season, and regional cultures attach different meanings to it. Views also differ between generations: elders recall steady seasons, while younger people track forecasts on their phones."]}]},"context":{"countries":["IN","PK","BD","NP"],"region":"South Asia","continent":"asia","languages":["hi"],"period":"contemporary"},"tags":["nature-and-seasons","South Asia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Monsoon","de":"Monsoon","en":"Monsoon"},"url":"https://en.wikipedia.org/wiki/Monsoon","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Monsoon of South Asia","de":"Monsoon of South Asia","en":"Monsoon of South Asia"},"url":"https://en.wikipedia.org/wiki/Monsoon_of_South_Asia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في أواخر يونيو تراقب أسرة السماء، فيقرع المطر الغزير السطح أول مرة، ويركض الأطفال خارجه ليبتلّوا، وتبدأ الجدة في تخطيط الزرع.","de":"Ende Juni beobachtet eine Familie den Himmel, der erste schwere Regen trommelt auf das Dach, Kinder laufen hinaus und werden nass, und die Großmutter beginnt die Aussaat zu planen.","en":"In late June a family watches the sky, the first heavy rain drums on the roof, children run outside to get wet, and the grandmother starts planning the sowing."},"misunderstanding":{"ar":"يظن بعض الناس أن الموسم المطري فترة واحدة متشابهة في كل مكان، لكن توقيته وشدته يختلفان كثيرًا بين المناطق، ولكل ثقافة محلية معناها الخاص به.","de":"Manche halten den Monsun für eine überall gleiche Regenzeit, doch Zeitpunkt und Stärke unterscheiden sich stark zwischen den Regionen, und jede lokale Kultur verbindet eigene Bedeutungen mit ihm.","en":"Some assume the monsoon is one identical rainy period everywhere, but its timing and intensity vary greatly between regions, and each local culture attaches its own meanings to it."},"comparison":{"ar":"حيث ينتظر الناس هناك المطر الأول لبدء الزرع وترتيب الأعراس، ينتظر آخرون في مناطق أخرى تغيّر الفصول لأسباب مشابهة، فالطقس عند الجميع تقويم حياة لا مجرد خبر.","de":"Wo dort Menschen auf den ersten Regen warten, um zu säen und Hochzeiten zu planen, warten anderswo Menschen auf den Wechsel der Jahreszeiten aus ähnlichen Gründen – Wetter ist überall ein Kalender des Lebens, nicht nur eine Nachricht.","en":"Where people there wait for the first rain to sow and plan weddings, people elsewhere wait for seasonal shifts for similar reasons; weather is everywhere a calendar of life, not just a news item."}},{"id":"asa-040","version":2,"slug":"pashtunwali-an-unwritten-code-of-hospitality-honour-and-refuge","contentType":"feature","category":"social-behaviour","title":{"ar":"البشتونwali: قانون الضيافة والشرف واللجوء","de":"Paschtunwali: Ehre, Gastfreundschaft und Zuflucht","en":"Pashtunwali: Honour, Hospitality and the Right of Refuge"},"deck":{"ar":"كيف ينظّم البشتون حياتهم اليومية عبر قانون غير مكتوب يوازن بين الكرم وحماية المستجير.","de":"Wie der ungeschriebene Ehrenkodex der Paschtunen den Alltag zwischen Gastrecht und Schutzverpflichtung prägt.","en":"How an unwritten code shapes daily life among Pashtuns, balancing extravagant hospitality with the duty to protect."},"teaser":{"ar":"في بيوت البشتون، الضيف ليس مجرد زائر؛ إنه اختبار للشرف. فكيف يعمل هذا القانون غير المكتوب في الحياة اليومية؟","de":"Ein Fremder klopft an die Tür und bittet um Schutz – der Hausherr gewährt ihn, bevor er nach dem Grund fragt. Was steckt hinter diesem ungeschriebenen Gesetz?","en":"A stranger knocks on a village door and asks for protection. The host shelters him first and only then asks what happened. What drives this unwritten law?"},"readingMinutes":1,"sections":{"ar":[{"heading":"ثلاثة أيام لا تُرد فيها الوسادة","paragraphs":["يُعرَّف البشتونwali بأنه مجموعة من الأعراف التي تحكم حياة البشتون، وتقوم على ثلاث ركائز: الميلماستيا (الضيافة)، والنناواتي (طلب اللجوء)، والبدل (الرد بالمثل أو الانتقام). فحين يصل غريب إلى باب أحد البيوت، تصبح الأسرة ملزمة بإيوائه وإطعامه ثلاثة أيام، بصرف النظر عن التكلفة أو هوية الضيف. هذا الالتزام ليس مجرد كرم، بل هو واجب أخلاقي واجتماعي، ويُعدّ اختبارًا لشرف المضيف.","في قرية نائية، يطرق رجل هارب من نزاع بابًا ويطلب النناواتي؛ فيؤويه صاحب البيت أولًا، ثم يسأله عمّا حدث لاحقًا، لأن الحماية تسبق التفسير. وبهذا يضمن القانون أن يجد المستجير ملاذًا حتى لو كان خصمًا. لكن هذا لا يعني أن الجميع يطبّقونه بالشكل ذاته؛ فالممارسات تختلف بين القبائل والمناطق، وكثير من البشتون في المدن يعيشون وفق قوانين الدولة والإسلام أكثر من العرف."]},{"heading":"الجيرغا: حين يتحدث الشيوخ","paragraphs":["يُفرض البشتونwali عبر الجيرغا، وهي مجالس شيوخ تحل النزاعات بالتوافق والسوابق العرفية بدلًا من المحاكم الرسمية. ففي النزاعات على الأرض أو الدم، يجتمع الشيوخ ويستمعون للطرفين، ثم يصدرون حكمًا ملزمًا اجتماعيًا. هذا النظام يتعايش بصعوبة مع الأنظمة القانونية الحديثة في باكستان وأفغانستان، حيث قد يتعارض العرف مع القانون الوضعي.","ومع ذلك، يبقى البشتونwali مرجعًا أخلاقيًا حاضرًا في الحياة اليومية، حتى لمن لا يلتزم به حرفيًا. فهو ليس قانونًا مكتوبًا، بل مثالية تُستدعى في النزاعات، وتختلف تطبيقاتها بحسب القبيلة والمنطقة والجيل."]}],"de":[{"heading":"Drei Tage, in denen die Tür offen bleibt","paragraphs":["Paschtunwali ist der traditionelle Ehrenkodex der Paschtunen, der auf drei Säulen ruht: Melmastia (Gastfreundschaft), Nanawatai (Zuflucht gewähren) und Badal (Gegenseitigkeit oder Rache). Die Gastfreundschaft verpflichtet einen Haushalt, jeden Gast drei Tage lang zu beherbergen und zu verpflegen, unabhängig von den Kosten oder der Identität des Gastes. Diese Pflicht ist keine bloße Höflichkeit, sondern eine Frage der Ehre.","In einem abgelegenen Dorf klopft ein Mann, der vor einem Streit flieht, an eine Tür und bittet um Nanawatai. Der Hausherr gewährt ihm zuerst Schutz und fragt erst danach, was geschehen ist – denn Schutz steht vor Erklärung. So findet selbst ein Gegner Zuflucht. Doch nicht überall wird der Kodex gleich gelebt: Die Praxis unterscheidet sich je nach Stamm und Region, und viele Paschtunen in den Städten richten sich stärker nach staatlichem Recht und dem Islam."]},{"heading":"Die Dschirga: wenn die Ältesten sprechen","paragraphs":["Durchgesetzt wird das Paschtunwali von Dschirgas, Räten der Ältesten, die Konflikte durch Konsens und Gewohnheitsrecht schlichten – nicht durch staatliche Gerichte. Bei Streit um Land oder Blut treffen sich die Ältesten, hören beide Seiten an und fällen eine sozial bindende Entscheidung. Dieses System steht in einem spannungsreichen Verhältnis zu den modernen Rechtssystemen in Pakistan und Afghanistan, wo Gewohnheitsrecht und staatliches Recht oft kollidieren.","Dennoch bleibt das Paschtunwali ein moralischer Bezugspunkt im Alltag, auch für diejenigen, die es nicht wörtlich befolgen. Es ist kein geschriebenes Gesetz, sondern ein Ideal, das in Konflikten beschworen wird – und dessen Anwendung je nach Stamm, Region und Generation variiert."]}],"en":[{"heading":"Three Days When the Door Stays Open","paragraphs":["Pashtunwali is the customary code of the Pashtun people, built around three pillars: melmastia (hospitality), nanawatai (offering refuge) and badal (reciprocity or revenge). Hospitality obliges a household to shelter and feed any guest for three days, regardless of cost or the guest's identity. This is not mere politeness but a matter of honour, and it applies even to a complete stranger.","In a remote village, a man fleeing a dispute knocks on a door and asks for nanawatai. The host shelters him first and only afterwards asks what happened, because protection comes before explanation. This way, even an enemy can find refuge. Yet the code is not applied uniformly: tribal practice differs, and many Pashtuns in cities live under state law and Islam more decisively than under custom."]},{"heading":"The Jirga: When Elders Speak","paragraphs":["Pashtunwali is enforced through jirgas, councils of elders that settle disputes by consensus and customary precedent rather than state courts. In conflicts over land or blood, the elders gather, hear both sides and issue a socially binding decision. This system coexists uneasily with modern legal systems in Pakistan and Afghanistan, where customary and statutory law often clash.","Nevertheless, Pashtunwali remains a moral reference point in daily life, even for those who do not follow it literally. It is not a written law but an ideal invoked in disputes, and its application varies by tribe, region and generation."]}]},"context":{"countries":["PK","AF"],"region":"Pashtun belt","community":"Pashtuns","continent":"asia","languages":["ps","ur"],"period":"contemporary"},"tags":["social-behaviour","Pashtun belt","Pashtunwali is","Hospitality obliges"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pashtunwali","de":"Pashtunwali","en":"Pashtunwali"},"url":"https://en.wikipedia.org/wiki/Pashtunwali","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}},{"organization":"Wikipedia","title":{"ar":"Pashtuns","de":"Pashtuns","en":"Pashtuns"},"url":"https://en.wikipedia.org/wiki/Pashtuns","accessed":"2026-11-17","supports":{"ar":"Background facts and context for this article.","de":"Background facts and context for this article.","en":"Background facts and context for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"غريب يفر من خلاف يطرق بابًا في قرية ويطلب النناواتي؛ يؤويه المضيف أولًا ثم يسأله عما حدث، لأن الحماية تأتي قبل التفسير.","de":"Ein Fremder, der vor einem Streit flieht, klopft an eine Dorftür und bittet um Nanawatai; der Hausherr gewährt ihm zuerst Schutz und fragt erst danach nach den Hintergründen, weil Schutz vor Erklärung geht.","en":"A stranger fleeing a dispute knocks on a village door and asks for nanawatai; the host shelters him first and only afterwards asks what happened, because protection comes before explanation."},"misunderstanding":{"ar":"ليس كل بشتوني يطبّق البشتونwali بالشكل ذاته؛ فكثيرون يعيشون في المدن ويحكّمون القانون الرسمي، لذا من الخطأ تعميم الصورة النمطية عن «قانون الصحراء».","de":"Nicht jeder Paschtune befolgt das Paschtunwali auf dieselbe Weise; viele leben in Städten und richten sich nach staatlichem Recht. Das Klischee vom „Wüstengesetz“ ist eine Vereinfachung.","en":"Not every Pashtun follows Pashtunwali in the same way; many live in cities and rely on state law. The stereotype of a single 'desert law' oversimplifies a diverse reality."},"comparison":{"ar":"على عكس قوانين الضيافة في المجتمعات الغربية التي تقتصر على دعوة مسبقة، فإن البشتونwali يفرض واجب الإيواء حتى على الغريب تمامًا.","de":"Anders als westliche Gastfreundschaft, die meist auf Einladung beruht, verpflichtet das Paschtunwali zur Aufnahme selbst eines völlig Fremden.","en":"Unlike Western hospitality, which usually requires a prior invitation, Pashtunwali obliges a household to take in even a complete stranger."}},{"id":"asa-041","version":2,"slug":"basant-the-spring-sky-full-of-fighting-kites","contentType":"note","category":"traditions","title":{"ar":"بسنت: سماء الربيع مليئة بالطائرات الورقية المقاتلة","de":"Basant: Der Frühlingshimmel voller kämpfender Drachen","en":"Basant: The Spring Sky Full of Fighting Kites"},"deck":{"ar":"في البنجاب، يحول بسنت أسطح المنازل إلى حلبات قتال ورقية مع حلول فبراير.","de":"In Punjab verwandelt Basant die Dächer im Februar in Arenen für Drachenkämpfe.","en":"In Punjab, Basant turns rooftops into kite-fighting arenas as February warms the air."},"teaser":{"ar":"عيد بسنت الربيعي في البنجاب يجمع العائلات على الأسطح لقتال الطائرات الورقية، مع تاريخ هندوسي وتحولات أمنية.","de":"Basant in Punjab bringt Familien auf die Dächer zum Drachenkampf, mit hinduistischen Wurzeln und wechselnden Sicherheitsauflagen.","en":"Basant in Punjab brings families to rooftops for kite fighting, with Hindu roots and shifting safety restrictions across the region."},"readingMinutes":1,"sections":{"ar":[{"heading":"طائرات ورقية في سماء الربيع","paragraphs":["بسنت هو مهرجان ربيعي في البنجاب، ارتبط تاريخياً برفع الطائرات الورقية في لاهور ومدن أخرى مع دفء الطقس في فبراير. تمتلئ الأسطح بالعائلات والموسيقى، حيث يقطع المقاتلون خطوط منافسيهم بخيط مطلي بالزجاج يسمى مانجا، وتسمى الرياضة قتال الطائرات الورقية.","للاحتفال جذور هندوسية واعتنقته مجتمعات مختلفة؛ وفي باكستان أصبح احتفالاً حضرياً شعبياً وجاذباً للسياح. كما يوجد بسنت في البنجاب الهندية وبين المغتربين، حيث يكون غالباً مناسبة ثقافية لا دينية."]},{"heading":"قيود وأصوات متباينة","paragraphs":["أدت مخاوف السلامة بشأن الخيوط المطلية بالمعدن والزجاج إلى حظر ومواسم مقيدة، وتفاوت التنفيذ بين المحافظات والحكومات. يختلف الحظر والتواريخ والحماس حسب المدينة والسنة، ويحتفل المسلمون والهندوس والسيخ بطرق مختلفة، وقد دفعت القيود الرسمية كثيراً من الطيران إلى الخفاء."]}],"de":[{"heading":"Drachen im Frühlingshimmel","paragraphs":["Basant ist ein Frühlingsfest in Punjab, das historisch mit dem Drachensteigen in Lahore und anderen Städten verbunden ist, wenn es im Februar wärmer wird. Dächer füllen sich mit Familien und Musik; Kämpfer schneiden die Schnüre ihrer Rivalen mit glasbeschichtetem Garn namens Manja durch, und der Sport heißt Drachenkampf.","Das Fest hat hinduistische Wurzeln und wurde von verschiedenen Gemeinschaften übernommen; in Pakistan wurde es zu einer beliebten städtischen Feier und Touristenattraktion. Basant gibt es auch im indischen Punjab und in der Diaspora, wo es oft ein kultureller而非 religiöser Anlass ist."]},{"heading":"Einschränkungen und unterschiedliche Stimmen","paragraphs":["Sicherheitsbedenken wegen metall- und glasbeschichteter Schnüre führten zu Verboten und eingeschränkten Saisons, und die Durchsetzung variierte je nach Provinz und Regierung. Verbote, Termine und Begeisterung unterscheiden sich nach Stadt und Jahr; Muslimen, Hindus und Sikhs feiern auf unterschiedliche Weise, und offizielle Beschränkungen haben viel Drachensteigen in den Untergrund gedrängt."]}],"en":[{"heading":"Kites in the Spring Sky","paragraphs":["Basant is a spring festival in Punjab, historically associated with kite flying in Lahore and other cities as the weather warms in February. Rooftops fill with families and music; kite fighters cut rivals' lines with glass-coated string called manja, and the sport is called kite fighting.","The festival has Hindu roots and was adopted across communities; in Pakistan it became a popular urban celebration and a tourist draw. Basant also exists in Indian Punjab and among the diaspora, where it is often a cultural rather than religious occasion."]},{"heading":"Restrictions and Mixed Voices","paragraphs":["Safety concerns about metal-coated and glass-coated string led to bans and restricted seasons, and enforcement has varied by province and government. Bans, dates and enthusiasm vary by city and year; the festival is celebrated by Muslims, Hindus and Sikhs in different ways, and official restrictions have pushed much flying underground."]}]},"context":{"countries":["PK","IN"],"region":"Punjab","continent":"asia","languages":["pa","ur"],"period":"contemporary"},"tags":["traditions","Punjab"],"sources":[{"organization":"Wikipedia","title":{"ar":"Basant (festival)","de":"Basant (festival)","en":"Basant (festival)"},"url":"https://en.wikipedia.org/wiki/Basant_(festival)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Fighter kite","de":"Fighter kite","en":"Fighter kite"},"url":"https://en.wikipedia.org/wiki/Fighter_kite","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في فبراير يمتلئ سطح منزل في لاهور بأبناء العمومة يمسكون بكرات الخيط؛ مبارزة طائرات ورقية تثير الصيحات عند قطع خيط، وتنجرف طائرة الفائز فوق الحي.","de":"Im Februar füllt sich ein Dach in Lahore mit Cousins, die Spulen halten; ein Drachenduell löst Rufe aus, wenn eine Schnur reißt, und der Drachen des Siegers treibt über die Nachbarschaft.","en":"In February a Lahore rooftop fills with cousins holding spool reels; a kite duel draws shouts when a string cuts, and the winner's kite drifts over the neighbourhood."},"misunderstanding":{"ar":"يعتقد البعض أن بسنت مهرجان ديني بحت، لكنه في باكستان والشتات غالباً مناسبة ثقافية يجتمع حولها الناس من خلفيات مختلفة.","de":"Manche halten Basant für ein rein religiöses Fest, doch in Pakistan und der Diaspora ist es oft ein kultureller Anlass, bei dem Menschen verschiedener Herkunft zusammenkommen.","en":"Some assume Basant is purely religious, but in Pakistan and the diaspora it is often a cultural occasion that brings together people from different backgrounds."},"comparison":{"ar":"بينما يرتبط بسنت في لاهور بالأسطح والقتال الورقي، فإنه في البنجاب الهندية قد يتخذ شكل تجمعات ثقافية وأخرى دينية، مع اختلافات حسب المدينة والجيل.","de":"Während Basant in Lahore mit Dächern und Drachenkämpfen verbunden ist, kann es im indischen Punjab kulturelle und religiöse Formen annehmen, mit Unterschieden je nach Stadt und Generation.","en":"While Basant in Lahore is tied to rooftops and kite fighting, in Indian Punjab it can take cultural and religious forms, with differences by city and generation."}},{"id":"asa-042","version":2,"slug":"qawwali-turning-a-shrine-courtyard-into-a-trance-floor","contentType":"note","category":"music-and-dance","title":{"ar":"القوالي: تحويل ساحة الضريح إلى أرضية نشوة","de":"Qawwali: Ein Schreinvorhof wird zur Trancefläche","en":"Qawwali: Turning a Shrine Courtyard into a Trance Floor"},"deck":{"ar":"موسيقى صوفية من جنوب آسيا تحول الاستماع إلى تجربة جماعية","de":"Südasiatische Sufi-Musik, die Zuhören in ein gemeinsames Erlebnis verwandelt","en":"South Asian Sufi music that transforms listening into a collective experience"},"teaser":{"ar":"في ساحات الأضرحة، يجتمع الناس حول المغني الرئيسي والجوقة، حيث تتصاعد الأنغام والكلمات لتأخذهم في رحلة روحانية.","de":"Auf Schreinvorhöfen versammeln sich Menschen um den Leadsänger und den Chor, während Melodien und Worte sie auf eine spirituelle Reise mitnehmen.","en":"In shrine courtyards, people gather around the lead singer and chorus as melodies and words carry them on a spiritual journey."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور صوفية وحضور حي","paragraphs":["القوالي هو شكل من أشكال الموسيقى التعبدية في التصوف بجنوب آسيا، يؤديها مغنٍ رئيسي وجوقة مع الهارمونيوم والطبلة والدولاك. نشأ في التقليد الصوفي الجشتي، الذي يتمركز حول الأضرحة في ما يعرف الآن بباكستان والهند، ويُؤدى في إحياء ذكرى الأولياء وفي المجالس الخاصة.","تضع الأغاني الشعر الصوفي بالأردية والبنجابية على لازمة متكررة تبني الكثافة، وقد يدخل المستمعون في حالة استغراق روحي."]},{"heading":"تفاعل وتنوع في الأداء","paragraphs":["غالبًا ما يرتجل المؤدون أبياتًا ويغيرون الإيقاع استجابةً للجمهور، مما يجعل كل أداء مختلفًا. وقد جلب نورسات فتح علي خان القوالي إلى جماهير عالمية في الثمانينيات والتسعينيات، وأصبح يظهر الآن في موسيقى الأفلام ومشاريع الدمج. يختلف الأسلوب أيضًا حسب المنطقة والجيل، إذ يميل المؤدون الشباب إلى مزج عناصر معاصرة مع الأشكال التقليدية."]}],"de":[{"heading":"Sufistische Wurzeln und lebendige Aufführung","paragraphs":["Qawwali ist eine devotionale Musikform des südasiatischen Sufismus, aufgeführt von einem Leadsänger, einem Chor, Harmonium, Tabla und Dholak. Sie entstand in der Chishti-Sufi-Tradition, die sich um Schreine im heutigen Pakistan und Indien konzentriert, und wird bei Urs-Gedenkfeiern und privaten Mehfils aufgeführt.","Die Lieder vertonen Urdu- und Punjabi-Mystik auf wiederholte Refrains, die Intensität aufbauen, und Zuhörer können in einen Zustand spiritueller Versenkung geraten."]},{"heading":"Interaktion und Wandel","paragraphs":["Die Aufführenden improvisieren oft Verse und ändern das Tempo als Reaktion auf das Publikum, sodass jede Aufführung anders ist. Nusrat Fateh Ali Khan brachte Qawwali in den 1980er und 1990er Jahren einem globalen Publikum nahe, und heute erscheint die Form in Filmmusik und Fusionsprojekten. Auch regional und generationell gibt es Unterschiede: Jüngere Künstler neigen dazu, zeitgenössische Elemente mit traditionellen Formen zu mischen."]}],"en":[{"heading":"Sufi Roots and Living Performance","paragraphs":["Qawwali is a devotional music form of South Asian Sufism, performed by a lead singer, a chorus, harmonium, tabla and dholak. It grew in the Chishti Sufi tradition, centred on shrines in what is now Pakistan and India, and is performed at urs commemorations and private mehfils.","Songs set Urdu and Punjabi mystical poetry to repeated refrains that build intensity, and listeners may enter a state of spiritual absorption."]},{"heading":"Interaction and Evolution","paragraphs":["Performers often improvise verses and change tempo in response to the audience, making each performance different. Nusrat Fateh Ali Khan brought qawwali to global audiences in the 1980s and 1990s, and the form now appears in film soundtracks and fusion projects. Style also varies by region and generation, with younger performers tending to blend contemporary elements with traditional forms."]}]},"context":{"countries":["PK","IN"],"region":"Punjab and Sindh","continent":"asia","languages":["ur","pa"],"period":"contemporary"},"tags":["music-and-dance","Punjab and Sindh"],"sources":[{"organization":"Wikipedia","title":{"ar":"Qawwali","de":"Qawwali","en":"Qawwali"},"url":"https://en.wikipedia.org/wiki/Qawwali","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Sufism","de":"Sufism","en":"Sufism"},"url":"https://en.wikipedia.org/wiki/Sufism","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في ساحة ضريح في لاهور، يكرر المغني الرئيسي سطرًا ويرفع يده؛ يتصاعد صوت الهارمونيوم، ويقف المستمعون ويتمايلون، ويتقرب الجمهور من المسرح.","de":"Auf einem Schreinvorhof in Lahore wiederholt der Leadsänger eine Zeile und hebt die Hand; das Harmonium schwillt an, Zuhörer stehen auf und wiegen sich, und die Menge drängt näher an die Bühne.","en":"At a shrine courtyard in Lahore the lead singer repeats a line and raises his hand; the harmonium swells, listeners stand and sway, and the crowd presses closer to the stage."},"misunderstanding":{"ar":"القوالي ممارسة تعبدية وليس مجرد موسيقى حفلات، وكلماته تأتي من عدة لغات وتقاليد شعرية؛ النشوة ليست مضمونة أو مطلوبة.","de":"Qawwali ist devotionale Praxis, nicht nur Konzertmusik, und die Texte stammen aus mehreren Sprachen und poetischen Traditionen; Trance ist nicht garantiert oder erforderlich.","en":"Qawwali is devotional practice, not only concert music, and its lyrics come from several languages and poetic traditions; trance is not guaranteed or required."},"comparison":{"ar":"بينما تُؤدى القوالي في سياقات دينية، فإنها تجد طريقها أيضًا إلى قاعات الحفلات والأفلام، مما يخلق توترًا بين الأصالة والتجديد.","de":"Während Qawwali in religiösen Kontexten aufgeführt wird, findet sie auch ihren Weg in Konzertsäle und Filme, was eine Spannung zwischen Authentizität und Erneuerung erzeugt.","en":"While qawwali is performed in religious settings, it also finds its way into concert halls and films, creating a tension between authenticity and renewal."}},{"id":"asa-043","version":2,"slug":"adda-the-purposeless-conversation-that-holds-bengali-life-together","contentType":"scene","category":"everyday-life","title":{"ar":"أدّا: حديث بلا غاية يجمع الحياة البنغالية","de":"Adda: das zwecklose Gespräch, das Bengalen zusammenhält","en":"Adda: the purposeless talk that binds Bengali life"},"deck":{"ar":"جلسات الكلام الطويل بلا جدول أعمال، من أكشاك الشاي إلى غرف الجلوس، حيث تكون المتعة في التبادل نفسه لا في قرار يُتخذ.","de":"Lange, formlose Gespräche am Teestand, im Buchladen oder im Wohnzimmer, bei denen das Gespräch selbst der Zweck ist.","en":"Long, informal conversations at a tea stall, bookshop or sitting room, where the exchange itself is the point and no conclusion is needed."},"teaser":{"ar":"في البنغال يجتمع الناس ساعات على الشاي والكلام، من السياسة إلى الكريكيت، ثم يفترقون دون أن يحسموا شيئًا.","de":"In Bengalen sitzt man stundenlang bei Tee zusammen, spricht über Politik, Cricket und Philosophie und geht ohne Beschluss nach Hause.","en":"In Bengal people gather for hours over tea, talk politics, cricket and philosophy, then go home without deciding anything at all."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما معنى أدّا","paragraphs":["أدّا هو عادة بنغالية في الحديث الطويل غير الرسمي، في كشك شاي أو مكتبة أو زاوية شارع أو غرفة جلوس، بلا جدول أعمال ولا حاجة إلى خاتمة.","يمتد الكلام من السياسة والكريكيت إلى الغossip والفلسفة، والمتعة في التبادل نفسه لا في قرار يُتخذ.","كان أدّا محور الحياة الفكرية البنغالية في العهد الاستعماري، وصارت المقاهي والمكتبات في كالكوتا أماكن شهيرة له.","تختلف أشكاله بين بنغلاديش والبنغال الغربية، وبين الأجيال، فالأصغر يمارسه عبر الهاتف أو في مقاهٍ حديثة أكثر مما في زوايا الشارع."]},{"heading":"تراجع وانتشار","paragraphs":["في داكا وكالكوتا يوصف أدّا الأقدم بأنه يتراجع أمام الهواتف الذكية والتنقل الطويل والشقق الأصغر.","لكن للعادة مكانة أدبية، فقد تعامل معها كتّاب المقالات وصنّاع الأفلام كشكل اجتماعي بنغالي مميز.","وهي أقرب إلى مثال يُحتذى من مؤسسة موحّدة، فليس لكل أحد وقت الفراغ أو المكان الذي يسمح بها."]}],"de":[{"heading":"Was Adda bedeutet","paragraphs":["Adda ist die bengalische Praxis des langen, informellen Gesprächs, am Teestand, im Buchladen, an der Straßenecke oder im Wohnzimmer, ohne Tagesordnung und ohne Abschluss.","Das Gespräch reicht von Politik und Cricket bis zu Klatsch und Philosophie, und die Freude liegt im Austausch, nicht in einer Entscheidung.","In der Kolonialzeit war Adda zentral für das intellektuelle Leben Bengalens, und Kaffeehäuser und Buchläden in Kolkata wurden zu berühmten Orten dafür.","Die Formen unterscheiden sich zwischen Bangladesch und Westbengalen und zwischen den Generationen, wobei Jüngere sie eher am Telefon oder in modernen Cafés pflegen."]},{"heading":"Rückzug und literarischer Rang","paragraphs":["In Dhaka und Kolkata gilt die ältere Adda-Kultur oft als rückläufig angesichts von Smartphones, Pendelwegen und kleineren Wohnungen.","Zugleich hat die Praxis literarischen Rang, denn Essayisten und Filmemacher behandelten Adda als eigenständige bengalische Sozialform.","Sie ist eher ein Ideal als eine einheitliche Institution, denn nicht jede und jeder hat die Muße oder den Raum dafür."]}],"en":[{"heading":"What adda actually is","paragraphs":["Adda is the Bengali practice of long, informal conversation, at a tea stall, a bookshop, a street corner or someone's sitting room, with no agenda and no need to conclude.","The talk ranges from politics and cricket to gossip and philosophy, and the pleasure lies in the exchange rather than a decision.","Adda was central to colonial-era Bengali intellectual life, and coffee houses and bookshops in Kolkata became famous venues for it.","Its forms differ between Bangladesh and West Bengal and across generations, with younger people often holding adda by phone or in newer cafés."]},{"heading":"Retreat and literary standing","paragraphs":["In Dhaka and Kolkata, older adda culture is often described as retreating before smartphones, commuting and smaller apartments.","Yet the practice has literary status, since essayists and filmmakers have treated adda as a distinctly Bengali social form.","It is more an ideal than a uniform institution, and not everyone has the leisure or the space for it."]}]},"context":{"countries":["BD","IN"],"region":"Bengal","continent":"asia","languages":["bn"],"period":"contemporary"},"tags":["everyday-life","Bengal"],"sources":[{"organization":"Wikipedia","title":{"ar":"Adda (South Asian)","de":"Adda (South Asian)","en":"Adda (South Asian)"},"url":"https://en.wikipedia.org/wiki/Adda_(South_Asian)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Bengal","de":"Culture of Bengal","en":"Culture of Bengal"},"url":"https://en.wikipedia.org/wiki/Culture_of_Bengal","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يجتمع ثلاثة أصدقاء عند كشك شاي بعد العمل، يطلبون أكوابًا صغيرة لا تنتهي، يتجادلون حول فيلم ساعتين، ثم يعودون إلى بيوتهم دون أن يحسموا شيئًا.","de":"Drei Freunde treffen sich nach der Arbeit am Teestand, bestellen endlos kleine Gläser Tee, streiten zwei Stunden über einen Film und gehen heim, ohne etwas entschieden zu haben.","en":"Three friends meet at a tea stall after work, order endless small glasses of tea, argue about a film for two hours and go home without deciding anything."},"misunderstanding":{"ar":"يظن البعض أن أدّا مضيعة وقت أو حديث فارغ، لكن قيمته في العلاقة نفسها لا في نتيجة عملية.","de":"Manche halten Adda für Zeitverschwendung oder leeres Gerede, doch sein Wert liegt in der Beziehung selbst, nicht in einem Ergebnis.","en":"Some dismiss adda as wasted time or empty talk, but its value lies in the relationship itself, not in a practical result."},"comparison":{"ar":"يشبه أدّا الجلسات الطويلة في المقاهي حول العالم، لكنه لا ينتظر خلاصة ولا يهدف إلى إنجاز.","de":"Adda ähnelt langen Cafégesprächen weltweit, erwartet aber weder Fazit noch Erledigung.","en":"Adda resembles long café conversations elsewhere, yet it expects neither a conclusion nor a task completed."}},{"id":"asa-044","version":2,"slug":"pohela-boishakh-a-new-year-that-became-a-civic-procession","contentType":"note","category":"traditions","title":{"ar":"بويلا بويشاخ: رأس سنة صار موكبًا مدنيًا","de":"Pohela Boishakh: Neujahr wird zum Bürgerumzug","en":"Pohela Boishakh: a new year that became a civic procession"},"deck":{"ar":"في بنغلاديش وغرب البنغال يبدأ العام البنغالي الجديد بمواكب وأقمشة حمراء وبيضاء وأطباق بسيطة تجمع العائلات.","de":"In Bangladesch und Westbengalen beginnt das bengalische Jahr mit Umzügen, roten und weißen Stoffen und einfachen Gerichten am Familientisch.","en":"In Bangladesh and West Bengal the Bengali year opens with street processions, red-and-white cloth and a simple meal shared at family tables."},"teaser":{"ar":"عيد رأس السنة البنغالي في الرابع عشر من أبريل يجمع بين مواكب الطلاب وأسواق الأقمشة والحسابات الجديدة وطعام بسيط على مائدة واحدة.","de":"Das bengalische Neujahr am 14. April verbindet Schülerumzüge, neue Geschäftsbücher, Stoffmärkte und ein bescheidenes Essen auf einer gemeinsamen Tafel.","en":"The Bengali New Year on 14 April brings student processions, fresh account books, cloth markets and a humble dish eaten together across generations."},"readingMinutes":1,"sections":{"ar":[{"heading":"صباح المواكب والألوان","paragraphs":["يبدأ اليوم في دكا قبل شروق الشمس، حين يرفع الطلاب أقنعة ضخمة على هياكل من الخيزران ويضبط الطبالون إيقاعهم، ثم يمر الموكب في الشوارع. سُجّل هذا الموكب، المعروف باسم مانغال شوبهايترا، في قائمة اليونسكو للتراث غير المادي عام 2016، لكنه لم يبدأ إلا في عام 1989.","يرتدي الناس الأحمر والأبيض، وتنتشر الأسواق والمعارض والأغاني. وتختلف العادات والتواريخ بين بنغلاديش والبنغال الغربية وتريبورا، كما تتباين بين الأجيال داخل العائلة الواحدة."]},{"heading":"حسابات جديدة وطعام بسيط","paragraphs":["تفتح المتاجر دفاتر حسابات جديدة في طقس يُسمى هالكهاتا، فيجتمع التجار مع زبائنهم على مائدة واحدة بدلًا من دفتر الأستاذ فقط.","على مائدة العائلة يظهر طبق بسيط: بانطا بهات مع سمك مقلي، طعام متواضع يرتبط بهذا اليوم ارتباطًا وثيقًا.","في الستينيات رُوّج للعيد كعلامة هوية بنغالية علمانية متميزة عن الأعياد الدينية، وانتقلت الاحتفالات لاحقًا إلى المجتمعات البنغالية في الخارج."]}],"de":[{"heading":"Ein Morgen voller Masken und Farben","paragraphs":["In Dhaka beginnt der Tag vor Sonnenaufgang: Studierende heben riesige Masken auf Bambusgestelle, Trommler stimmen ihre Instrumente, dann zieht der Umzug durch die Straßen. Dieser Mangal Shobhajatra genannte Zug wurde 2016 von der UNESCO als immaterielles Erbe gelistet, entstand aber erst 1989.","Die Menschen tragen Rot und Weiß, Märkte, Lieder und Messen füllen die Stadt. Bräuche und Daten unterscheiden sich zwischen Bangladesch, Westbengalen und Tripura und variieren auch zwischen den Generationen einer Familie."]},{"heading":"Neue Bücher, einfaches Essen","paragraphs":["Geschäfte öffnen neue Kontobücher, ein Ritual namens Halkhata, bei dem Händler und Kundschaft gemeinsam am Tisch sitzen statt nur im Hauptbuch zu blättern.","Auf den Familientischen steht Panta Bhat mit gebratenem Fisch, ein schlichtes Gericht, das eng mit diesem Tag verbunden ist.","In den 1960er Jahren wurde das Fest als säkulare bengalische Identitätsmarke abseits religiöser Feiertage beworben; später breitete es sich in bengalische Gemeinschaften im Ausland aus."]}],"en":[{"heading":"A morning of masks and colour","paragraphs":["In Dhaka the day opens before sunrise, as students lift huge masks onto bamboo frames and drummers tune up, then the procession winds through the streets. This Mangal Shobhajatra was listed by UNESCO as intangible heritage in 2016, though it only began in 1989.","People wear red and white, and fairs, songs and markets fill the city. Dates and customs differ between Bangladesh, West Bengal and Tripura, and they also vary between generations within one family."]},{"heading":"New books, a simple plate","paragraphs":["Shops open new account books in a ritual called halkhata, when traders and customers sit together at a table instead of only in the ledger.","On family tables appears panta bhat with fried fish, a plain dish closely tied to the day.","In the 1960s the festival was promoted as a secular Bengali identity marker distinct from religious holidays, and celebrations later spread to Bengali communities abroad."]}]},"context":{"countries":["BD","IN"],"region":"Bengal","continent":"asia","languages":["bn"],"period":"contemporary"},"tags":["traditions","Bengal"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pohela Boishakh","de":"Pohela Boishakh","en":"Pohela Boishakh"},"url":"https://en.wikipedia.org/wiki/Pohela_Boishakh","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Mangal Shobhajatra","de":"Mangal Shobhajatra","en":"Mangal Shobhajatra"},"url":"https://en.wikipedia.org/wiki/Mangal_Shobhajatra","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"قبل الشروق يرفع الطلاب قناع نمر وطائر ضخم على إطار من الخيزران، ويضبط الطبالون طبولهم، ويمر الموكب في دكا بينما ترتدي العائلات الأحمر والأبيض وتزور الأسواق.","de":"Vor Sonnenaufgang heben Studierende eine riesige Maske aus Tiger und Vogel auf Bambusrahmen, Trommler stimmen sich ein, der Zug windet sich durch Dhaka, während Familien Rot und Weiß tragen und Märkte besuchen.","en":"Before sunrise students lift a giant tiger-and-bird mask onto bamboo frames, drummers tune up, and the procession winds through Dhaka while families wear red and white and visit fairs."},"misunderstanding":{"ar":"يُفهم العيد أحيانًا كاحتفال ديني بحت، لكنه يجمع عناصر علمانية ودينية معًا، وتختلف تفاصيله بين البلدان والمناطق.","de":"Manchmal gilt das Fest als rein religiöse Feier, doch es mischt säkulare und religiöse Elemente, und seine Formen unterscheiden sich je nach Land und Region.","en":"The day is sometimes read as purely religious, yet it mixes secular and religious elements, and its details vary by country and region."},"comparison":{"ar":"في بنغلاديش يقام العيد في 14 أبريل، وفي أجزاء من الهند في 15 أبريل، وفق التقويم البنغالي المعدّل.","de":"In Bangladesch fällt das Fest auf den 14. April, in Teilen Indiens auf den 15. April, nach dem überarbeiteten bengalischen Kalender.","en":"In Bangladesh the festival falls on 14 April, in parts of India on 15 April, following the revised Bengali calendar."}},{"id":"asa-045","version":2,"slug":"the-language-movement-when-a-script-became-a-country-s-reason","contentType":"feature","category":"cultural-change","title":{"ar":"حركة اللغة: حين صار الحرف سبباً لبلد","de":"Die Sprachbewegung: als Schrift zum Staatsgrund wurde","en":"The language movement: when a script became a country's reason"},"deck":{"ar":"كيف حوّل طلاب في دكا مطلبهم بلغتهم الأم إلى ذكرى عالمية، وإلى وعي سياسي قاد إلى استقلال بنغلاديش.","de":"Wie Studierende in Dhaka aus der Forderung nach ihrer Muttersprache eine weltweite Erinnerung und politisches Bewusstsein machten.","en":"How students in Dhaka turned a demand for their mother tongue into a global remembrance and a political consciousness that led to independence."},"teaser":{"ar":"في عام 1952 سقط طلاب في دكا دفاعاً عن لغتهم البنغالية، وتحوّل ذلك اليوم إلى ذكرى عالمية تحتفي بها اليونسكو كل عام.","de":"1952 fielen in Dhaka Studierende für ihre bangla Sprache. Heute erinnert ein weltweiter Tag an sie, und die Bewegung prägte den Weg zur Unabhängigkeit.","en":"In 1952 students in Dhaka died for their Bangla language. Today a worldwide day honours them, and the movement helped shape a nation's path."},"readingMinutes":2,"sections":{"ar":[{"heading":"قرار اللغة الواحدة","paragraphs":["بعد تقسيم شبه القارة الهندية عام 1947، دفعت حكومة باكستان باللغة الأردية لتكون اللغة الرسمية الوحيدة للدولة، رغم أن غالبية سكان باكستان الشرقية كانوا يتحدثون البنغالية في بيوتهم وأسواقهم ومدارسهم.","لم يكن القرار مجرد مسألة إدارية، بل مساساً بهوية الناس اليومية: بالكلمات التي يسمّون بها أبناءهم، والأغاني التي يردّدونها في المدرسة، والخط الذي يقرأون به الصحف."]},{"heading":"الطلاب في الشارع","paragraphs":["نظّم الطلاب والمنظمات الثقافية احتجاجات متواصلة، وبلغ التوتر ذروته في 21 فبراير 1952 حين أطلقت الشرطة النار على مظاهرة في دكا، فسقط عدد من الطلاب قتلى.","تحوّلت تلك الوفيات إلى ذكرى مؤسِّسة، لا تُروى كخبر عابر بل كجرح مشترك يتوارثه الناس جيلاً بعد جيل.","اليوم تتباين أشكال إحياء هذه الذكرى بين الأجيال والمناطق، بين من يحضر المسيرات ومن يتابعها عبر الشاشات."]},{"heading":"من الحرف إلى الدولة","paragraphs":["اعتُرف بالبنغالية لغةً رسمية للدولة عام 1956، لكن الحركة لم تتوقف عند هذا الاعتراف، بل ساعدت في بناء الوعي السياسي الذي قاد إلى استقلال بنغلاديش عام 1971.","ويقف نصب الشهيد مينار في دكا عند موقع الأحداث، ويُحيّى اليوم بمسيرات حافية الأقدام وأغانٍ جماعية.","وتُروى هذه الحركة في باكستان بصيغة مختلفة، كما أن سياسات اللغة في المنطقة شملت لغات أخرى كالأردية والسندية والبنجابية."]},{"heading":"الذكرى في التفاصيل اليومية","paragraphs":["في منتصف ليل 21 فبراير، يسير الحشود حفاة الأقدام نحو الشهيد مينار حاملين الزهور، ويشدو أطفال المدارس بأغنية «عمار بيهاي روكته رانغانو» (أي: دم أخي لوّنها بالأحمر).","هكذا تتحول اللغة من موضوع نقاش إلى ممارسة جسدية جماعية، تُختبر فيها الذاكرة بالقدمين والصوت."]},{"heading":"لغة تحفظ أصحابها","paragraphs":["ما جرى في دكا يعيد التذكير بأن اللغة ليست زينة ثقافية، بل شرط من شروط الكرامة، وأن الناس قد يخاطرون بحياتهم حين يُطلب منهم التخلي عنها.","ولأن اليوم صار مناسبة عالمية، فإن الاحتفاء باللغات الأم صار يذكّر بأن كل لغة صغيرة تحمل تجربة إنسانية كاملة."]},{"heading":"أبعد من الحدث","paragraphs":["لا تزال حركة اللغة حاضرة في النقاش حول التعليم والهوية في جنوب آسيا، حيث تتشابك اللغات مع السياسة والحدود.","ومن هنا يبقى الدرس بسيطاً وقوياً: عندما يُصغي الناس إلى لغتهم، فإنهم يصغون إلى أنفسهم."]},{"heading":"أثر طويل","paragraphs":["مرّت عقود على تلك الليلة، لكن الحدث يحتفظ بقدرته على تحريك المشاعر، لأنه يخصّ الناس لا المتاحف.","وحين يقرأ المرء عن اللغة البنغالية اليوم، فإنه يقرأ عن مجتمع يتذكّر ضحاياه بالكلمات."]}],"de":[{"heading":"Ein Staat, eine Sprache","paragraphs":["Nach der Teilung 1947 förderte Pakistans Regierung Urdu als einzige Staatssprache, obwohl die Mehrheit der Bevölkerung Ostpakistans Bengali sprach.","Der Beschluss betraf nicht nur Ämter, sondern den Alltag: die Wörter, mit denen Menschen ihre Kinder rufen, die Lieder in der Schule, die Schrift der Zeitung."]},{"heading":"Studierende auf der Straße","paragraphs":["Studierende und Kulturorganisationen protestierten; am 21. Februar 1952 schoss die Polizei in Dhaka auf eine Demonstration und tötete mehrere Studierende.","Diese Toten wurden zur Gründungserinnerung, die von Generation zu Generation weitergegeben wird.","Wie dieser Tag begangen wird, unterscheidet sich regional und zwischen den Generationen, je nach Familie und Umfeld."]},{"heading":"Vom Buchstaben zur Nation","paragraphs":["1956 wurde Bengali als Staatssprache anerkannt, doch die Bewegung endete dort nicht: Sie half, das politische Bewusstsein zu formen, das 1971 zur Unabhängigkeit Bangladeschs führte.","Das Shaheed Minar in Dhaka markiert den Ort, und der Tag wird mit barfüßigen Prozessionen und Liedern begangen.","In Pakistan wird diese Geschichte anders erzählt, und die Sprachpolitik der Region betraf auch Urdu, Sindhi und Punjabi."]},{"heading":"Erinnerung im Alltag","paragraphs":["Um Mitternacht des 21. Februar gehen Menschen barfuß zum Shaheed Minar, tragen Blumen, und Schulkinder singen „Amar Bhaier Rokte Rangano“ (Das Blut meines Bruders färbte es rot).","So wird Sprache zu einer körperlichen gemeinsamen Handlung, in der Erinnerung mit Füßen und Stimme geprüft wird."]},{"heading":"Sprache, die Menschen trägt","paragraphs":["Was in Dhaka geschah, erinnert daran, dass Sprache keine kulturelle Zierde ist, sondern eine Bedingung von Würde.","Weil der Tag heute weltweit begangen wird, mahnt er daran, dass jede kleine Sprache eine ganze menschliche Erfahrung trägt."]},{"heading":"Über den Tag hinaus","paragraphs":["Die Sprachbewegung wirkt in Debatten über Bildung und Identität in Südasien weiter, wo Sprachen mit Politik und Grenzen verflochten sind.","Die Lehre bleibt einfach: Wer der eigenen Sprache zuhört, hört sich selbst zu."]},{"heading":"Lange Wirkung","paragraphs":["Jahrzehnte sind vergangen, doch der Tag bewegt Menschen weiterhin, weil er von Menschen handelt und nicht von Sammlungen.","Wer heute über Bengali liest, liest über eine Gesellschaft, die ihrer Toten mit Worten gedenkt."]}],"en":[{"heading":"One state, one language","paragraphs":["After Partition in 1947, Pakistan's government promoted Urdu as the sole state language, though a majority of East Pakistan's population spoke Bengali.","The decision touched daily life, not just offices: the words people use for their children, the songs sung at school, the script of the newspaper."]},{"heading":"Students in the street","paragraphs":["Students and cultural organisations protested; on 21 February 1952 police fired on a demonstration in Dhaka, killing several students.","The deaths became a founding memory, passed from generation to generation rather than told as a passing news item.","How the day is observed varies by region and generation, depending on family and neighbourhood."]},{"heading":"From letter to nation","paragraphs":["Bengali was recognised as a state language in 1956, and the movement helped build the political consciousness that led to Bangladesh's independence in 1971.","The Shaheed Minar monument in Dhaka marks the site, and the day is observed with barefoot processions and songs.","The movement's history is commemorated differently in Bangladesh and Pakistan, and language politics in the region also involved other languages such as Urdu, Sindhi and Punjabi."]},{"heading":"Remembrance in daily detail","paragraphs":["At midnight on 21 February crowds walk barefoot to the Shaheed Minar holding flowers, and schoolchildren sing the song Amar Bhaier Rokte Rangano (My brother's blood dyed it red).","Language thus becomes a shared physical act, in which memory is tested with feet and voice."]},{"heading":"A language that carries people","paragraphs":["What happened in Dhaka is a reminder that language is not cultural decoration but a condition of dignity.","Because the day is now marked worldwide, it insists that every small language carries a whole human experience."]},{"heading":"Beyond the event","paragraphs":["The language movement still echoes in debates about education and identity in South Asia, where languages are tangled with politics and borders.","The lesson stays simple: when people listen to their language, they listen to themselves."]},{"heading":"A long aftermath","paragraphs":["Decades have passed, yet the day keeps its power to move people because it is about people, not collections.","To read about Bengali today is to read about a society that remembers its dead through words."]}]},"context":{"countries":["BD"],"region":"Bangladesh","continent":"asia","languages":["bn"],"period":"contemporary"},"tags":["cultural-change","Bangladesh"],"sources":[{"organization":"Wikipedia","title":{"ar":"Bengali language movement","de":"Bengali language movement","en":"Bengali language movement"},"url":"https://en.wikipedia.org/wiki/Bengali_language_movement","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Bengali language","de":"Bengali language","en":"Bengali language"},"url":"https://en.wikipedia.org/wiki/Bengali_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في منتصف ليل 21 فبراير، يسير الحشود حفاة الأقدام نحو الشهيد مينار حاملين الزهور، ويشدو أطفال المدارس بأغنية «عمار بيهاي روكته رانغانو» (أي: دم أخي لوّنها بالأحمر).","de":"Um Mitternacht des 21. Februar gehen Menschen barfuß zum Shaheed Minar, tragen Blumen, und Schulkinder singen „Amar Bhaier Rokte Rangano“ (Das Blut meines Bruders färbte es rot).","en":"At midnight on 21 February crowds walk barefoot to the Shaheed Minar holding flowers, and schoolchildren sing the song Amar Bhaier Rokte Rangano (My brother's blood dyed it red)."},"misunderstanding":{"ar":"يُفهم الحدث أحياناً كأنه خلاف لغوي تجريدي، لكنه في الواقع كان مطالب بحقوق يومية: التعليم والقضاء والإدارة بلغة الناس.","de":"Oft wird der Konflikt als abstrakter Sprachstreit gesehen, doch es ging um alltägliche Rechte: Bildung, Verwaltung und Recht in der Sprache der Menschen.","en":"The event is sometimes read as an abstract quarrel over language, but it was a claim to everyday rights: schooling, courts and administration in people's own words."},"comparison":{"ar":"يُروى هذا التاريخ في بنغلاديش كذكرى تأسيسية، بينما تُقدَّم في سياقات أخرى صيغ مختلفة، وقد شملت سياسات اللغة في المنطقة لغات أخرى كالأردية والسندية والبنجابية.","de":"In Bangladesch gilt der Tag als Gründungserinnerung, anderswo wird die Geschichte anders erzählt; die Sprachpolitik der Region betraf auch Urdu, Sindhi und Punjabi.","en":"In Bangladesh the history is a founding memory, while elsewhere it is told differently, and regional language politics also involved Urdu, Sindhi and Punjabi."}},{"id":"asa-046","version":2,"slug":"esala-perahera-a-procession-of-fire-elephants-and-caste-duties","contentType":"note","category":"traditions","title":{"ar":"موكب بيراهيرا: نار وفيلة وواجبات طبقات","de":"Esala Perahera: Feuer, Elefanten und Kastenpflichten","en":"Esala Perahera: fire, elephants and caste duties"},"deck":{"ar":"عشر ليالٍ في كاندي حيث يسير الفيلة المزينة والدوارون بالنار إلى جانب حاملي واجبات ورثوها عن أسلافهم.","de":"Zehn Nächte in Kandy, in denen geschmückte Elefanten, Tänzer und Feuerschwinger ihren ererbten Pflichten nachgehen.","en":"Ten nights in Kandy when caparisoned elephants, dancers and fire twirlers walk out to fulfil duties inherited from their ancestors."},"teaser":{"ar":"موكب بوذي سنوي في كاندي يجمع بين العبادة والعمل الوراثي والسياحة، ويطرح اليوم أسئلة علنية حول رعاية الفيلة.","de":"Eine jährliche buddhistische Prozession in Kandy zwischen Andacht, vererbter Arbeit und Tourismus, die heute öffentlich über das Wohl der Elefanten streitet.","en":"An annual Buddhist procession in Kandy that mixes devotion, inherited work and tourism, and now argues publicly about the welfare of its elephants."},"readingMinutes":1,"sections":{"ar":[{"heading":"ليالٍ من الطبول والنار","paragraphs":["يُقام موكب إيسالا بيراهيرا كل عام في كاندي بسريلانكا في يوليو أو أغسطس، ويستمر نحو عشر ليالٍ. يرافق الموكب صندوق يُعتقد أنه يحوي أثراً من بوذا، ويسير فيه رقاصون وطبالون ودوارون بالنار وفيلة مزينة.","يتولى تنظيم الموكب طبقات وراثية ومستأجرون معبديون لكل منهم واجبات محددة، ويقود الترتيبات دياوادانا نيلامي، وهو الحارس العلماني للمعبد.","الليلة الأخيرة، راندولي بيراهيرا، هي الأبهى، وتُختتم بمراسم قطع الماء عند نهر ماهاويلي. وتختلف تفاصيل الطقوس والأدوار بحسب المعبد والمنطقة، فموكب كاندي ليس الوحيد."]},{"heading":"بين العبادة والسياحة","paragraphs":["الحدث ديني ووجهة سياحية كبرى في آن واحد، وقد صار رعاية الفيلة نقاشاً عاماً. أدت مخاوف الرفق بالحيوان إلى قيود على مشاركة الفيلة.","ويتباين إقبال الناس عليه بين الأجيال: بعض الشباب يشارك حباً بالطبل والرقص، وآخرون يتابعون النقاش حول الحيوان.","يبقى الموكب عملاً جماعياً تتقاسمه أسر كثيرة، لا مجرد عرض يُشاهد من الرصيف."]}],"de":[{"heading":"Nächte aus Trommeln und Feuer","paragraphs":["Die Esala Perahera findet jedes Jahr in Kandy in Sri Lanka im Juli oder August statt und dauert etwa zehn Nächte. Sie geleitet einen Schrein, von dem man glaubt, er enthalte eine Reliquie des Buddha; Tänzer, Trommler, Feuerschwinger und geschmückte Elefanten ziehen mit.","Organisiert wird der Zug von ererbten Kasten und Tempelpächtern mit je eigenen Pflichten; der diyawadana nilame, der weltliche Hüter des Tempels, leitet die Vorbereitungen.","Die letzte Nacht, die Randoli Perahera, ist die prächtigste, und eine Wasserzeremonie am Mahaweli-Fluss beendet das Fest. Ritualdetails und Kastenrollen unterscheiden sich je nach Tempel und Region, denn Kandy ist nicht die einzige Perahera."]},{"heading":"Zwischen Andacht und Tourismus","paragraphs":["Das Ereignis ist religiös und zugleich eine große Touristenattraktion; das Wohl der Elefanten ist zu einer öffentlichen Debatte geworden. Tierschutzbedenken führten zu Einschränkungen bei der Teilnahme der Tiere.","Die Beteiligung der Menschen unterscheidet sich auch zwischen den Generationen: Manche Jüngere kommen wegen Trommel und Tanz, andere verfolgen die Diskussion um die Tiere.","Die Prozession bleibt ein gemeinsames Werk vieler Familien, keine bloße Vorführung für Zuschauer am Straßenrand."]}],"en":[{"heading":"Nights of drums and fire","paragraphs":["The Esala Perahera is held every year in Kandy, Sri Lanka, in July or August and lasts about ten nights. It escorts a casket believed to hold a relic of the Buddha, with dancers, drummers, fire twirlers and decorated elephants.","Hereditary castes and temple tenants organise the procession, each with specific duties; the diyawadana nilame, the temple's lay custodian, leads the arrangements.","The final Randoli Perahera is the grandest, and a water-cutting ceremony at the Mahaweli River ends the festival. Ritual details and caste roles vary by temple and region, and Kandy is not the only perahera."]},{"heading":"Between devotion and tourism","paragraphs":["The event is both religious and a major tourist attraction, and elephant welfare has become a public debate. Concerns about animal welfare have led to restrictions on elephant participation.","People's involvement also varies by generation: some younger participants come for the drums and dancing, while others follow the discussion about the animals.","The procession remains a shared effort across many families, not merely a show watched from the roadside."]}]},"context":{"countries":["LK"],"region":"Kandy","continent":"asia","languages":["si"],"period":"contemporary"},"tags":["traditions","Kandy"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kandy Esala Perahera","de":"Kandy Esala Perahera","en":"Kandy Esala Perahera"},"url":"https://en.wikipedia.org/wiki/Kandy_Esala_Perahera","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kandy","de":"Kandy","en":"Kandy"},"url":"https://en.wikipedia.org/wiki/Kandy","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الليلة الأخيرة تسير الفيلة المزينة تحت الأضواء الكهربائية، ويقفز رقاصو كاندي على وقع الطبول، ويدور الدوارون بقشور جوز الهند المشتعلة على طول الطريق.","de":"In der letzten Nacht ziehen geschmückte Elefanten unter elektrischem Licht, Kandyan-Tänzer springen im Trommelrhythmus, und Feuerschwinger lassen brennende Kokosnussschalen über den Weg kreisen.","en":"On the last night caparisoned elephants walk under electric lights, Kandyan dancers leap to drumbeats, and fire twirlers spin flaming coconut shells along the route."},"misunderstanding":{"ar":"يظن بعض الزوار أن الموكب عرض سياحي صرف، لكنه في الأساس عبادة وواجب وراثي يلتزم به أهل المعبد.","de":"Manche Besucher halten die Perahera für eine reine Touristen-Show, doch sie ist vor allem Andacht und ererbte Pflicht der Tempelgemeinschaft.","en":"Some visitors assume the perahera is purely a tourist show, but it is first of all devotion and inherited duty carried out by the temple community."},"comparison":{"ar":"يشبه الموكب مواكب دينية أخرى يتقاسم فيها السكان أدواراً موروثة، لكن ارتباطه بالفيلة يجعله اليوم موضوع نقاش بيئي لا نجده في كل مكان.","de":"Sie ähnelt anderen religiösen Umzügen, bei denen Einheimische ererbte Rollen teilen, doch die Beteiligung der Elefanten macht sie heute zum Thema einer Umweltdebatte.","en":"It resembles other religious processions where local people share inherited roles, yet its use of elephants makes it today the subject of an environmental debate."}},{"id":"asa-047","version":2,"slug":"chhaupadi-the-menstrual-exile-that-law-has-not-ended","contentType":"note","category":"social-behaviour","title":{"ar":"الحَيض في المنفى: قانون لا يكفي","de":"Menstruationsverbannung trotz Gesetz","en":"Chhaupadi: exile the law has not ended"},"deck":{"ar":"في غرب نيبال تُعزل الفتيات والنساء الحائضات في حظائر، رغم حظر المحكمة العليا وتجريم القانون عام 2017.","de":"In Teilen Westnepals werden menstruierende Frauen und Mädchen in Hütten oder Ställen isoliert, obwohl Gerichte und Gesetze die Praxis verbieten.","en":"In parts of western Nepal, menstruating women and girls are isolated in sheds or cattle stalls, despite a court ban and a 2017 criminal law."},"teaser":{"ar":"عادة محلية في غرب نيبال تُبعد النساء الحائضات عن البيت والمطبخ، ويواجه القانون صعوبة في الوصول إلى القرى النائية.","de":"Eine lokale Sitte im Westen Nepals trennt Frauen während der Periode vom Haus und der Küche. Das Gesetz erreicht abgelegene Distrikte nur schwer.","en":"A local custom in western Nepal bars menstruating women from home and kitchen. The law exists, but remote districts enforce it unevenly."},"readingMinutes":1,"sections":{"ar":[{"heading":"حياة خارج البيت كل شهر","paragraphs":["في أجزاء من غرب نيبال، تُخرَج الفتيات والنساء أثناء الحيض من البيت والمطبخ وتُوضع في shed أو حظيرة ماشية. العادة متجذرة في أفكار محلية عن الطهارة الشعائرية، لكنها تحمل مخاطر جدية: البرد والدخان ولدغات الأفاعي والعنف الجنسي، وقد تسببت في وفيات.","ليست العادة شاملة في نيبال؛ فهي أقوى في أقصى الغرب وبعض مقاطعات الغرب الأوسط، وتختلف شدتها بين الأسر والأجيال.","تتكرر القصة نفسها: تلميذة تُرسل إلى shed طيني صغير أياماً، فتغيب عن الصفوف، ثم يعود إليها معلمها بعد حديث مع والديها."]},{"heading":"قانون على الورق","paragraphs":["حظرت المحكمة العليا النيبالية هذه الممارسة عام 2005، وجرّم قانون صادر عام 2017 إجبار أحد على ممارستها بغرامات وأحكام سجن. لكن التنفيذ يبقى ضعيفاً في المقاطعات النائية، ونتائج حملات التوعية والشرطة والحكومات المحلية متفاوتة.","يصف كثير من التقارير العادة وكأنها منتشرة في نيبال كلها، بينما هي عادة محلية يعارضها نيباليون كثيرون، ويصعب تقدير انتشارها بدقة.","الفرق بين نص القانون وتطبيقه يظهر في القرى، حيث تتداخل سلطة الأسرة والتقاليد مع عمل الشرطة والمجالس المحلية."]}],"de":[{"heading":"Jeden Monat draußen leben","paragraphs":["In Teilen Westnepals werden menstruierende Frauen und Mädchen in einer Hütte oder einem Viehstall isoliert und vom Haus und der Küche ausgeschlossen. Die Sitte wurzelt in lokalen Vorstellungen von ritueller Reinheit, birgt aber ernste Risiken: Kälte, Rauch, Schlangenbisse und sexuelle Gewalt haben Todesfälle verursacht.","Die Praxis ist in Nepal nicht flächendeckend verbreitet; am stärksten ist sie im äußersten Westen und in einigen Distrikten des Mittleren Westens, und sie variiert je nach Familie und Generation.","Ein Schulmädchen in einem Bergdistrikt wird während ihrer Periode in eine kleine Lehmhütte geschickt, fehlt tagelang im Unterricht, und ihre Lehrerin spricht anschließend mit den Eltern."]},{"heading":"Ein Gesetz auf dem Papier","paragraphs":["Nepals Oberster Gerichtshof verbot die Praxis 2005, und ein Gesetz von 2017 stellte es unter Strafe, jemanden zur Einhaltung zu zwingen, mit Geld- und Haftstrafen. Die Durchsetzung bleibt in abgelegenen Distrikten schwach, und Aufklärungskampagnen, Polizei und lokale Regierungen erzielen ungleiche Ergebnisse.","Viele Berichte verallgemeinern die Sitte auf ganz Nepal; tatsächlich ist sie lokal begrenzt, wird von vielen Nepalesen bekämpft, und genaue Verbreitungszahlen sind schwer zu ermitteln.","Die Lücke zwischen Gesetzestext und Alltag zeigt sich in den Dörfern, wo familiäre Autorität und Tradition auf Polizei und lokale Räte treffen."]}],"en":[{"heading":"Living outside the house each month","paragraphs":["In parts of western Nepal, menstruating women and girls are isolated in a shed or cattle stall, barred from the home and kitchen. The custom is rooted in local beliefs about ritual purity, but it carries serious risks: cold, smoke, snake bites and sexual violence have caused deaths.","The practice is not universal in Nepal; it is strongest in the Far West and some Mid-Western districts, and its severity varies between families and generations.","A schoolgirl in a hill district is sent to a small mud shed during her period, misses classes for days, and returns to find her teacher has spoken to her parents."]},{"heading":"A law on paper","paragraphs":["Nepal's Supreme Court banned the practice in 2005, and a 2017 law criminalised forcing someone to observe it, with fines and jail terms. Enforcement remains weak in remote districts, and awareness campaigns, police and local governments have had uneven results.","Reporting often generalises the practice to all of Nepal; it is a localised custom contested by many Nepalis, and precise prevalence estimates are difficult.","The gap between legal text and daily life shows in the villages, where family authority and tradition meet police and local councils."]}]},"context":{"countries":["NP"],"region":"Western Nepal","continent":"asia","languages":["ne"],"period":"contemporary"},"tags":["social-behaviour","Western Nepal"],"sources":[{"organization":"Wikipedia","title":{"ar":"Chhaupadi","de":"Chhaupadi","en":"Chhaupadi"},"url":"https://en.wikipedia.org/wiki/Chhaupadi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture and menstruation","de":"Culture and menstruation","en":"Culture and menstruation"},"url":"https://en.wikipedia.org/wiki/Culture_and_menstruation","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تلميذة في مقاطعة جبلية تُرسل إلى shed طيني صغير أثناء حيضها، فتغيب عن الدروس أياماً، ثم يعود إليها معلمها بعد أن تحدث مع والديها.","de":"Ein Schulmädchen in einem Bergdistrikt wird während ihrer Periode in eine kleine Lehmhütte geschickt, verpasst mehrere Schultage, und ihre Lehrerin sucht danach das Gespräch mit den Eltern.","en":"A schoolgirl in a hill district is sent to a small mud shed during her period, misses classes for days, and returns to find her teacher has spoken to her parents."},"misunderstanding":{"ar":"كثيراً ما تُعمَّم العادة على نيبال بأكملها؛ لكنها عادة محلية يعارضها نيباليون كثيرون، ويصعب الحصول على تقديرات دقيقة لانتشارها.","de":"Berichte verallgemeinern die Praxis oft auf ganz Nepal; sie ist jedoch eine lokale Sitte, die viele Nepalesen ablehnen, und genaue Verbreitungszahlen sind schwer zu ermitteln.","en":"Reporting often generalises the practice to all of Nepal; it is a localised custom contested by many Nepalis, and precise prevalence estimates are difficult."},"comparison":{"ar":"حيث يُطبَّق القانون بجدية، تنخفض حالات الإبعاد؛ وحيث تضعف المؤسسات، تبقى العادة أقوى من النص.","de":"Wo das Gesetz ernst genommen wird, gehen die Fälle von Isolation zurück; wo Institutionen schwach sind, bleibt die Sitte stärker als der Gesetzestext.","en":"Where the law is taken seriously, cases of isolation decline; where institutions are weak, the custom stays stronger than the statute."}},{"id":"asa-048","version":2,"slug":"gross-national-happiness-a-national-policy-that-measures-the-mind","contentType":"note","category":"cultural-change","title":{"ar":"السعادة الوطنية الكلية: سياسة تقيس العقل","de":"Bruttonationalglück: eine Politik, die den Geist misst","en":"Gross National Happiness: a policy that measures the mind"},"deck":{"ar":"منذ سبعينيات القرن الماضي، تضع بوتان السعادة في صميم سياستها التنموية، ليس مجرد شعار بل إطار عمل يوجه القرارات.","de":"Seit den 1970er Jahren setzt Bhutan Wohlbefinden an die Stelle von GDP und hat daraus ein politisches Rahmenwerk gemacht.","en":"Since the 1970s, Bhutan has put well-being at the heart of its development, turning happiness into a governing framework."},"teaser":{"ar":"في بوتان، تُقاس التنمية بالسعادة لا بالناتج المحلي، فكيف يعيش الناس تحت هذا الإطار؟","de":"In Bhutan misst man Entwicklung am Glück, nicht am Bruttoinlandsprodukt. Wie lebt es sich unter diesem Rahmen?","en":"In Bhutan, development is measured by happiness, not GDP. What does it mean to live under this national framework?"},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف يعيش الناس تحت سياسة السعادة","paragraphs":["في بوتان، لا يُنظر إلى السعادة كشعور عابر، بل كهدف وطني. منذ أن صاغ الملك جيغمي سينغي وانغتشوك فكرة السعادة الوطنية الكلية في السبعينيات، أصبحت التنمية تُقاس بالرفاهية لا بالناتج المحلي الإجمالي. ويشعر الناس أن قرارات الحكومة، من حماية الغابات إلى قيود التبغ، تُبرر بهذا الإطار.","دستور 2008 يجعل الدولة مسؤولة عن تعزيز السعادة الوطنية الكلية، ولجنة خاصة تفحص السياسات وفق تسعة مجالات تشمل الصحة والتعليم والثقافة والبيئة. وتُجرى استقصاءات وطنية دورية لتصنيف المواطنين إلى سعداء بعمق، وسعداء بكثافة، وغير سعداء. هذا التصنيف يثير نقاشات حول كيف يعيش الناس فعلاً."]},{"heading":"بين التطبيق والنظرة النقدية","paragraphs":["غالبًا ما تُشرح سياسات بوتان، مثل نسبة الغطاء الحرجي ورسوم السياحة، من خلال السعادة الوطنية الكلية. لكن بعض النقاد يرون أن الإطار أداة تسويقية أيضًا، وأن تطبيقه يختلف باختلاف المناطق والأجيال.","على المستوى الدولي، انتشرت الفكرة وتبنت الأمم المتحدة قرارًا حول السعادة والرفاهية في 2011. ومع ذلك، يبقى السؤال: هل يعكس هذا الإطار مشاعر كل البوتانيين، أم أنه سياسة دولة تحتمل الجدل؟"]}],"de":[{"heading":"Wie Menschen unter der Glückspolitik leben","paragraphs":["In Bhutan gilt Glück nicht als flüchtiges Gefühl, sondern als nationales Ziel. Seit König Jigme Singye Wangchuck in den 1970er Jahren die Idee des Bruttonationalglücks formulierte, wird Entwicklung am Wohlbefinden gemessen, nicht am BIP. Viele Bürger sehen darin die Rechtfertigung für Politik, von Waldschutz bis Tabakbeschränkungen.","Die Verfassung von 2008 verpflichtet den Staat, GNH zu fördern, und eine Kommission prüft Politiken anhand von neun Bereichen wie Gesundheit, Bildung, Kultur und Ökologie. Regelmäßige Umfragen stufen Bürger als tief glücklich, umfassend glücklich oder unglücklich ein. Diese Einordnung wird diskutiert."]},{"heading":"Zwischen Anwendung und Kritik","paragraphs":["Bhutans Politik, etwa Waldbedeckung und Tourismusgebühren, wird oft mit GNH erklärt. Kritiker sehen darin jedoch auch ein Marketinginstrument, und die Anwendung variiert je nach Region und Generation.","International wurde die Idee populär, 2011 verabschiedete die UN eine Resolution zu Glück und Wohlbefinden. Doch die Frage bleibt, ob der Rahmen die Gefühle aller Bhutaner widerspiegelt oder eine umstrittene Staatspolitik ist."]}],"en":[{"heading":"How people live under the happiness policy","paragraphs":["In Bhutan, happiness is not seen as a fleeting feeling but as a national goal. Since King Jigme Singye Wangchuck articulated Gross National Happiness in the 1970s, development has been measured by well-being, not GDP. People often cite it to explain policies from forest cover to tobacco restrictions.","The 2008 constitution makes the state responsible for promoting GNH, and a commission screens policies against nine domains including health, education, culture and ecology. Periodic surveys classify citizens as deeply happy, extensively happy or unhappy. This classification sparks debate about how people actually live."]},{"heading":"Between application and critique","paragraphs":["Bhutan's policies, such as forest cover and tourism fees, are often explained through GNH. But critics say the framework is also a branding tool, and its application varies across regions and generations.","Internationally, the idea has spread, with the UN adopting a resolution on happiness and well-being in 2011. Still, the question remains whether the framework reflects every Bhutanese person's feelings or is a debated state policy."]}]},"context":{"countries":["BT"],"region":"Bhutan","continent":"asia","languages":["dz"],"period":"contemporary"},"tags":["cultural-change","Bhutan"],"sources":[{"organization":"Wikipedia","title":{"ar":"Gross National Happiness","de":"Gross National Happiness","en":"Gross National Happiness"},"url":"https://en.wikipedia.org/wiki/Gross_National_Happiness","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Bhutan","de":"Bhutan","en":"Bhutan"},"url":"https://en.wikipedia.org/wiki/Bhutan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"اقتراح بناء طريق أو مدرسة في تيمفو يجب أن يمر بفحص للسعادة الوطنية الكلية يسأل عن تأثيره على حيوية المجتمع والمرونة البيئية، وليس فقط تكلفته.","de":"Ein Straßen- oder Schulprojekt in Thimphu muss ein GNH-Screening durchlaufen, das fragt, wie es Gemeinschaftsleben und ökologische Resilienz beeinflusst, nicht nur die Kosten.","en":"A road or school proposal in Thimphu must pass a GNH screening that asks how it affects community vitality and ecological resilience, not only its cost."},"misunderstanding":{"ar":"يُفهم أحيانًا أن السعادة الوطنية الكلية تعني أن كل البوتانيين سعداء، لكنها إطار حكومي وليست وصفًا لحالة الجميع.","de":"Manchmal wird GNH so verstanden, als seien alle Bhutaner glücklich, doch es ist ein staatlicher Rahmen, keine Beschreibung für jeden Einzelnen.","en":"GNH is sometimes misunderstood to mean all Bhutanese are happy, but it is a state framework, not a description of everyone's feelings."},"comparison":{"ar":"بينما تقيس معظم الدول نجاحها بالنمو الاقتصادي، تضع بوتان السعادة والرفاهية في المركز، وإن كان التطبيق يثير جدلاً.","de":"Während die meisten Länder Erfolg am Wirtschaftswachstum messen, stellt Bhutan Glück und Wohlbefinden in den Mittelpunkt, auch wenn die Umsetzung umstritten ist.","en":"While most countries measure success by economic growth, Bhutan places happiness and well-being at the center, though its implementation is debated."}},{"id":"asa-049","version":2,"slug":"dhivehi-and-thaana-a-script-written-right-to-left","contentType":"language","category":"languages","title":{"ar":"Dhivehi وThaana: لغة تكتب من اليمين إلى اليسار","de":"Dhivehi und Thaana: eine Schrift von rechts nach links","en":"Dhivehi and Thaana: a script written right to left"},"deck":{"ar":"في المالديف، يكتب الناس Dhivehi بحروف Thaana من اليمين إلى اليسار، ويتنقلون يوميًا بين لغات المدرسة والبيت والعمل.","de":"Auf den Malediven schreiben Menschen Dhivehi in der Thaana-Schrift von rechts nach links und wechseln täglich zwischen Schule, Zuhause und Arbeit.","en":"In the Maldives, people write Dhivehi in the Thaana script from right to left, switching daily between school, home and island work."},"teaser":{"ar":"Dhivehi لغة المالديف الهندية-الآرية، تُكتب بـThaana من اليمين إلى اليسار، وتخلط حروفًا عربية وهندية.","de":"Dhivehi ist die indoarische Sprache der Malediven, in Thaana von rechts nach links geschrieben, mit arabischen und indischen Buchstabenformen.","en":"Dhivehi is the Indo-Aryan language of the Maldives, written in Thaana from right to left, mixing Arabic-derived and Indian-derived letter forms."},"readingMinutes":1,"sections":{"ar":[{"heading":"حروف تمزج العربية والهندية","paragraphs":["Dhivehi هي اللغة الهندية-الآرية في المالديف، وتُكتب بـThaana، وهو خط يسير من اليمين إلى اليسار ويمزج أشكال حروف مشتقة من العربية وأخرى من الهند.","تطور Thaana في القرن السادس عشر بديلًا عن خط أقدم يُسمى Dhives Akuru، وحروفه مسماة على أسماء الأرقام العربية.","تختلف لهجات Dhivehi بين الجزر المرجانية، وأشكال أقصى الجنوب متميزة بوضوح عن معيار Male."]},{"heading":"تبديل يومي بين اللغات","paragraphs":["تحتوي اللغة على مفردات عربية كثيرة للدين والإدارة، وكلمات مستعارة من البرتغالية والإنجليزية للتجارة والتقنية.","الإنجليزية هي لغة التعليم الثانوي والعالي، لذا يبدّل كثير من المالديفيين لغاتهم يوميًا بين المدرسة والبيت والعمل في الجزيرة.","يختلف هذا التبديل بين الأجيال والمناطق، فالشباب في Male قد ينتقلون إلى الإنجليزية أسرع من كبار السن في الجزر النائية."]}],"de":[{"heading":"Buchstaben aus arabischen und indischen Formen","paragraphs":["Dhivehi ist die indoarische Sprache der Malediven und wird in Thaana geschrieben, einer Schrift, die von rechts nach links läuft und arabisch- sowie indischstämmige Buchstabenformen mischt.","Thaana entstand im 16. Jahrhundert und ersetzte eine ältere Schrift namens Dhives Akuru; seine Buchstaben sind nach arabischen Ziffern benannt.","Die Dhivehi-Dialekte unterscheiden sich zwischen den Atollen, wobei die südlichsten Formen deutlich vom Standard von Male abweichen."]},{"heading":"Täglicher Sprachwechsel","paragraphs":["Die Sprache hat viel arabisches Vokabular für Religion und Verwaltung sowie portugiesische und englische Lehnwörter für Handel und Technik.","Englisch ist die Unterrichtssprache der Sekundar- und Hochschulbildung, daher wechseln viele Malediver täglich zwischen Schule, Zuhause und Inselarbeit.","Dieser Wechsel variiert regional und zwischen Generationen: Junge Menschen in Male greifen oft schneller zum Englischen als Ältere auf abgelegenen Inseln."]}],"en":[{"heading":"Letters mixing Arabic and Indian forms","paragraphs":["Dhivehi is the Indo-Aryan language of the Maldives, written in Thaana, a script that runs right to left and mixes Arabic-derived and Indian-derived letter forms.","Thaana developed in the sixteenth century, replacing an older script called Dhives Akuru, and its letters are named after Arabic numerals.","Dhivehi dialects differ across atolls, with the southernmost forms markedly distinct from the Male standard."]},{"heading":"Switching languages every day","paragraphs":["The language has heavy Arabic vocabulary for religion and administration, and Portuguese and English loanwords for trade and technology.","English is the medium of secondary and higher education, so many Maldivians switch languages daily between school, home and island work.","This switching varies by region and generation, with younger people in Male often reaching for English faster than older speakers on remote islands."]}]},"context":{"countries":["MV"],"region":"Maldives","continent":"asia","languages":["dv"],"period":"contemporary"},"tags":["languages","Maldives"],"sources":[{"organization":"Wikipedia","title":{"ar":"Maldivian language","de":"Maldivian language","en":"Maldivian language"},"url":"https://en.wikipedia.org/wiki/Maldivian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Maldivian writing systems","de":"Maldivian writing systems","en":"Maldivian writing systems"},"url":"https://en.wikipedia.org/wiki/Maldivian_writing_systems","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يكتب مدرّس ملاحظة على السبورة بـThaana من اليمين إلى اليسار، ثم ينتقل إلى الإنجليزية لدرس العلوم بينما ينسخ الطلاب الاثنين.","de":"Eine Lehrerin schreibt einen Hinweis in Thaana von rechts nach links an die Tafel und wechselt für die Naturwissenschaftsstunde ins Englische, während die Schüler beides abschreiben.","en":"A teacher writes a note on the board in Thaana, reading right to left, then switches to English for the science lesson while students copy both."},"misunderstanding":{"ar":"قد يظن المرء أن كتابة اليمين إلى اليسار تعني لغة عربية، لكن Thaana خط مستقل للغة Dhivehi وله حروف خاصة.","de":"Man könnte annehmen, eine Schrift von rechts nach links bedeute Arabisch, doch Thaana ist eine eigene Schrift für Dhivehi mit eigenen Buchstaben.","en":"One might assume a right-to-left script means Arabic, but Thaana is a distinct script for Dhivehi with its own letters."},"comparison":{"ar":"كما يتنقل متحدثو لغات أخرى بين لغة البيت ولغة المدرسة، يتنقل المالديفيون بين Dhivehi والإنجليزية في يومهم.","de":"Wie andere zwischen Familiensprache und Schulsprache wechseln, pendeln Malediver in ihrem Alltag zwischen Dhivehi und Englisch.","en":"Just as other speakers move between home and school languages, Maldivians move between Dhivehi and English in their daily lives."},"expression":{"original":"ޝުކުރިއްޔާ","language":"ދިވެހި","gloss":{"ar":"شكرًا","de":"danke","en":"thank you"},"usage":{"ar":"تُقال عند الشكر في الحياة اليومية.","de":"Wird im Alltag zum Danken gesagt.","en":"Said when thanking someone in everyday life."},"transliteration":"shukuriyyā"}},{"id":"asa-051","version":2,"slug":"sanuk-why-thai-social-life-is-organised-around-having-fun","contentType":"note","category":"social-behaviour","title":{"ar":"سانوك: لماذا تدور الحياة الاجتماعية التايلاندية حول المرح","de":"Sanuk: Warum das thailändische Sozialleben auf Spaß baut","en":"Sanuk: why Thai social life is organised around fun"},"deck":{"ar":"كلمة واحدة تحدد كيف يتوقع التايلانديون أن تُنجز المهام وتُدار العلاقات: المرح ليس ترفًا بل شرطًا اجتماعيًا.","de":"Ein einziges Wort prägt, wie Thailänder Aufgaben erledigen und Beziehungen gestalten: Spaß ist kein Luxus, sondern eine soziale Bedingung.","en":"One word shapes how Thai people get tasks done and manage relationships: fun is not a luxury but a social condition."},"teaser":{"ar":"من العمل إلى الأخبار السيئة، يبحث التايلانديون عن المتعة داخل الفعل نفسه، فتصبح البهجة وسيلة للتعامل لا هدفًا منفصلًا.","de":"Vom Arbeitsalltag bis zur schlechten Nachricht suchen Thailänder das Vergnügen in der Sache selbst – Heiterkeit wird zum Werkzeug, nicht zum Ziel.","en":"From the workplace to bad news, Thai people look for enjoyment inside the activity itself, so cheerfulness becomes a tool rather than a separate goal."},"readingMinutes":1,"sections":{"ar":[{"heading":"المرح كطريقة للعمل","paragraphs":["تعني كلمة سانوك المتعة أو الاستمتاع، وتُستخدم لوصف العمل والأكل والسفر وحتى المهام الصعبة التي تُؤدى بطريقة ممتعة. وتنظم الشركات حفلات وأيامًا رياضية ورحلات تحت هذا العنوان، ويستند الإعلان التايلاندي كثيرًا إلى الفكاهة.","القيمة تصوغ التوقعات الاجتماعية: التجمع الجاد جدًا قد يُحكم عليه بالفشل، وتُستخدم الفكاهة لتلطيف الأخبار السيئة والنزاعات. ويختلف ذلك بين الأجيال والمناطق، فالشباب في المدن قد يقرأون المرح كاختيار شخصي أكثر من كونه واجبًا جماعيًا."]},{"heading":"بين المرح والضغط","paragraphs":["يتقاطع سانوك مع فكرة ماي بن راي أي لا يهم، وهي استجابة هادئة للانتكاسات يقرأها الغرباء أحيانًا كلامبالاة. لكن المفهوم مثالي أكثر مما يبدو: ساعات طويلة وزحام والتزامات عائلية تعني أن ليس كل يوم مرحًا، ويرى نقاد أن ضغط البهجة الدائمة قد يكبت الشكوى."]}],"de":[{"heading":"Spaß als Arbeitsweise","paragraphs":["Sanuk bedeutet Freude oder Vergnügen, und das Wort beschreibt Arbeit, Essen, Reisen und selbst schwierige Aufgaben, die auf angenehme Weise erledigt werden. Firmen veranstalten unter diesem Etikett Partys, Sporttage und Ausflüge, und die thailändische Werbung setzt stark auf Humor.","Der Wert prägt soziale Erwartungen: Ein allzu ernstes Treffen gilt leicht als gescheitert, und Humor mildert schlechte Nachrichten und Konflikte. Regional und zwischen Generationen variiert das, denn jüngere Städter verstehen Sanuk eher als persönliche Wahl denn als Gruppennorm."]},{"heading":"Zwischen Freude und Druck","paragraphs":["Sanuk überschneidet sich mit mai pen rai, dem gelassenen „macht nichts“ bei Rückschlägen, das Außenstehende manchmal als Gleichgültigkeit lesen. Doch das Konzept ist eine Idealisierung: lange Arbeitszeiten, Verkehr und Familienpflichten sorgen dafür, dass nicht jeder Tag lustig ist, und Kritiker sagen, der Zwang zur Heiterkeit könne Beschwerden ersticken."]}],"en":[{"heading":"Fun as a way of working","paragraphs":["Sanuk means fun or enjoyment, and the word describes work, eating, travel and even difficult tasks done in a pleasurable way. Workplaces stage parties, sports days and offsite trips under the sanuk label, and Thai advertising leans heavily on humour.","The value shapes social expectations: a gathering that is too serious may be judged a failure, and humour is used to soften bad news and conflict. This varies by region and generation, with younger urban Thais often treating sanuk as a personal choice rather than a group duty."]},{"heading":"Between cheerfulness and pressure","paragraphs":["Sanuk overlaps with mai pen rai, a relaxed response to setbacks that outsiders sometimes read as indifference. But the concept is an idealisation: long hours, traffic and family obligations mean not every day is fun, and critics say the pressure to be cheerful can suppress complaint."]}]},"context":{"countries":["TH"],"region":"Thailand","continent":"asia","languages":["th"],"period":"contemporary"},"tags":["social-behaviour","Thailand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sanuk (Thai culture)","de":"Sanuk (Thai culture)","en":"Sanuk (Thai culture)"},"url":"https://en.wikipedia.org/wiki/Sanuk_(Thai_culture)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Thailand","de":"Culture of Thailand","en":"Culture of Thailand"},"url":"https://en.wikipedia.org/wiki/Culture_of_Thailand","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"فريق ينهي جردًا مرهقًا يطلب الطعام ويشغّل الموسيقى ويحول الساعة الأخيرة إلى لعبة، لأن مزاج الجماعة يهم بقدر الموعد النهائي.","de":"Ein Team beendet eine erschöpfende Inventur trotzdem mit Essen, Musik und einem Spiel in der letzten Stunde, weil die Stimmung der Gruppe ebenso zählt wie die Frist.","en":"A team finishing an exhausting inventory still orders food, plays music and turns the last hour into a game, because the group's mood matters as much as the deadline."},"misunderstanding":{"ar":"كثير من الزوار يظنون أن سانوك دعوة دائمة للاحتفال، لكنه في جوهره أسلوب لتخفيف ثقل الواجبات لا هروب منها.","de":"Viele Besucher halten Sanuk für eine Daueraufforderung zum Feiern, doch es ist vor allem eine Methode, Pflichten zu erleichtern statt ihnen auszuweichen.","en":"Many visitors assume sanuk is a constant invitation to celebrate, but it is mainly a way of lightening obligations rather than escaping them."},"comparison":{"ar":"يشبه سانوك إلى حد ما روح الدعابة في ثقافات أخرى، لكنه هنا معيار لتقييم التفاعل الاجتماعي نفسه، لا مجرد لمسة إضافية.","de":"Sanuk ähnelt Humor in anderen Kulturen, ist hier aber ein Maßstab für die soziale Interaktion selbst und nicht bloß eine Zugabe.","en":"Sanuk resembles humour in other cultures, yet here it is a standard for judging social interaction itself, not an added extra."}},{"id":"asa-052","version":2,"slug":"songkran-the-new-year-celebrated-by-throwing-water","contentType":"scene","category":"traditions","title":{"ar":"سونغكران: رأس السنة بالماء","de":"Songkran: Neujahr mit Wasser","en":"Songkran: New Year by Water"},"deck":{"ar":"عيد رأس السنة التايلاندي حيث يخلط الناس بين البركة والمرح في الشوارع.","de":"Thailändisches Neujahrsfest, bei dem Segen und Straßenwasserfights aufeinandertreffen.","en":"Thailand's New Year blends blessing and street play with water."},"teaser":{"ar":"من 13 إلى 15 أبريل، تحتفل تايلاند برأس السنة بسكب الماء على التماثيل والأيدي كبركة، ثم تتحول الشوارع إلى معارك مائية.","de":"Vom 13. bis 15. April feiert Thailand Neujahr, indem Wasser als Segen über Buddha-Statuen und Hände gegossen wird – und später auf der Straße.","en":"From 13 to 15 April, Thais pour scented water over Buddha images and elders' hands as a blessing—then cities erupt in water fights."},"readingMinutes":1,"sections":{"ar":[{"heading":"بركة الماء وتكريم الكبار","paragraphs":["في صباح اليوم الأول، تجتمع العائلات لسكب الماء المعطر على تماثيل بوذا وأيدي كبار السن كتعبير عن الاحترام والبركة. الماء يرمز إلى غسل السنة الماضية، وسكبه على الأيدي ليس لعباً بل تكريم.","كما أنه عطلة عائلية: كثير من العمال يعودون إلى محافظاتهم، وتقيم المعابد احتفالات خاصة وبناء ستوبا من الرمل."]},{"heading":"من الطقوس إلى الشوارع","paragraphs":["توسعت طقوس الماء إلى معارك مائية عامة في مدن مثل بانكوك وتشيانغ ماي، وتجذب حشوداً من السكان والسياح. هذا الشكل الصاخب ليس سوى جزء من العيد، وتختلف الممارسات حسب المنطقة والدين؛ بعض التايلانديين يقضون اليوم بهدوء في المنزل، وقد واجهت معارك الماء قيوداً محلية.","خلال فترة السفر، تشكل سلامة الطرق قلقاً متكرراً، وتشن السلطات حملات سنوية ضد القيادة تحت تأثير الكحول."]}],"de":[{"heading":"Wassersegen und Respekt vor Älteren","paragraphs":["Am ersten Morgen versammeln sich Familien, um duftendes Wasser über Buddha-Statuen und die Hände der Ältesten zu gießen – als Segen und Zeichen des Respekts. Wasser symbolisiert das Abwaschen des vergangenen Jahres; das Übergießen der Hände ist keine Spielerei.","Das Fest ist auch ein Familienurlaub: Viele Arbeiter kehren in ihre Heimatprovinzen zurück, und Tempel veranstalten besondere Zeremonien und bauen Sand-Stupas."]},{"heading":"Vom Ritual zum Straßenfest","paragraphs":["Das Wasserritual hat sich in Städten wie Bangkok und Chiang Mai zu öffentlichen Wasserschlachten ausgeweitet, die große Menschenmengen anziehen. Die ausgelassene Straßenversion ist nur ein Teil des Festes, und die Bräuche unterscheiden sich je nach Region und Religion; manche Thailänder bleiben ruhig zu Hause, und Wasserschlachten wurden örtlich eingeschränkt.","Während der Reisezeit ist Verkehrssicherheit ein wiederkehrendes Thema, und die Behörden führen jährlich Kampagnen gegen Alkohol am Steuer durch."]}],"en":[{"heading":"Water Blessing and Respect for Elders","paragraphs":["On the first morning, families gather to pour scented water over Buddha images and the hands of elders as a blessing. Water symbolises washing away the past year, and pouring it over elders is an act of respect, not play.","The festival is also a family holiday: many workers return to their home provinces, and temples hold special ceremonies and sand-stupa building."]},{"heading":"From Ritual to Street Fest","paragraphs":["The water ritual has expanded into public street water fights in cities such as Bangkok and Chiang Mai, drawing huge crowds of locals and tourists. The boisterous street version is only part of the festival, and observances differ by region and religion; some Thais keep the day quietly at home, and water fights have faced local restrictions.","During the travel period, road safety is a recurring concern, and authorities campaign against drink-driving each year."]}]},"context":{"countries":["TH"],"region":"Thailand","continent":"asia","languages":["th"],"period":"contemporary"},"tags":["traditions","Thailand"],"sources":[{"organization":"Wikipedia","title":{"ar":"Songkran (Thailand)","de":"Songkran (Thailand)","en":"Songkran (Thailand)"},"url":"https://en.wikipedia.org/wiki/Songkran_(Thailand)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Thailand","de":"Culture of Thailand","en":"Culture of Thailand"},"url":"https://en.wikipedia.org/wiki/Culture_of_Thailand","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الصباح الأول، تسكب عائلة ماءً معطراً بالياسمين على أيدي الأجداد، ثم ينضم الأطفال إلى الشارع حيث تحمل الشاحنات براميل الماء ويبتل المارة.","de":"Am ersten Morgen gießt eine Familie jasminduftendes Wasser über die Hände der Großeltern; später mischen sich die Kinder unter die Menge, wo Pick-ups Wasserfässer transportieren und Passanten durchnässen.","en":"On the first morning a family pours jasmine-scented water over the hands of grandparents, then children join the street where pickup trucks carry barrels of water and passers-by get soaked."},"misunderstanding":{"ar":"يظن البعض أن سونغكران مجرد حرب ماء، لكنه في الأساس مناسبة عائلية ودينية.","de":"Viele halten Songkran für eine reine Wasserschlacht, doch es ist vor allem ein Familien- und Tempelfest.","en":"Many think Songkran is just a water fight, but it is primarily a family and temple occasion."},"comparison":{"ar":"يشبه سونغكران أعياد رأس السنة التي تجمع العائلة، لكنه يتميز بطقس الماء كبركة.","de":"Songkran ähnelt anderen Neujahrsfesten, bei denen Familien zusammenkommen, doch der Wassersegen ist einzigartig.","en":"Songkran resembles other New Year celebrations that bring families together, but its water blessing is distinct."}},{"id":"asa-053","version":2,"slug":"tet-the-new-year-that-sends-everyone-home","contentType":"scene","category":"traditions","title":{"ar":"تيت: عيد يعيد الجميع إلى الديار","de":"Tết: das Neujahrsfest, das alle nach Hause bringt","en":"Tết: the new year that sends everyone home"},"deck":{"ar":"عيد رأس السنة القمري الفيتنامي ليس مجرد مناسبة، بل رحلة حتمية إلى البيت والعائلة.","de":"Vietnams Mondneujahr ist weit mehr als ein Feiertag – es ist die jährliche Heimkehr zu Familie und Herkunft.","en":"Vietnam's Lunar New Year is more than a holiday—it's an annual journey back to family and roots."},"teaser":{"ar":"في فيتنام، تيت هو العيد الذي تتوقف فيه الحياة اليومية لتعود العائلات إلى قرىها ومدنها الأصلية.","de":"In Vietnam bringt Tết das Alltagsleben zum Stillstand, damit Familien in ihre Heimatdörfer und -städte zurückkehren können.","en":"In Vietnam, Tết brings everyday life to a halt so families can return to their home towns and villages."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقوس البيت والعائلة","paragraphs":["تيت هو رأس السنة القمرية الفيتنامية، العيد العائلي المركزي في السنة، حيث يعود الناس إلى مسقط رأسهم وقرى أجدادهم.","تُنظف المنازل، وتُزيَّن مذابح الأسلاف بالفواكه والزهور، ويُختار أول زائر في السنة بعناية لأن شخصيته يُعتقد أنها تؤثر على حظ الأسرة.","تُحضَّر الأطعمة قبل أيام: بان تشونغ (كعكات الأرز الدبق المربعة)، والبصل المخلل، والفواكه المجففة، وصينية الفواكه الخمس."]},{"heading":"الاحتفال والتقاليد","paragraphs":["يتلقى الأطفال مظاريف حمراء تسمى لي سي تحتوي على نقود، وتزور العائلات القبور والمعابد؛ الأيام الأولى مخصصة للأقارب، والأيام اللاحقة للأصدقاء.","تصل حركة المرور والطلب على السفر إلى ذروتها قبل العيد، وقد مددت الحكومة العطلات وشجعت حملات السلامة على الطرق.","تختلف العادات بين شمال فيتنام وجنوبها وبين المجتمعات الدينية، وبعض العائلات الحضرية تبقى في المدينة، لكن فوضى السفر جزء من القصة الوطنية المشتركة."]}],"de":[{"heading":"Rituale rund um Haus und Familie","paragraphs":["Tết ist das vietnamesische Mondneujahr, der zentrale Familienfeiertag des Jahres, an dem Menschen in ihre Heimatstädte und Dörfer zurückkehren.","Häuser werden geputzt, Ahnengedenkstätten mit Obst und Blumen geschmückt, und der erste Besucher des Jahres wird sorgfältig ausgewählt, da sein Charakter das Glück des Haushalts beeinflussen soll.","Essen wird Tage im Voraus zubereitet: bánh chưng (quadratische Klebreiskuchen), eingelegte Zwiebeln, Trockenfrüchte und eine Schale mit fünf Früchten."]},{"heading":"Feiern und Traditionen","paragraphs":["Kinder erhalten rote Umschläge namens lì xì mit Geld, und Familien besuchen Gräber und Tempel; die ersten Tage sind den Verwandten vorbehalten, spätere Tage den Freunden.","Verkehr und Reisenachfrage erreichen vor dem Fest ihren Höhepunkt, und die Regierung hat die Feiertage verlängert und Kampagnen für Verkehrssicherheit gefördert.","Die Bräuche unterscheiden sich zwischen Nord- und Südvietnam sowie zwischen religiösen Gemeinschaften; manche Stadtfamilien bleiben in der Stadt, doch das Reisechaos gehört zur gemeinsamen nationalen Geschichte."]}],"en":[{"heading":"Rituals of home and family","paragraphs":["Tết is the Vietnamese Lunar New Year, the year's central family holiday, when people return to their home towns and villages.","Homes are cleaned, ancestral altars are set with fruit and flowers, and the first visitor of the year is chosen carefully because their character is believed to influence the household's luck.","Food is prepared days ahead: bánh chưng (square sticky-rice cakes), pickled onions, dried fruit and a tray of five fruits."]},{"heading":"Celebrations and traditions","paragraphs":["Children receive red envelopes called lì xì with money, and families visit graves and temples; the first days are reserved for relatives, later days for friends.","Traffic and travel demand peak before the holiday, and the government has extended holidays and encouraged road-safety campaigns.","Customs vary between north and south Vietnam and among religious communities; urban families sometimes stay in the city, and travel chaos is part of the shared national story."]}]},"context":{"countries":["VN"],"region":"Vietnam","continent":"asia","languages":["vi"],"period":"contemporary"},"tags":["traditions","Vietnam"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tết","de":"Tết","en":"Tết"},"url":"https://en.wikipedia.org/wiki/T%E1%BA%BFt","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Vietnam","de":"Culture of Vietnam","en":"Culture of Vietnam"},"url":"https://en.wikipedia.org/wiki/Culture_of_Vietnam","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة في مدينة هو تشي مينه تحمل فرع خوخ وبان تشونغ على دراجة نارية، وتسافر 500 كيلومتر إلى قرية في دلتا ميكونغ، وتصل في الوقت المناسب لتنظيف مذبح الأسلاف قبل منتصف الليل.","de":"Eine Familie in Ho-Chi-Minh-Stadt belädt ein Motorrad mit einem Pfirsichzweig und bánh chưng, fährt 500 km in ein Dorf im Mekong-Delta und kommt rechtzeitig an, um vor Mitternacht den Ahnenaltar zu reinigen.","en":"A family in Ho Chi Minh City loads a motorbike with a peach branch and bánh chưng, rides 500 km to a Mekong village, and arrives in time to clean the ancestral altar before midnight."},"misunderstanding":{"ar":"يُفهم تيت أحيانًا كعيد ديني فقط، لكنه في جوهره مناسبة عائلية واجتماعية تشمل جميع الفيتناميين بغض النظر عن معتقداتهم.","de":"Tết wird manchmal nur als religiöses Fest verstanden, doch im Kern ist es ein Familien- und Gesellschaftsfest für alle Vietnamesen, unabhängig vom Glauben.","en":"Tết is sometimes seen as purely a religious festival, but it is essentially a family and social occasion for all Vietnamese, regardless of belief."},"comparison":{"ar":"يشبه تيت عيد النوروز في آسيا الوسطى أو رأس السنة الصينية من حيث العودة إلى الوطن وتجديد الروابط الأسرية.","de":"Tết ähnelt dem Nowruz in Zentralasien oder dem chinesischen Neujahr, da es die Rückkehr in die Heimat und die Erneuerung familiärer Bindungen betont.","en":"Tết resembles Nowruz in Central Asia or Chinese New Year in its emphasis on returning home and renewing family ties."}},{"id":"asa-054","version":2,"slug":"vietnamese-pronouns-why-i-depends-on-who-you-are-talking-to","contentType":"language","category":"languages","title":{"ar":"الضمائر الفيتنامية: لماذا يعتمد \"أنا\" على من تخاطب","de":"Vietnamesische Pronomen: Warum „Ich“ davon abhängt, mit wem du sprichst","en":"Vietnamese pronouns: why I depends on who you are talking to"},"deck":{"ar":"في الفيتنامية، اختيار الضمير ليس مجرد مسألة نحوية، بل هو مرآة للعلاقة الاجتماعية والعمر والمكانة.","de":"In Vietnam ist die Wahl des Pronomens keine reine Grammatikfrage, sondern spiegelt Beziehung, Alter und Status wider.","en":"In Vietnamese, pronoun choice is not just grammar—it reflects relationship, age, and status."},"teaser":{"ar":"كيف يحدد عمر المستمع ومكانته الاجتماعية شكل الضمير الذي تستخدمه في الفيتنامية، ولماذا قد يسألك شخص عن عمرك قبل أن يسألك عن اسمك.","de":"Wie Alter und sozialer Status des Zuhörers die Pronomenwahl im Vietnamesischen bestimmen und warum manche dich zuerst nach deinem Alter fragen, bevor sie deinen Namen wissen.","en":"How the listener's age and social position shape the pronoun you use in Vietnamese, and why someone may ask your age before your name."},"readingMinutes":1,"sections":{"ar":[{"heading":"الضمائر كألقاب عائلية","paragraphs":["في اللغة الفيتنامية، الضمائر ليست مجرد كلمات مثل \"أنا\" و\"أنت\"، بل هي ألقاب عائلية. فالمتحدث يسمي نفسه \"em\" (الأخ الأصغر) أو \"anh\" (الأخ الأكبر) أو \"chi\" (الأخت الكبرى) اعتمادًا على عمر المستمع وعلاقته به، وليس على جنس المتحدث وحده. هذا يعني أن نفس الشخص يمكن أن يكون \"أنا\" بعدة طرق في يوم واحد، وتغيير الضمير يغير المسافة العاطفية في المحادثة."]},{"heading":"احترام يظهر في الكلمات","paragraphs":["تضاف أدوات التأدب مثل \"ạ\" و\"dạ\" لإظهار الاحترام، خاصة لكبار السن وفي سياقات الخدمة الرسمية. ولأن الخطأ في العلاقة العمرية قد يسبب الإساءة، فإن الفيتناميين غالبًا ما يسألون عن عمر أو سنة ميلاد الشخص الذي قابلوه حديثًا. في المدن، يستعير الشباب كلمات إنجليزية مثل \"you\" و\"I\" في الرسائل النصية غير الرسمية، كما أن الإنترنت أنتج أشكالًا جديدة للمخاطبة. يختلف الاستخدام حسب المنطقة والجيل والسياق، وليس النظام جامدًا؛ فالمتحدثون يتفاوضون على الضمائر لتغيير النبرة، والفيتناميون المغتربون يكيفونها مع اللغات المحلية."]}],"de":[{"heading":"Pronomen als Verwandtschaftsbezeichnungen","paragraphs":["Im Vietnamesischen sind Pronomen keine bloßen Wörter für „ich“ und „du“, sondern Verwandtschaftsbezeichnungen. Ein Sprecher nennt sich selbst „em“ (jüngeres Geschwister), „anh“ (älterer Bruder) oder „chi“ (ältere Schwester), je nach Alter und Beziehung des Zuhörers, nicht allein nach dem Geschlecht. Das bedeutet, dieselbe Person kann an einem Tag auf mehrere Arten „ich“ sein, und ein Pronomenwechsel verändert die emotionale Distanz im Gespräch."]},{"heading":"Respekt, der in Worten sichtbar wird","paragraphs":["Höflichkeitspartikeln wie „ạ“ und „dạ“ werden hinzugefügt, um Respekt zu zeigen, besonders gegenüber Älteren und in formellen Dienstleistungssituationen. Da ein Fehler in der Altersbeziehung beleidigend wirken kann, fragen Vietnamesen neue Bekannte oft früh nach Alter oder Geburtsjahr. In der Stadt leihen sich junge Leute beim informellen Texten englische Wörter wie „you“ und „I“, und das Internet hat neue Anredeformen hervorgebracht. Der Gebrauch variiert je nach Region, Generation und Situation, und das System ist nicht starr: Sprecher verhandeln Pronomen, um den Ton zu ändern, und Auslandsvietnamesen passen es an lokale Sprachen an."]}],"en":[{"heading":"Pronouns as kinship terms","paragraphs":["In Vietnamese, pronouns are not just words for 'I' and 'you'—they are kinship terms. A speaker calls themselves em (younger sibling), anh (older brother) or chi (older sister) depending on the listener's age and relationship, not on gender alone. This means the same person can be 'I' in several ways in one day, and switching pronouns changes the emotional distance of a conversation."]},{"heading":"Respect shown in words","paragraphs":["Politeness particles such as a and da are added to show respect, especially to elders and in formal service settings. Getting the age relationship wrong can cause offence, so Vietnamese often ask a new acquaintance's age or year of birth early. Young urban speakers borrow English you and I in casual texting, and the internet has produced new address forms. Usage varies by region, generation and setting, and the system is not rigid: speakers negotiate pronouns to change tone, and overseas Vietnamese adapt it to local languages."]}]},"context":{"countries":["VN"],"region":"Vietnam","continent":"asia","languages":["vi"],"period":"contemporary"},"tags":["languages","Vietnam"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pronouns in Vietnamese","de":"Pronouns in Vietnamese","en":"Pronouns in Vietnamese"},"url":"https://en.wikipedia.org/wiki/Pronouns_in_Vietnamese","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Vietnamese language","de":"Vietnamese language","en":"Vietnamese language"},"url":"https://en.wikipedia.org/wiki/Vietnamese_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"مساعد متجر يحيي عميلًا أكبر سنًا بلقب \"anh\" أو \"chi\"، ويسمي نفسه \"em\"، ويضيف أداة تأدب في نهاية الجمل؛ مع صديق في نفس العمر، كان سيستخدم \"toi\" و\"ban\".","de":"Eine Verkäuferin begrüßt eine ältere Kundin als „anh“ oder „chi“, nennt sich selbst „em“ und fügt am Satzende eine Höflichkeitspartikel hinzu; mit einem gleichaltrigen Freund würde sie zu „toi“ und „ban“ wechseln.","en":"A shop assistant greets an older customer as anh or chi, calls herself em, and adds a polite particle at the end of sentences; with a friend of the same age she would switch to toi and ban."},"misunderstanding":{"ar":"يعتقد بعض الأجانب أن الضمائر الفيتنامية ثابتة مثل ضمائر اللغات الأوروبية، لكنها في الواقع تتغير حسب العلاقة والعمر، وقد يبدو استخدام الضمير الخطأ غير مهذب أو حتى مسيءًا.","de":"Manche Ausländer glauben, vietnamesische Pronomen seien fest wie in europäischen Sprachen, doch sie ändern sich je nach Beziehung und Alter, und das falsche Pronomen kann unhöflich oder sogar beleidigend wirken.","en":"Some foreigners assume Vietnamese pronouns are fixed like in European languages, but they shift with relationship and age, and using the wrong one can seem rude or even offensive."},"comparison":{"ar":"على عكس الإنجليزية التي تستخدم \"I\" و\"you\" بشكل ثابت، تتطلب الفيتنامية من المتحدث أن يحدد موقعه الاجتماعي بالنسبة للمستمع في كل محادثة.","de":"Anders als im Englischen, wo „I“ und „you“ feststehen, muss der Sprecher im Vietnamesischen in jedem Gespräch seine soziale Position zum Zuhörer bestimmen.","en":"Unlike English, where 'I' and 'you' are fixed, Vietnamese requires the speaker to locate their social position relative to the listener in every conversation."},"expression":{"original":"Dạ","language":"tiếng Việt","gloss":{"ar":"أداة تأدب تستخدم عند الرد على شخص أكبر سنًا أو لإظهار الاحترام","de":"Höflichkeitspartikel, die beim Antworten gegenüber Älteren oder zur Ehrerbietung verwendet wird","en":"polite particle used when answering an elder or showing deference"},"usage":{"ar":"تستخدم في بداية الرد أو في نهاية الجملة لإظهار الأدب، خاصة مع كبار السن.","de":"Wird am Anfang einer Antwort oder am Satzende verwendet, um Höflichkeit zu zeigen, besonders gegenüber Älteren.","en":"Used at the start of a reply or at the end of a sentence to show politeness, especially to elders."},"transliteration":"dạ"}},{"id":"asa-055","version":2,"slug":"ao-dai-the-vietnamese-tunic-that-became-a-school-uniform","contentType":"note","category":"clothing-and-design","title":{"ar":"Áo dài: الزي الفيتنامي الذي أصبح زيًا مدرسيًا","de":"Áo dài: Die vietnamesische Tunika als Schuluniform","en":"Áo dài: The Vietnamese tunic that became a school uniform"},"deck":{"ar":"كيف تحول رداء حريري طويل إلى رمز للأناقة والانضباط في المدارس الفيتنامية.","de":"Wie eine lange Seidentunika zum Symbol für Eleganz und Disziplin in vietnamesischen Schulen wurde.","en":"How a long silk tunic turned into a symbol of elegance and discipline in Vietnamese schools."},"teaser":{"ar":"في فيتنام، يعكس Áo dài الهوية والاحترام، لكن ارتداءه يوميًا يثير نقاشات حول التكلفة والعملية.","de":"In Vietnam steht Áo dài für Identität und Respekt, doch das Tragen im Alltag wirft Fragen zu Kosten und Praktikabilität auf.","en":"In Vietnam, the áo dài reflects identity and respect, yet wearing it daily raises debates about cost and practicality."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الزي التقليدي إلى الزي المدرسي","paragraphs":["Áo dài هو رداء حريري طويل محكم يلبسه الرجال والنساء فوق بنطال، ويُعرف بأنه الزي الفيتنامي الأبرز. شكله الحديث تم الترويج له في الثلاثينيات والخمسينيات، ثم أصبح زيًا موحدًا للعديد من المدارس الثانوية للبنات في جنوب فيتنام ثم في جميع أنحاء البلاد.","يرتبط الرداء بالأناقة والتواضع، وتسمح شقوقه الجانبية الطويلة بالحركة مع تغطية الجسم. وهو علامة على الرسمية: المعلمون والمضيفات والعرائس والمشاركون في المهرجانات يرتدون نسخًا بألوان وأقمشة مختلفة."]},{"heading":"تقاليد متجددة ونقاشات مستمرة","paragraphs":["تتكرر النقاشات حول ما إذا كان يجب أن يكون الزي المدرسي إلزاميًا، نظرًا للتكلفة والعملية، بينما يواصل المصممون تحديث القصة. تختلف الأنماط والقواعد حسب المنطقة والمدرسة والمناسبة، وكثير من الطلاب يرتدون الزي فقط في الأيام الخاصة؛ فالرداء ليس لباسًا يوميًا لمعظم الفيتناميين."]}],"de":[{"heading":"Von der traditionellen Kleidung zur Schuluniform","paragraphs":["Áo dài ist eine eng anliegende, lange Seidentunika mit hohen Seitenschlitzen, die von Frauen und Männern über Hosen getragen wird und als das bekannteste vietnamesische Kleidungsstück gilt. Ihre moderne Form wurde in den 1930er und 1950er Jahren gefördert und wurde zur Uniform vieler Mädchenschulen in Südvietnam und später im ganzen Land.","Das Kleid gilt als Zeichen von Anmut und Bescheidenheit; die langen Schlitze ermöglichen Bewegung und bedecken den Körper. Es ist ein Zeichen von Förmlichkeit: Lehrer, Flugbegleiterinnen, Bräute und Festbesucher tragen Versionen in verschiedenen Farben und Stoffen."]},{"heading":"Lebendige Tradition und anhaltende Debatten","paragraphs":["Debatten darüber, ob Schuluniformen obligatorisch sein sollten, kehren wegen Kosten und Praktikabilität wieder, während Designer den Schnitt weiter modernisieren. Stile und Regeln unterscheiden sich je nach Region, Schule und Anlass, und viele Schüler tragen die Uniform nur an besonderen Tagen; für die meisten Vietnamesen ist das Kleid keine Alltagskleidung."]}],"en":[{"heading":"From traditional dress to school uniform","paragraphs":["The áo dài is a close-fitting silk tunic with long side slits, worn over trousers by both women and men, and it is the best-known Vietnamese garment. Its modern form was promoted in the 1930s and 1950s, and it became the uniform of many girls' secondary schools in South Vietnam and later across the country.","The dress is associated with grace and modesty, and its long slits allow movement while covering the body. Wearing it is a mark of formality: teachers, flight attendants, brides and festival-goers wear versions in different colours and fabrics."]},{"heading":"Living tradition and ongoing debates","paragraphs":["Debates recur about whether school uniforms should be mandatory, given cost and practicality, and designers keep modernising the cut. Styles and rules differ by region, school and occasion, and many students wear uniforms only on special days; the dress is not everyday wear for most Vietnamese."]}]},"context":{"countries":["VN"],"region":"Vietnam","continent":"asia","languages":["vi"],"period":"contemporary"},"tags":["clothing-and-design","Vietnam"],"sources":[{"organization":"Wikipedia","title":{"ar":"Áo dài","de":"Áo dài","en":"Áo dài"},"url":"https://en.wikipedia.org/wiki/%C3%81o_d%C3%A0i","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Vietnamese clothing","de":"Vietnamese clothing","en":"Vietnamese clothing"},"url":"https://en.wikipedia.org/wiki/Vietnamese_clothing","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حفل تخرج ثانوي في هيو، تصطف الفتيات بالÁo dài الأبيض والأولاد بنسخ داكنة لالتقاط الصور بينما يشرف المعلمون بنسخ حريرية.","de":"Bei einer High-School-Abschlussfeier in Hue stehen Mädchen in weißen Áo dài und Jungen in dunklen Versionen für Fotos Schlange, während Lehrer in Seidenversionen Aufsicht führen.","en":"At a high-school graduation in Hue, girls in white áo dài and boys in dark versions line up for photographs while teachers in silk versions supervise."},"misunderstanding":{"ar":"يعتقد البعض أن Áo dài يُلبس يوميًا، لكنه في الواقع زي مناسب للمناسبات الرسمية والمدارس في أيام محددة.","de":"Manche glauben, Áo dài werde täglich getragen, doch tatsächlich ist es formelle Kleidung für besondere Anlässe und Schultage.","en":"Some assume the áo dài is worn daily, but it is actually formal attire for occasions and specific school days."},"comparison":{"ar":"مثل الزي المدرسي في بعض الدول، يحمل Áo dài دلالة على الانتماء والاحترام، لكنه يتميز بكونه قطعة تراثية متجددة.","de":"Wie Schuluniformen in anderen Ländern vermittelt Áo dài Zugehörigkeit und Respekt, ist aber ein sich erneuerndes Erbstück.","en":"Like school uniforms elsewhere, the áo dài signals belonging and respect, but it stands out as a renewing heritage piece."}},{"id":"asa-056","version":2,"slug":"thanaka-the-yellow-paste-that-protects-and-decorates-a-myanmar-face","contentType":"note","category":"everyday-life","title":{"ar":"ثاناكا: عجينة صفراء تحمي الوجه وتزينه","de":"Thanaka: gelbe Paste schützt und schmückt Gesichter","en":"Thanaka: The Yellow Paste That Protects and Decorates"},"deck":{"ar":"في ميانمار، يطحن الناس لحاء الأشجار على حجر مسطح بالماء ليصنعوا عجينة ثاناكا، التي تحمي من الشمس وتبقي الوجه بارداً وتزينه.","de":"In Myanmar mahlen Menschen die Rinde mehrerer Bäume mit Wasser auf einem flachen Stein zu Thanaka-Paste, die vor Sonne schützt, kühlt und das Gesicht schmückt.","en":"In Myanmar, people grind tree bark with water on a flat stone to make thanaka paste, which protects from the sun, cools the skin, and decorates the face."},"teaser":{"ar":"عادة يومية عمرها قرون: عجينة صفراء من لحاء الأشجار تحمي البشرة وتزين الوجوه في ميانمار، وتُعدّ طقساً اجتماعياً تتعلمه الأطفال.","de":"Jahrhundertealte Alltagsroutine: Eine gelbe Paste aus Baumrinde schützt die Haut und schmückt Gesichter in Myanmar – ein soziales Ritual, das Kinder früh lernen.","en":"A centuries-old daily routine: yellow paste from tree bark protects skin and decorates faces in Myanmar, a social ritual children learn early."},"readingMinutes":1,"sections":{"ar":[{"heading":"كيف تُصنع الثاناكا وتُستخدم","paragraphs":["تُصنع عجينة ثاناكا عن طريق طحن لحاء عدة أنواع من الأشجار على حجر مسطح مع الماء. ثم تُدهن على الوجه والذراعين. تستخدمها النساء والأطفال يومياً، غالباً في دوائر أنيقة أو أنماط تشبه الأوراق.","تُستخدم للحماية من الشمس والتبريد والعناية بالبشرة والزينة. يختلف الاستخدام حسب المنطقة والعمر والطبقة؛ فالرجال والأولاد يستخدمونها أقل، وبعض المهنيين في المدن يضعونها فقط في المهرجانات أو يتجنبونها في مكاتب العمل."]},{"heading":"طقس اجتماعي وصورة وطنية","paragraphs":["تطبيق الثاناكا طقس اجتماعي: يتعلم الأطفال طحن اللحاء، وقد تحضر الأم العجينة لكل أفراد الأسرة في الصباح. هذه الممارسة قديمة جداً وتظهر في الفن والشعر البورمي، والوجه المخطط بالثاناكا صورة شائعة في الإعلام المحلي."]}],"de":[{"heading":"Herstellung und Anwendung","paragraphs":["Thanaka-Paste entsteht, indem man die Rinde mehrerer Baumarten mit Wasser auf einem flachen Stein mahlt. Sie wird auf Gesicht und Arme aufgetragen. Viele Frauen und Kinder tragen sie täglich, oft in sauberen Kreisen oder Blattmustern.","Sie dient als Sonnenschutz, Kühlung, Hautpflege und Dekoration. Die Verwendung variiert je nach Region, Alter und Klasse; Männer und Jungen nutzen sie seltener, und manche Stadtberufler tragen sie nur zu Festen oder meiden sie im Büro."]},{"heading":"Soziales Ritual und nationales Bild","paragraphs":["Das Auftragen ist ein soziales Ritual: Kinder lernen das Mahlen der Rinde, und eine Mutter bereitet morgens oft Paste für die ganze Familie zu. Die Praxis ist jahrhundertealt und erscheint in burmesischer Kunst und Poesie; ein von Thanaka gestreiftes Gesicht ist ein vertrautes Bild in lokalen Medien."]}],"en":[{"heading":"How Thanaka Is Made and Used","paragraphs":["Thanaka paste is made by grinding the bark of several trees on a flat stone with water, then applied to the face and arms. Many women and children wear it daily, often in neat circles or leaf patterns.","It is used for sun protection, cooling, skin care, and decoration. Use varies by region, age, and class; men and boys use it less often, and some urban professionals wear it only at festivals or avoid it in office settings."]},{"heading":"A Social Ritual and National Image","paragraphs":["Application is a social ritual: children learn to grind the bark, and a mother may prepare paste for the whole family in the morning. The practice is centuries old and appears in Burmese art and poetry; a face streaked with thanaka is a common image of Myanmar in local media."]}]},"context":{"countries":["MM"],"region":"Myanmar","continent":"asia","languages":["my"],"period":"contemporary"},"tags":["everyday-life","Myanmar"],"sources":[{"organization":"Wikipedia","title":{"ar":"Thanaka","de":"Thanaka","en":"Thanaka"},"url":"https://en.wikipedia.org/wiki/Thanaka","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Myanmar","de":"Myanmar","en":"Myanmar"},"url":"https://en.wikipedia.org/wiki/Myanmar","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"فتاة في ماندالاي تطحن اللحاء على حجر مستدير مع قطرات ماء، وتنشر دائرة صفراء على كل وجنة قبل المدرسة، ثم تحمل الحجر إلى كشك العائلة لاحقاً.","de":"Ein Mädchen in Mandalay mahlt Rinde mit Wassertropfen auf einem runden Stein, streicht vor der Schule einen gelben Kreis auf jede Wange und trägt den Stein später zum Familienstand.","en":"A girl in Mandalay grinds bark on a round stone with drops of water, spreads a yellow circle on each cheek before school, and carries the stone to the family's stall later."},"misunderstanding":{"ar":"يعتقد البعض أن الثاناكا مجرد مستحضر تجميلي، لكنها في الواقع وسيلة حماية من الشمس وعناية بالبشرة وطقس اجتماعي متوارث.","de":"Manche halten Thanaka für reine Kosmetik, doch tatsächlich ist sie Sonnenschutz, Hautpflege und ein überliefertes soziales Ritual.","en":"Some think thanaka is just cosmetics, but it is actually sun protection, skin care, and an inherited social ritual."},"comparison":{"ar":"مثلما يضع الناس واقي الشمس يومياً في بلدان أخرى، تضع الأسر في ميانمار الثاناكا كجزء من روتين الصباح، لكنها هنا أيضاً علامة جمال وترابط أسري.","de":"So wie Menschen anderswo täglich Sonnencreme auftragen, gehört Thanaka in Myanmar zur Morgenroutine – ist dort aber auch Schönheitszeichen und Familienbindung.","en":"Just as people elsewhere apply sunscreen daily, families in Myanmar include thanaka in their morning routine—but here it is also a mark of beauty and family bonding."}},{"id":"asa-057","version":2,"slug":"thingyan-the-burmese-new-year-of-water-and-merit","contentType":"scene","category":"traditions","title":{"ar":"ثينغيان: ماء العام الجديد في ميانمار","de":"Thingyan: Wasser und Verdienst zum neuen Jahr","en":"Thingyan: water, merit and the Burmese new year"},"deck":{"ar":"في منتصف أبريل يرشّ البورميون الماء ويغسلون رؤوس كبار السن، فيمزجون الاحتفال بالعام الجديد بفعل الخير البوذي.","de":"Mitte April übergießen Burmesen einander mit Wasser, waschen Älteren die Haare und verbinden so Neujahr mit buddhistischem Verdienst.","en":"In mid-April Burmese people throw water, wash elders' hair and give alms, mixing new-year celebration with Buddhist merit-making."},"teaser":{"ar":"عيد رأس السنة البورمي يمتد أياماً في منتصف أبريل، حيث يرمي الناس الماء لطرد العام القديم، ويجتمعون حول الموائد والمنصات الموسيقية.","de":"Das burmesische Neujahrsfest dauert Mitte April mehrere Tage: Wasser wäscht das alte Jahr fort, Straßenbühnen feiern, Familien besuchen Tempel.","en":"Thingyan lasts several days in mid-April: water washes away the old year, street stages host crowds, and families visit temples and share festive food."},"readingMinutes":1,"sections":{"ar":[{"heading":"ماء يغسل العام القديم","paragraphs":["يُقام عيد ثينغيان في منتصف أبريل على مدى عدة أيام، حين يُرشّ الماء ويُسكب لغسل العام المنصرم. وفي المدن تُنصب منصات فيها خراطيم وموسيقى، فتغمر الحشود المارّة بالماء، وتعمّ الولائم وحلوى الأرز البورمية «مون لون ياي باو».","لكن الماء في جوهره فعل خير بوذي: تغسل العائلات تماثيل بوذا، وتغسل شعر كبار السن، وتقدّم الطعام والصدقات للرهبان. وتختلف الممارسة بين المدن والقرى والجماعات البوذية، فصورة الحفلة الشارعية تطغى على التغطية الأجنبية، بينما تبقى الطقوس الدينية والعائلية محوراً لكثيرين."]},{"heading":"صمت اليوم الأول","paragraphs":["يبدأ العام الجديد بعد مهرجان الماء، ويُستقبل في كثير من البيوت بالصمت وزيارة المعابد. وقد عُطّل ثينغيان أو قُيّد أثناء جائحة كوفيد-19 وتحت قيود أمنية بعد انقلاب 2021، فيما يواصل كثيرون إحياءه في نطاق خاص.","وتتباين الملاحظة أيضاً بين الأجيال: فالشباب ينجذبون إلى المنصات والرشّ الجماعي، بينما يتمسّك كبار السن بالزيارات والغسل الهادئ في البيت."]}],"de":[{"heading":"Wasser wäscht das alte Jahr fort","paragraphs":["Thingyan wird Mitte April über mehrere Tage gefeiert, wenn Wasser geworfen und gegossen wird, um das alte Jahr abzuwaschen. In Städten entstehen Pandals mit Schläuchen und Musik, Menschenmengen durchnässen Passanten, und es wird gefeiert mit Festessen und dem burmesischen Snack Mont Lone Yay Paw.","Doch das Wasser ist ursprünglich eine Handlung buddhistischen Verdiensterwerbs: Familien baden Buddha-Statuen, waschen älteren Menschen die Haare und geben Essen und Almosen an Mönche. Die Bräuche unterscheiden sich zwischen Städten, Dörfern und buddhistischen Gemeinschaften; das Bild der Straßenparty prägt ausländische Berichte, doch die religiösen und familiären Riten bleiben für viele zentral."]},{"heading":"Stille am ersten Tag","paragraphs":["Das neue Jahr beginnt nach dem Wasserfest und wird in vielen Haushalten mit Stille und Tempelbesuchen begrüßt. Während der COVID-19-Pandemie und unter Sicherheitsbeschränkungen nach dem Putsch von 2021 wurde Thingyan ausgesetzt oder eingeschränkt, viele Menschen begehen es weiterhin im Privaten.","Auch zwischen den Generationen unterscheidet sich die Praxis: Jüngere ziehen zu den Bühnen und kollektivem Übergießen, Ältere halten an stillen Besuchen und dem Waschen zu Hause fest."]}],"en":[{"heading":"Water that washes the old year away","paragraphs":["Thingyan is held over several days in mid-April, when water is thrown and poured to wash away the old year. Cities set up pandals with hoses and music, crowds douse passers-by, and the holiday brings feasts and the Burmese snack mont lone yay paw.","Yet the water is rooted in Buddhist merit-making: families bathe images of the Buddha, wash the hair of elders, and give food and alms to monks. Observances differ between cities, villages and Buddhist communities; the street-party image dominates foreign coverage, but the religious and family rites remain central for many."]},{"heading":"Silence on the first day","paragraphs":["The new year begins after the water festival, marked in many households by silence and temple visits. Thingyan was suspended or restricted during the COVID-19 pandemic and under security restrictions after the 2021 coup, while many people continue private observances.","Practice also shifts across generations: younger people are drawn to the pandals and collective soaking, while older relatives keep to quiet temple visits and washing at home."]}]},"context":{"countries":["MM"],"region":"Myanmar","continent":"asia","languages":["my"],"period":"contemporary"},"tags":["traditions","Myanmar"],"sources":[{"organization":"Wikipedia","title":{"ar":"Thingyan","de":"Thingyan","en":"Thingyan"},"url":"https://en.wikipedia.org/wiki/Thingyan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Burmese calendar","de":"Burmese calendar","en":"Burmese calendar"},"url":"https://en.wikipedia.org/wiki/Burmese_calendar","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في اليوم الأول من ثينغيان تسكب عائلة ماءً معطّراً على تمثال صغير لبوذا، وتغسل شعر عمة مسنّة، ثم ينضم الأطفال إلى منصة الشارع حيث يبلّلهم خرطوم.","de":"Am ersten Tag von Thingyan gießt eine Familie duftendes Wasser über eine kleine Buddha-Statue, wäscht einer älteren Tante die Haare, dann gehen die Kinder zur Straßenbühne, wo ein Schlauch alle durchnässt.","en":"On the first day of Thingyan a family pours scented water over a small Buddha image, washes an elderly aunt's hair, then children join the street pandal where a hose soaks everyone."},"misunderstanding":{"ar":"يظن كثيرون أن العيد مجرد معركة ماء صاخبة في الشارع، لكن غسل تماثيل بوذا وشعر الكبار والصدقات للرهبان هي جوهره الديني.","de":"Viele halten das Fest für eine laute Wasserschlacht, doch das Baden der Buddha-Statuen, das Haarwaschen der Älteren und Almosen an Mönche sind sein religiöser Kern.","en":"Many assume the festival is only a loud street water fight, but bathing Buddha images, washing elders' hair and giving alms to monks are its religious core."},"comparison":{"ar":"يشبه العيد مهرجانات الماء في تايلاند ولاوس، لكنه يمتاز بطابع بوذي عائلي هادئ في أول أيامه.","de":"Es ähnelt den Wasserfesten in Thailand und Laos, doch die stillen familiären Rituale der ersten Tage sind besonders burmesisch.","en":"It resembles the water festivals of Thailand and Laos, but the quiet family rites of the first days are distinctly Burmese."}},{"id":"asa-058","version":2,"slug":"shinbyu-the-ordination-that-turns-a-boy-into-a-little-monk","contentType":"note","category":"family-and-friendship","title":{"ar":"شينبيو: حين يصبح الصبي راهبًا صغيرًا","de":"Shinbyu: Wenn ein Junge Mönch wird","en":"Shinbyu: the making of a little monk"},"deck":{"ar":"احتفال عائلي بوذي يحوّل الأولاد بين السابعة والثالثة عشرة إلى مبتدئين في الدير، لفترة قصيرة غالبًا.","de":"Eine buddhistische Familienfeier, bei der Jungen zwischen sieben und dreizehn für kurze Zeit als Novizen in ein Kloster gehen.","en":"A Burmese family ceremony in which boys, usually seven to thirteen, are ordained as novice monks for a short stretch of days or months."},"teaser":{"ar":"شعر يُحلق وثوب أميري وموكب بالأجراس: طقس عائلي في ميانمار يعلن فضل الأسرة ويعلّم الصبي الانضباط.","de":"Kahlgeschorener Kopf, Prinzenkostüm und eine Prozession mit Trommlern: In Myanmar zeigt eine Familie so ihr Verdienst und lehrt den Sohn Disziplin.","en":"A shaved head, a prince's costume and a procession with drummers: one family's Buddhist merit, and a boy's first lesson in discipline."},"readingMinutes":1,"sections":{"ar":[{"heading":"من ثوب الأمير إلى ثوب الراهب","paragraphs":["في طقس شينبيو البورمي يُرسَل الأولاد، وعمرهم عادة بين السابعة والثالثة عشرة، للترهبن كمبتدئين مدة قصيرة، قد تكون أسبوعًا أو بضعة أشهر.","يحلق شعر الصبي ويُلبس زي أمير في موكب، ثم يلبس الثوب الراهب ويتلقى أول صدقة.","هذا الانتقال يجعل الطقس حدثًا عائليًا كبيرًا، لا مجرد خطوة دينية فردية."]},{"heading":"فضل الأسرة وتغيّر الأجيال","paragraphs":["يُعدّ شينبيو إعلانًا لفضل الأسرة البوذي، وكثيرًا ما يُقام مع طقوس ثقب الأذن للبنات.","تعتمد الأديرة على المبتدئين المؤقتين، والغاية أن يتعلم الصبي الانضباط والترتيل والتعاليم.","في العقود الأخيرة قلّصت الكلفة والتغيّرات الاجتماعية حجم بعض الاحتفالات، لكنه بقي طقس عبور شائعًا.","وتختلف التفاصيل بين المناطق والأجيال، وبين الأسر الغنية والأقل حظًا، فلا يُرهَّب كل صبي."]}],"de":[{"heading":"Vom Prinzengewand zur Robe","paragraphs":["Bei der burmesischen Shinbyu-Zeremonie werden Jungen, meist zwischen sieben und dreizehn Jahren, für kurze Zeit als Novizen ordiniert, oft für eine Woche oder einige Monate.","Dem Jungen wird der Kopf geschoren, er wird für eine Prozession als Prinz gekleidet und legt danach die Robe an und erhält seine erste Almosenschale.","Der Übergang macht die Zeremonie zu einem großen Familienereignis und nicht nur zu einem persönlichen religiösen Schritt."]},{"heading":"Verdienst der Familie und Wandel der Zeit","paragraphs":["Shinbyu gilt als Ausdruck des buddhistischen Verdienstes der Familie und wird häufig mit Ohrstechzeremonien für Mädchen gefeiert.","Klöster sind auf zeitweilige Novizen angewiesen; die Zeit soll Disziplin, Rezitation und die buddhistischen Gebote vermitteln.","In den letzten Jahrzehnten haben Kosten und sozialer Wandel manche Feiern verkleinert, doch Shinbyu bleibt ein verbreiteter Übergangsritus.","Regionale und familiäre Unterschiede sind groß, und nicht jeder Junge wird ordiniert."]}],"en":[{"heading":"From prince's costume to robe","paragraphs":["In the Burmese shinbyu ceremony, boys usually between seven and thirteen are ordained as novice monks for a short period, often a week or a few months.","The boy's head is shaved, he is dressed as a prince for a procession, and then he puts on the robe and receives alms.","That passage turns the day into a major family event rather than a private religious step."]},{"heading":"Family merit and changing times","paragraphs":["Shinbyu marks the family's Buddhist merit and is often held together with ear-piercing ceremonies for girls.","Monasteries depend on temporary novices, and the stay is meant to teach discipline, chanting and the Buddhist precepts.","In recent decades cost and social change have reduced the scale of some ceremonies, but shinbyu remains a common rite of passage.","Practice varies by region, generation and family wealth, and not every boy is ordained."]}]},"context":{"countries":["MM"],"region":"Myanmar","continent":"asia","languages":["my"],"period":"contemporary"},"tags":["family-and-friendship","Myanmar"],"sources":[{"organization":"Wikipedia","title":{"ar":"Shinbyu","de":"Shinbyu","en":"Shinbyu"},"url":"https://en.wikipedia.org/wiki/Shinbyu","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Buddhism in Myanmar","de":"Buddhism in Myanmar","en":"Buddhism in Myanmar"},"url":"https://en.wikipedia.org/wiki/Buddhism_in_Myanmar","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"صبي بزي أمير مزركش يجول على عربة في القرية مع الطبالين والأقارب؛ وفي الدير يبدّل ثوبه، يُحلق رأسه ويتسلم وعاء الصدقة الأول.","de":"Ein Junge im glitzernden Prinzenkostüm fährt mit Trommlern und Verwandten auf einem Wagen durchs Dorf; im Kloster wechselt er in die Robe, lässt sich den Kopf scheren und bekommt seine erste Almosenschale.","en":"A boy in a sequinned prince costume rides a cart through the village with drummers and relatives; at the monastery he changes into a robe, has his head shaved and receives his first alms bowl."},"misunderstanding":{"ar":"يظن البعض أن الترهبن قصير الأمد يعني التخلي عن الحياة العادية، لكنه في الواقع مرحلة تعليمية مؤقتة يعود بعدها الصبي إلى بيته.","de":"Manche halten die kurze Ordination für einen Abschied vom Alltagsleben, doch sie ist eine zeitlich begrenzte Lehrzeit, nach der der Junge heimkehrt.","en":"Outsiders sometimes assume a short ordination means leaving ordinary life behind, but it is a temporary period of learning after which the boy returns home."},"comparison":{"ar":"يشبه هذا الطقس طقوس العبور العائلية في مجتمعات أخرى، حيث يُعلن الانتقال إلى مرحلة جديدة أمام الجماعة لا في السر.","de":"Ähnlich wie andere familiäre Übergangsriten macht sie den neuen Status öffentlich sichtbar, statt ihn im Privaten zu belassen.","en":"Like other family rites of passage, it announces a new stage publicly, in front of the whole community, rather than quietly at home."}}];

export default { version: 2, items };
